INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候驾驶过过拖拉机。", "corrected_sentence": "我小时候驾驶过拖拉机。", "error_description": "体标重复：经历体“过”只用一次，应说“驾驶过拖拉机”，不能重复成“驾驶过过拖拉机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
