INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客机指用于运载旅客的民用航空飞机。", "primary_collocate": null, "pronunciation": "kè jī", "ipa": "kʰɤ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "值得注意的是，即便在自动驾驶与人工智能高度集成的现代客机中，空气动力学的基本物理规律依然不可违背。", "target_word": "客机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这架客机明天早上飞往北京。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里停着很多客机。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架客机能坐三百名乘客。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客机在云层上平稳地飞行。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次坐客机去上海。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客机上的空姐正在发饮料。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大型客机的票价通常比较贵。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大雾，客机晚点了两个小时。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂今年造出了一架新客机。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一架客机", "label": "量词"}, {"form": "客機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "运载旅客的民用飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12247, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确答案。kè jī 指运载旅客的民用飞机。"}, {"text": "科技", "is_correct": false, "explanation": "kē jì（第一声、第四声）两个音节的声调都与 kè jī 不同，意思是科学技术。"}, {"text": "柯基", "is_correct": false, "explanation": "kē jī（第一声）第一个音节的声调与 kè jī 不同，指柯基犬，不是飞机。"}, {"text": "客气", "is_correct": false, "explanation": "kè qi（轻声）第二个音节的声母和声调与 kè jī 不同，意思是有礼貌、不随便。"}, {"text": "课间", "is_correct": false, "explanation": "kè jiān（第四声、第一声）第二个音节的韵母与 kè jī 不同，意思是两节课之间的休息时间。"}], "explanations": {"客机": "正确答案。kè jī 指运载旅客的民用飞机。", "科技": "kē jì（第一声、第四声）两个音节的声调都与 kè jī 不同，意思是科学技术。", "柯基": "kē jī（第一声）第一个音节的声调与 kè jī 不同，指柯基犬，不是飞机。", "客气": "kè qi（轻声）第二个音节的声母和声调与 kè jī 不同，意思是有礼貌、不随便。", "课间": "kè jiān（第四声、第一声）第二个音节的韵母与 kè jī 不同，意思是两节课之间的休息时间。"}, "sentence_index": null, "correct_answer": "客机"}, "level_3": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确。客机是载客的民用飞机，可以自动驾驶，也涉及空气动力学，符合句中各项线索。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：空气动力学研究的是空气中物体的运动，轮船在水面航行，句中所说的规律不适用于它。"}, {"text": "潜艇", "is_correct": false, "explanation": "语义：潜艇在水下航行，与“空气动力学”所研究的空中运动不符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“自动驾驶”只用于车辆、飞行器等交通工具，不能用于手机。"}], "explanations": {"客机": "正确。客机是载客的民用飞机，可以自动驾驶，也涉及空气动力学，符合句中各项线索。", "轮船": "语义：空气动力学研究的是空气中物体的运动，轮船在水面航行，句中所说的规律不适用于它。", "潜艇": "语义：潜艇在水下航行，与“空气动力学”所研究的空中运动不符。", "手机": "搭配：“自动驾驶”只用于车辆、飞行器等交通工具，不能用于手机。"}, "sentence_index": 0, "correct_answer": "客机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这架客机专门用来运送三十吨货物。", "explanation": "这里应该用〈货机〉。客机专门载运旅客，运送货物要用货机。"}, {"text": "这架客机专门用来在海里捕鱼。", "explanation": "这里应该用〈渔船〉。客机在空中载运旅客，在海里捕鱼要用渔船。"}, {"text": "这架客机专门用来拍摄风景。", "explanation": "这里应该用〈无人机〉。客机用于载客，拍摄风景通常用无人机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12247, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确答案。kè jī 指运载旅客的民用飞机。"}, {"text": "课件", "is_correct": false, "explanation": "kè jiàn（第四声、第四声）第二个音节的韵母和声调与 kè jī 不同，指教学用的课件。"}, {"text": "克制", "is_correct": false, "explanation": "kè zhì（第四声、第四声）第二个音节的声母由 j 变为 zh，意思是控制自己的言行。"}, {"text": "开机", "is_correct": false, "explanation": "kāi jī（第一声）第一个音节的韵母和声调与 kè 不同，意思是启动机器。"}], "explanations": {"客机": "正确答案。kè jī 指运载旅客的民用飞机。", "课件": "kè jiàn（第四声、第四声）第二个音节的韵母和声调与 kè jī 不同，指教学用的课件。", "克制": "kè zhì（第四声、第四声）第二个音节的声母由 j 变为 zh，意思是控制自己的言行。", "开机": "kāi jī（第一声）第一个音节的韵母和声调与 kè 不同，意思是启动机器。"}, "sentence_index": null, "correct_answer": "客机"}, "level_3": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确。空姐是航班上的乘务员，客机上才会有空姐。"}, {"text": "货车", "is_correct": false, "explanation": "语义：货车用于运货，不载乘客，也没有空姐。"}, {"text": "卫星", "is_correct": false, "explanation": "语义：卫星在太空轨道上运行，不在航班上，句中的场景不合。"}, {"text": "公园", "is_correct": false, "explanation": "语义：空姐是航班上的乘务员，公园里没有空姐，句意不合。"}], "explanations": {"客机": "正确。空姐是航班上的乘务员，客机上才会有空姐。", "货车": "语义：货车用于运货，不载乘客，也没有空姐。", "卫星": "语义：卫星在太空轨道上运行，不在航班上，句中的场景不合。", "公园": "语义：空姐是航班上的乘务员，公园里没有空姐，句意不合。"}, "sentence_index": 6, "correct_answer": "客机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架客机专门用来拦截敌机。", "explanation": "这里应该用〈战斗机〉。客机载运旅客，拦截敌机要用战斗机。"}, {"text": "这架客机专门用来耕地。", "explanation": "这里应该用〈拖拉机〉。客机用于载运旅客，耕地要用拖拉机。"}, {"text": "这架客机在高速公路上行驶。", "explanation": "这里应该用〈卡车〉。客机是飞机，在天空中飞行，不在公路上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机场跑道上停着一只客机。", "corrected_sentence": "机场跑道上停着一架客机。", "error_description": "量词错误：“客机”是飞机，应该用量词“架”，不能用“只”（“只”多用于动物等）。错误形式是“一只客机”，正确形式是“一架客机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些客机们都是新买的。", "corrected_sentence": "这些客机都是新买的。", "error_description": "后缀错误：“们”用于指人，不能加在“客机”这类无生命的物体后面。错误形式是“客机们”，正确形式是“客机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵守", "is_correct": true, "explanation": "正确。“遵守”与“违背”互为反义词，都指是否按约定、规则去做。"}, {"text": "观察", "is_correct": false, "explanation": "不构成反义关系：“观察”指仔细看，与“违背”没有对立关系。"}, {"text": "赞美", "is_correct": false, "explanation": "不构成反义关系：“赞美”指表扬，与“违背”不是对立关系。"}, {"text": "保存", "is_correct": false, "explanation": "不构成反义关系：“保存”指留存，与“违背”没有对立关系。"}], "correct_answer": "遵守", "explanations": {"遵守": "正确。“遵守”与“违背”互为反义词，都指是否按约定、规则去做。", "观察": "不构成反义关系：“观察”指仔细看，与“违背”没有对立关系。", "赞美": "不构成反义关系：“赞美”指表扬，与“违背”不是对立关系。", "保存": "不构成反义关系：“保存”指留存，与“违背”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵从", "is_correct": true, "explanation": "正确。“遵从”与“违背”互为反义词，都指是否照着约定、规则去做。"}, {"text": "研究", "is_correct": false, "explanation": "不构成反义关系：“研究”指探究，与“违背”没有对立关系。"}, {"text": "散步", "is_correct": false, "explanation": "不构成反义关系：“散步”指行走消遣，与“违背”无关。"}, {"text": "鼓励", "is_correct": false, "explanation": "不构成反义关系：“鼓励”指支持、激励，与“违背”不是反义词。"}], "correct_answer": "遵从", "explanations": {"遵从": "正确。“遵从”与“违背”互为反义词，都指是否照着约定、规则去做。", "研究": "不构成反义关系：“研究”指探究，与“违背”没有对立关系。", "散步": "不构成反义关系：“散步”指行走消遣，与“违背”无关。", "鼓励": "不构成反义关系：“鼓励”指支持、激励，与“违背”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不遵守、不遵从（约定、规则、意愿等）。", "primary_collocate": null, "pronunciation": "wéi bèi", "ipa": "weɪ˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，即便在自动驾驶与人工智能高度集成的现代客机中，空气动力学的基本物理规律依然不可违背。", "target_word": "违背", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他违背了对朋友的承诺。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违背交通规则会受到处罚。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想学钢琴，父母不该违背他的意愿。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的做法违背了合同的约定。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做违背了我的原则。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有违背过自己的诺言。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违背法律的事情，我们不能做。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿违背父母的意愿，留在了老家。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违背比赛规则的人会失去资格。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违背了", "label": "完成体"}, {"form": "违背过", "label": "经历体"}, {"form": "違背", "label": "繁体"}], "register": "书面", "sense_fingerprint": "不遵守约定、规则或意愿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违背", "is_correct": true, "explanation": "正确。“违背”表示不遵守、不遵从，与“不可违背”的语境相符。"}, {"text": "发明", "is_correct": false, "explanation": "语义：物理规律是客观存在的，只能发现，不能发明，句意不合。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损的东西，规律不能被修补。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、燃料等，不能用于规律。"}], "explanations": {"违背": "正确。“违背”表示不遵守、不遵从，与“不可违背”的语境相符。", "发明": "语义：物理规律是客观存在的，只能发现，不能发明，句意不合。", "修补": "搭配：“修补”用于破损的东西，规律不能被修补。", "点燃": "搭配：“点燃”用于火、燃料等，不能用于规律。"}, "sentence_index": 0, "correct_answer": "违背"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他违背了窗外的雨，还是出门了。", "explanation": "这里应该用〈不顾〉。违背针对约定、规则或意愿，不能用于天气；“不顾下雨”才是正确说法。"}, {"text": "他违背了公司的财物，要赔偿。", "explanation": "这里应该用〈损坏〉。违背针对约定、规则，不能用于具体的物品。"}, {"text": "他违背了老师的尊严，大家都很生气。", "explanation": "这里应该用〈冒犯〉。违背针对约定、规则、意愿，尊严不能违背；伤害别人的尊严要说冒犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违背", "is_correct": true, "explanation": "正确。“违背过”表示曾经不遵守，与“从来没有”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“诺言”搭配，诺言不是可以吃的东西。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不能用于诺言。"}, {"text": "发掘", "is_correct": false, "explanation": "语义：“发掘”指挖掘、找出，诺言不是矿藏，句意不合。"}], "explanations": {"违背": "正确。“违背过”表示曾经不遵守，与“从来没有”的语境相符。", "吃": "搭配：“吃”不能与“诺言”搭配，诺言不是可以吃的东西。", "修理": "搭配：“修理”用于机器、物品，不能用于诺言。", "发掘": "语义：“发掘”指挖掘、找出，诺言不是矿藏，句意不合。"}, "sentence_index": 6, "correct_answer": "违背"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他违背了这次比赛的结果，大家都不服。", "explanation": "这里应该用〈接受〉。违背针对约定、规则、意愿，比赛结果不能违背，应该说接受。"}, {"text": "他违背了这把椅子，大家都觉得奇怪。", "explanation": "这里应该用〈搬动〉。违背针对约定、规则或意愿，不能用于具体物品；搬动椅子才是正确说法。"}, {"text": "她违背了这个邀请，大家都很理解。", "explanation": "这里应该用〈拒绝〉。违背针对的是约定、规则，拒绝邀请才是正确的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很违背了约定。", "corrected_sentence": "他故意违背了约定。", "error_description": "副词错误：“很”用来修饰形容词、表示程度，不能修饰动作“违背”。表示有意要做时应该用“故意”。错误形式是“很违背”，正确形式是“故意违背”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经违背了过约定。", "corrected_sentence": "他曾经违背过约定。", "error_description": "“了”与“过”重复：“违背过”已经表示曾经有过的经历，不能再加“了”。错误形式是“违背了过”，正确形式是“违背过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
