INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一定的方法控制或操作某个东西，让它按照自己的想法动。", "primary_collocate": null, "pronunciation": "cāo zòng", "ipa": "tsʰɑʊ˥ tsʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "飞行员或飞控系统所执行的所有操纵动作——无论是俯仰、滚转还是偏航——最终都归结为对气动力矩的精确调控。", "target_word": "操纵", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "有人在背后操纵这次比赛的结果。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总想操纵身边的朋友。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人操纵着市场价格，赚了很多钱。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司一直在操纵股票价格。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木偶师傅在幕后操纵着木偶，让它们跳舞。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑操纵机器人，让它拿起杯子。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让别人操纵你的选择。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人在幕后操纵一切。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想操纵公司的每一个决定。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "操纵着", "label": "体标"}, {"form": "操纵了", "label": "体标"}, {"form": "操纵者", "label": "复合"}, {"form": "操縱", "label": "繁体"}], "register": "书面", "sense_fingerprint": "操纵|控制事物使其按自己的意愿行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91d27849-f17d-475a-ae9e-30e433cef473') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操纵", "is_correct": true, "explanation": "正确：「操纵动作」指用一定方法控制飞行器的动作，与飞行员、飞控系统和精确调控的语境相符。"}, {"text": "跳跃", "is_correct": false, "explanation": "语义：「跳跃」指跳起、蹦起，与飞控系统对气动力矩的精确调控不相容。"}, {"text": "投掷", "is_correct": false, "explanation": "搭配：「投掷」须带投掷物作对象，句中「飞行员所执行的动作」没有这样的对象，与「气动力矩调控」也不搭。"}, {"text": "眨眼", "is_correct": false, "explanation": "语义：「眨眼」是眼睑的快速开合，与飞行器的姿态调控无关。"}], "explanations": {"操纵": "正确：「操纵动作」指用一定方法控制飞行器的动作，与飞行员、飞控系统和精确调控的语境相符。", "跳跃": "语义：「跳跃」指跳起、蹦起，与飞控系统对气动力矩的精确调控不相容。", "投掷": "搭配：「投掷」须带投掷物作对象，句中「飞行员所执行的动作」没有这样的对象，与「气动力矩调控」也不搭。", "眨眼": "语义：「眨眼」是眼睑的快速开合，与飞行器的姿态调控无关。"}, "sentence_index": 0, "correct_answer": "操纵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在老家操纵一碗热汤，很快就喝完了。", "explanation": "这里应该用〈端〉。操纵指控制机器、装置或局面，不能用于端碗。"}, {"text": "她每天操纵生病的父亲，很细心。", "explanation": "这里应该用〈照料〉。操纵含控制、摆布之意，不用于照料病人；照料才是护理、照顾。"}, {"text": "他操纵一口流利的英语，大家都佩服。", "explanation": "这里应该用〈说〉。操纵是控制事物使其按意愿行动，不能与语言能力搭配，表示会说应用〈说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操纵", "is_correct": true, "explanation": "正确：「用电脑操纵机器人」指通过计算机控制其动作，与后句「让它拿起杯子」相合。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：「拆卸」是拆开零件，与后句「让它拿起杯子」的目的不符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」用于动物或幼儿等生物，不能用于机器人。"}, {"text": "讨好", "is_correct": false, "explanation": "配价：「讨好」需要有情感的对象，机器人不能被讨好，「讨好机器人」不成立。"}], "explanations": {"操纵": "正确：「用电脑操纵机器人」指通过计算机控制其动作，与后句「让它拿起杯子」相合。", "拆卸": "语义：「拆卸」是拆开零件，与后句「让它拿起杯子」的目的不符。", "喂养": "搭配：「喂养」用于动物或幼儿等生物，不能用于机器人。", "讨好": "配价：「讨好」需要有情感的对象，机器人不能被讨好，「讨好机器人」不成立。"}, "sentence_index": 6, "correct_answer": "操纵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们必须操纵交通规则。", "explanation": "这里应该用〈遵守〉。操纵多指暗中摆布，「必须」之后应是守规则，而非摆布规则。"}, {"text": "她认真操纵了一盘饺子。", "explanation": "这里应该用〈包〉。操纵指操作机器或装置，包饺子要用〈包〉。"}, {"text": "他悠闲地操纵着咖啡。", "explanation": "这里应该用〈喝〉。操纵指操作机器或装置，喝咖啡要用〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他操纵机器人得很熟练。", "corrected_sentence": "他操纵机器人很熟练。", "error_description": "「得」用法有误。动词带宾语后接程度补语，须重复动词（「操纵机器人操纵得很熟练」）或改用「把」字句；此句直接在宾语后接「得」，应去掉「得」，改为「他操纵机器人很熟练」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想总操纵身边的人。", "corrected_sentence": "她总想操纵身边的人。", "error_description": "副词「总」位置错误。「总」修饰「想」，应放在「想」之前，说「总想操纵」；「想总」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
