INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12254, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体绕自身轴线旋转或翻转，如飞机做滚转动作。", "primary_collocate": null, "pronunciation": "gǔn zhuǎn", "ipa": "kuən˨˩˦ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "飞行员或飞控系统所执行的所有操纵动作——无论是俯仰、滚转还是偏航——最终都归结为对气动力矩的精确调控。", "target_word": "滚转", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机向右滚转，机翼一边升高一边下降。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员向左压杆，飞机便向左滚转。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机绕着纵轴滚转时，机翼会倾斜。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特技飞机在空中连续滚转了三圈。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副翼一动，飞机就会向一侧滚转。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机突然滚转，躲开了对方的导弹。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机滚转时，乘客会觉得身体向一侧倾斜。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机失控后绕机身不停滚转，乘客很害怕。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机为什么会滚转？因为两边机翼的升力不同。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滚转了", "label": "体标（了）"}, {"form": "滚转着", "label": "体标（着）"}, {"form": "滚转过", "label": "体标（过）"}, {"form": "滚转角", "label": "复合词"}], "register": "书面", "sense_fingerprint": "飞机等绕纵轴旋转或翻转的滚转动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滚转", "is_correct": true, "explanation": "正确：与“俯仰”“偏航”并列，指飞行器绕纵轴的横向翻转。"}, {"text": "滑行", "is_correct": false, "explanation": "语义：“滑行”是飞机在地面上的移动，与“俯仰”“偏航”这类空中姿态动作不属同类。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指飞机落地，不是绕轴的姿态动作，与并列结构不合。"}, {"text": "起飞", "is_correct": false, "explanation": "搭配：“起飞”是离地的过程，不能与“俯仰”“偏航”并列作操纵动作。"}], "explanations": {"滚转": "正确：与“俯仰”“偏航”并列，指飞行器绕纵轴的横向翻转。", "滑行": "语义：“滑行”是飞机在地面上的移动，与“俯仰”“偏航”这类空中姿态动作不属同类。", "降落": "语义：“降落”指飞机落地，不是绕轴的姿态动作，与并列结构不合。", "起飞": "搭配：“起飞”是离地的过程，不能与“俯仰”“偏航”并列作操纵动作。"}, "sentence_index": 0, "correct_answer": "滚转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的论文滚转了三次，终于定稿。", "explanation": "这里应该用〈修改〉。滚转指物体绕自身轴线翻转，论文不能被翻转，应说修改。"}, {"text": "地震来时，房子剧烈滚转。", "explanation": "这里应该用〈震动〉。滚转指物体绕自身轴线翻转，房屋因地震晃动应说震动。"}, {"text": "他的成绩一直在滚转，很不稳定。", "explanation": "这里应该用〈波动〉。滚转指物体绕自身轴线翻转，成绩的起伏应说波动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚转", "is_correct": true, "explanation": "正确：战斗机为躲避导弹而绕纵轴快速翻转。"}, {"text": "装载", "is_correct": false, "explanation": "语义：“装载”指往机器里放货物，与“躲开导弹”的规避动作无关。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”用于船只或车辆在站点停下，不说战斗机突然停靠。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”是补充电能，与紧急规避动作冲突。"}], "explanations": {"滚转": "正确：战斗机为躲避导弹而绕纵轴快速翻转。", "装载": "语义：“装载”指往机器里放货物，与“躲开导弹”的规避动作无关。", "停靠": "搭配：“停靠”用于船只或车辆在站点停下，不说战斗机突然停靠。", "充电": "语义：“充电”是补充电能，与紧急规避动作冲突。"}, "sentence_index": 6, "correct_answer": "滚转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马车在坑洼的路上滚转，车里的人都被晃得东倒西歪。", "explanation": "这里应该用〈颠簸〉。滚转指物体绕自身轴线翻转，马车在坑洼路上一起一伏应说颠簸。"}, {"text": "这次谈判滚转了三天，才签下合同。", "explanation": "这里应该用〈持续〉。滚转指物体绕自身轴线翻转，谈判所经历的时间应说持续。"}, {"text": "秋千在风中滚转，荡来荡去。", "explanation": "这里应该用〈摇摆〉。滚转指绕自身轴的翻转，秋千来回荡动应说摇摆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "特技飞机向左滚转了一只，又拉回了水平飞行。", "corrected_sentence": "特技飞机向左滚转了一圈，又拉回了水平飞行。", "error_description": "错误：补语量词用了“只”；正确：“圈”。“只”多用于动物，“滚转”计量转动次数应用“圈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机在低空向左滚转的很快，机翼几乎碰到地面。", "corrected_sentence": "飞机在低空向左滚转得很快，机翼几乎碰到地面。", "error_description": "错误：状态补语标记用了“的”（滚转的很快）；正确：“得”。“滚转得很快”中“得”引出补语，“的”不能接在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "航行的物体偏离了原本的航线。", "primary_collocate": null, "pronunciation": "piān háng", "ipa": "pʰiɛn˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长途航行中，哪怕只有很小的误差，船只也会慢慢偏航，远离原定路线。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾中，客机偏航了二十公里。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机偏航后，飞行员马上调整方向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把小船吹得偏航了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘货船偏航，没有按原定航线走。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导航出了问题，飞机才会偏航。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机在强风中偏航，操作员及时把它拉了回来。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长发现船偏航了，马上下令转向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机一偏航，雷达屏幕上就会报警。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，帆船常常偏航，很难直线前进。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏航了", "label": "体标（了）"}, {"form": "偏航过", "label": "体标（过）"}, {"form": "偏航角", "label": "复合词"}], "register": "书面", "sense_fingerprint": "飞机、船等偏离原定航线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：船只因误差慢慢偏离原定航线，即为偏航。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”是补充电能，与船只慢慢偏离航线无关。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指飞机落地，船只不说降落，与句中偏离航线的意思不符。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”指船只靠岸或停在站点，不能说船只慢慢停靠而远离原定路线。"}], "explanations": {"偏航": "正确：船只因误差慢慢偏离原定航线，即为偏航。", "充电": "语义：“充电”是补充电能，与船只慢慢偏离航线无关。", "降落": "语义：“降落”指飞机落地，船只不说降落，与句中偏离航线的意思不符。", "停靠": "搭配：“停靠”指船只靠岸或停在站点，不能说船只慢慢停靠而远离原定路线。"}, "sentence_index": 0, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树叶在风中慢慢偏航到地上。", "explanation": "这里应该用〈飘落〉。偏航只指航行的船、飞机偏离航线，树叶随风落下应说飘落。"}, {"text": "他每天早上在公园偏航半个小时，锻炼身体。", "explanation": "这里应该用〈跑步〉。偏航指航行的船、飞机偏离航线，不能表示锻炼身体的活动。"}, {"text": "这道菜的味道偏航了，有点太咸。", "explanation": "这里应该用〈偏〉。偏航只指航行器偏离航线，不能用来说味道偏咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：无人机被强风吹离航线，操作员及时纠正。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”与强风中偏离航线的情境无关。"}, {"text": "喷漆", "is_correct": false, "explanation": "语义：“喷漆”是给表面上色，与航向问题无关。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”用于环境或物体的温度，不能说无人机在强风中降温。"}], "explanations": {"偏航": "正确：无人机被强风吹离航线，操作员及时纠正。", "充电": "语义：“充电”与强风中偏离航线的情境无关。", "喷漆": "语义：“喷漆”是给表面上色，与航向问题无关。", "降温": "搭配：“降温”用于环境或物体的温度，不能说无人机在强风中降温。"}, "sentence_index": 6, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赛车在弯道上偏航，车身向内倾斜。", "explanation": "这里应该用〈转弯〉。偏航指航行器偏离航线，赛车过弯用转弯。"}, {"text": "货轮在港口偏航，等待卸货。", "explanation": "这里应该用〈停泊〉。偏航指航行中偏离航线，停在港口不说偏航。"}, {"text": "小狗跑丢了，偏航到了别的街区。", "explanation": "这里应该用〈跑错〉。偏航只用于航行器，小狗跑错路不说偏航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客机因为大雾偏航着二十公里，机长通知了乘客。", "corrected_sentence": "客机因为大雾偏航了二十公里，机长通知了乘客。", "error_description": "错误：体标用了“着”（偏航着二十公里）；正确：“了”。后面有“二十公里”表示完成的偏离量，应说“偏航了二十公里”，“着”表示持续，不能带这种数量补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风把帆船吹地偏航了，船员赶紧收帆。", "corrected_sentence": "大风把帆船吹得偏航了，船员赶紧收帆。", "error_description": "错误：补语标记用了“地”；正确：“得”。“吹得偏航”中“得”引出补语，“地”只用于状语，不能接在动词后作补语标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
