INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "把事物的原因、本质或结论概括为某一点。", "primary_collocate": null, "pronunciation": "guī jié wéi", "ipa": "kweɪ˥ tɕjɛ˧˥ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "飞行员或飞控系统所执行的所有操纵动作——无论是俯仰、滚转还是偏航——最终都归结为对气动力矩的精确调控。", "target_word": "归结为", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的成功可以归结为两个字：努力。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败的原因，主要归结为准备不足。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把问题归结为一句话：多练习。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家把污染归结为工厂排放过多。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故的原因，最后归结为人的疏忽。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些争吵都可以归结为沟通太少。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好中文的方法，可以归结为多听多说。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种病的原因可以归结为一点：睡眠不足。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的问题复杂，但可以归结为管理不好。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把原因、本质或结论概括成某一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归结为", "is_correct": true, "explanation": "正确：归结为表示最终概括成某一点，与“最终都”和“对…的调控”相合。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与句中所说动作最终落在精确调控上的意思不符。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消”是撤销，句中说所有动作都归于精确调控，撤销说不通。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”表示不注意，句中说所有操纵动作最终都落在精确调控上，用“忽略”意思相反。"}], "explanations": {"归结为": "正确：归结为表示最终概括成某一点，与“最终都”和“对…的调控”相合。", "反对": "语义：“反对”表示不赞成，与句中所说动作最终落在精确调控上的意思不符。", "取消": "语义：“取消”是撤销，句中说所有动作都归于精确调控，撤销说不通。", "忽略": "语义：“忽略”表示不注意，句中说所有操纵动作最终都落在精确调控上，用“忽略”意思相反。"}, "sentence_index": 0, "correct_answer": "归结为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书归结为三个部分。", "explanation": "这里应该用〈分为〉。归结为是把原因或结论概括成一点，不能用来说把整体分成几部分。"}, {"text": "水蒸气归结为水滴。", "explanation": "这里应该用〈变成〉。归结为是把原因或结论概括成一点，不能用来说一种事物转化成另一种。"}, {"text": "这箱苹果归结为五个。", "explanation": "这里不能用归结为。它只用于概括原因、本质或结论，不能用来统计具体东西的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归结为", "is_correct": true, "explanation": "正确：归结为表示归纳成某一点，与“可以”和“沟通太少”的因果说法相合。"}, {"text": "分配", "is_correct": false, "explanation": "搭配：“分配”的对象是任务、资源等，不能说“分配沟通太少”。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不重视，与“争吵可以归结为沟通太少”的因果说法相矛盾。"}, {"text": "加强", "is_correct": false, "explanation": "语义：“加强”表示增强，与句中“沟通太少”的说法矛盾。"}], "explanations": {"归结为": "正确：归结为表示归纳成某一点，与“可以”和“沟通太少”的因果说法相合。", "分配": "搭配：“分配”的对象是任务、资源等，不能说“分配沟通太少”。", "忽视": "语义：“忽视”表示不重视，与“争吵可以归结为沟通太少”的因果说法相矛盾。", "加强": "语义：“加强”表示增强，与句中“沟通太少”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "归结为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体重归结为三公斤。", "explanation": "这里应该用〈增加〉。归结为是概括原因或结论，不能用来说体重的数量增长。"}, {"text": "这次考试归结为一所好大学。", "explanation": "这里应该用〈考上〉。归结为是概括原因或结论，不能用来说考取了哪所学校。"}, {"text": "这次旅行归结为昨天。", "explanation": "这里应该用〈发生在〉。归结为是概括原因或结论，不能用来说事情发生的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试失败，主要归结为。", "corrected_sentence": "这次考试失败，主要归结为复习不够。", "error_description": "错误：“归结为”位于句末，后面缺少所归结的内容；正确：“主要归结为复习不够”，“归结为”后必须接结论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把问题归结为为时间不够。", "corrected_sentence": "我们把问题归结为时间不够。", "error_description": "错误：“为”重复。“归结为”只用一个“为”，应说“把问题归结为时间不够”，不能说“归结为为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
