INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "力和力臂的乘积，表示力对物体转动作用的大小。", "primary_collocate": null, "pronunciation": "lì jǔ", "ipa": "li⁵¹ tɕy²¹⁴", "syllable_count": 2, "sentences": [{"text": "飞行员压杆时，两侧副翼偏转不同，产生的力矩使飞机绕纵轴转动。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力越大，力臂越长，力矩就越大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力矩等于力乘以力臂。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扳手越长，同样的力产生的力矩越大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把手离门轴很远，所以推门时力矩大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个力的力矩为零，所以物体不会转动。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了力臂，然后算出力矩。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跷跷板两边的力矩相等，所以它能保持平衡。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力矩的单位是牛顿米。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个力矩方向相反、大小相等时，物体不会转动。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "气动力矩", "label": "复合"}, {"form": "合力矩", "label": "复合"}], "register": "科技", "sense_fingerprint": "物理量：力与力臂的乘积，表示力使物体转动的作用大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力矩", "is_correct": true, "explanation": "正确：“力矩”是力与力臂的乘积，这里指副翼偏转产生的使飞机转动的作用。"}, {"text": "力臂", "is_correct": false, "explanation": "语义：力臂是支点到力作用线的距离，本身不能使飞机转动。"}, {"text": "能量", "is_correct": false, "explanation": "语义：能量是做功的能力，不是使物体转动的力矩。"}, {"text": "质量", "is_correct": false, "explanation": "语义：质量表示物体所含物质的多少，与产生转动作用无关。"}], "explanations": {"力矩": "正确：“力矩”是力与力臂的乘积，这里指副翼偏转产生的使飞机转动的作用。", "力臂": "语义：力臂是支点到力作用线的距离，本身不能使飞机转动。", "能量": "语义：能量是做功的能力，不是使物体转动的力矩。", "质量": "语义：质量表示物体所含物质的多少，与产生转动作用无关。"}, "sentence_index": 0, "correct_answer": "力矩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根杆子的力矩很长。", "explanation": "这里应该用〈力臂〉。力矩是力与力臂的乘积，不能说它很长，说长短的是力臂。"}, {"text": "打球的力矩很大。", "explanation": "这里应该用〈力度〉。力矩是使物体转动的作用，不能用来说打球时的用力程度。"}, {"text": "这块石头的力矩是五公斤。", "explanation": "这里应该用〈重量〉。力矩是使物体转动的作用，不以公斤计，不能用来说物体有多重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力矩", "is_correct": true, "explanation": "正确：“算出”的对象是力矩这样的物理量，与前面画出力臂后再计算相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是能算出的数值，与黑板上的物理计算不符。"}, {"text": "杠杆", "is_correct": false, "explanation": "搭配：“杠杆”是工具，不能被“算出”。"}, {"text": "门", "is_correct": false, "explanation": "语义：门是物体，不能被计算出来。"}], "explanations": {"力矩": "正确：“算出”的对象是力矩这样的物理量，与前面画出力臂后再计算相合。", "颜色": "语义：颜色不是能算出的数值，与黑板上的物理计算不符。", "杠杆": "搭配：“杠杆”是工具，不能被“算出”。", "门": "语义：门是物体，不能被计算出来。"}, "sentence_index": 6, "correct_answer": "力矩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两地的力矩很远。", "explanation": "这里应该用〈距离〉。力矩是使物体转动的作用，不能用来说两地的远近。"}, {"text": "这根绳子的力矩是三米。", "explanation": "这里应该用〈长度〉。力矩不以米为单位，不能用来说绳子的长度。"}, {"text": "这种药的力矩很好。", "explanation": "这里应该用〈效果〉。力矩不能用来评价药物的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根杠杆上产生了一只力矩。", "corrected_sentence": "这根杠杆上产生了一个力矩。", "error_description": "错误：量词用错。“力矩”是抽象的物理量，应用量词“个”，说成“一只力矩”不对，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这扇门受到的力矩大越，越容易打开。", "corrected_sentence": "这扇门受到的力矩越大，越容易打开。", "error_description": "错误：“越大”语序颠倒。“越”要放在“大”前，应说“力矩越大”，不能说“力矩大越”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”与“起飞”互为反义，一个是离开地面，一个是落回地面。"}, {"text": "行走", "is_correct": false, "explanation": "行走指步行，与“起飞”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时待在某处，与“起飞”不构成反义。"}, {"text": "站立", "is_correct": false, "explanation": "站立指直立在地面上，与“起飞”不构成反义。"}], "correct_answer": "降落", "explanations": {"降落": "正确：“降落”与“起飞”互为反义，一个是离开地面，一个是落回地面。", "行走": "行走指步行，与“起飞”没有反义关系。", "停留": "停留指暂时待在某处，与“起飞”不构成反义。", "站立": "站立指直立在地面上，与“起飞”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”与“起飞”互为反义，一个是离开地面，一个是落回地面。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意走走，与“起飞”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中活动，与“起飞”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步指快速奔跑，与“起飞”没有反义关系。"}], "correct_answer": "降落", "explanations": {"降落": "正确：“降落”与“起飞”互为反义，一个是离开地面，一个是落回地面。", "散步": "散步指随意走走，与“起飞”没有反义关系。", "游泳": "游泳指在水中活动，与“起飞”没有反义关系。", "跑步": "跑步指快速奔跑，与“起飞”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指飞机、火箭等飞行器离开地面开始飞行。", "primary_collocate": null, "pronunciation": "qǐ fēi", "ipa": "tɕʰi²¹⁴ fei⁵⁵", "syllable_count": 2, "sentences": [{"text": "飞机在跑道上加速，很快就起飞了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭起飞的时候，声音非常大。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，航班晚点起飞了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客请系好安全带，飞机马上要起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机从上海起飞，飞往北京。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航天员坐在飞船里，等着火箭起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了以后，飞机终于起飞了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机下午三点起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞前，机场广播通知大家登机。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机不用跑道，也能垂直起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起飞了", "label": "体标"}, {"form": "起飞过", "label": "体标"}, {"form": "起飞时间", "label": "复合"}], "register": "通用", "sense_fingerprint": "飞机、火箭等离开地面开始飞行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”指飞机离开地面开始飞行，与“在跑道上加速”的起飞阶段吻合。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”是从空中落回地面，与“在跑道上加速”的起飞阶段正好相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”只用于人或动物，不能用于飞机。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”指人结束工作，不能用于飞机。"}], "explanations": {"起飞": "正确：“起飞”指飞机离开地面开始飞行，与“在跑道上加速”的起飞阶段吻合。", "降落": "语义：“降落”是从空中落回地面，与“在跑道上加速”的起飞阶段正好相反。", "睡觉": "搭配：“睡觉”只用于人或动物，不能用于飞机。", "下班": "搭配：“下班”指人结束工作，不能用于飞机。"}, "sentence_index": 0, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机每天起飞十个小时。", "explanation": "这里应该用〈飞行〉。起飞指飞机离开地面的那一刻，是瞬时动作，不能表示持续十个小时。"}, {"text": "汽车在高速公路上起飞了。", "explanation": "这里应该用〈出发〉。起飞只用于飞机、火箭等飞行器离开地面，汽车上路要说出发。"}, {"text": "发动机终于起飞了。", "explanation": "这里应该用〈启动〉。发动机是启动，不是起飞；起飞指飞行器离开地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：雨停后飞机离开地面开始飞行，用“起飞”。"}, {"text": "起床", "is_correct": false, "explanation": "搭配：“起床”只用于人，不能用于飞机。"}, {"text": "吃饱", "is_correct": false, "explanation": "搭配：“吃饱”指进食饱足，飞机不能吃饱。"}, {"text": "闭幕", "is_correct": false, "explanation": "搭配：“闭幕”指会议、展览等结束，不能用于飞机。"}], "explanations": {"起飞": "正确：雨停后飞机离开地面开始飞行，用“起飞”。", "起床": "搭配：“起床”只用于人，不能用于飞机。", "吃饱": "搭配：“吃饱”指进食饱足，飞机不能吃饱。", "闭幕": "搭配：“闭幕”指会议、展览等结束，不能用于飞机。"}, "sentence_index": 6, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天六点就起飞，去上班。", "explanation": "这里应该用〈起床〉。起飞用于飞机、火箭等飞行器，人醒来起身要说起床。"}, {"text": "轮船明天早上起飞，开往上海。", "explanation": "这里应该用〈启航〉。起飞指飞行器离开地面，船只离岸出发要说启航。"}, {"text": "电梯慢慢起飞到十楼。", "explanation": "这里应该用〈上升〉。电梯在楼层之间运行，不是飞行器离地，要说上升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这班飞机向广州起飞，飞往成都。", "corrected_sentence": "这班飞机从广州起飞，飞往成都。", "error_description": "错误：起点介词用错。“起飞”表示从某地离开，起点要用“从”，应说“从广州起飞”；“向”表示朝向，“向广州起飞”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的航班终于起飞着。", "corrected_sentence": "昨天的航班终于起飞了。", "error_description": "错误：“起飞着”。“起飞”是瞬间完成的动作，不能用“着”表示持续；应为“起飞了”，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”与“降落”互为反义，一个是落回地面，一个是离开地面。"}, {"text": "行走", "is_correct": false, "explanation": "行走指步行，与“降落”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时待在某处，与“降落”不构成反义。"}, {"text": "站立", "is_correct": false, "explanation": "站立指直立在地面上，与“降落”不构成反义。"}], "correct_answer": "起飞", "explanations": {"起飞": "正确：“起飞”与“降落”互为反义，一个是落回地面，一个是离开地面。", "行走": "行走指步行，与“降落”没有反义关系。", "停留": "停留指暂时待在某处，与“降落”不构成反义。", "站立": "站立指直立在地面上，与“降落”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”与“降落”互为反义，一个是离开地面，一个是落回地面。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意走走，与“降落”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中活动，与“降落”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步指快速奔跑，与“降落”没有反义关系。"}], "correct_answer": "起飞", "explanations": {"起飞": "正确：“起飞”与“降落”互为反义，一个是离开地面，一个是落回地面。", "散步": "散步指随意走走，与“降落”没有反义关系。", "游泳": "游泳指在水中活动，与“降落”没有反义关系。", "跑步": "跑步指快速奔跑，与“降落”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体从空中向下落。", "primary_collocate": null, "pronunciation": "jiàng luò", "ipa": "tɕjaŋ⁵¹ lwo⁵¹", "syllable_count": 2, "sentences": [{"text": "飞机安全降落在机场，大家都很高兴。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机慢慢降落，轮子碰到了跑道。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船降落在月球表面，航天员走了出来。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞员从空中安全降落到草地上。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落前，空姐请大家坐好。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "返回舱降落在大海里，船马上过去接它。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机降落时，风把地上的草吹弯了。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机慢慢降落在桌子上。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球在空中飘了很久，最后降落在山脚下。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太差，飞机不能在这里降落。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降落了", "label": "体标"}, {"form": "降落过", "label": "体标"}, {"form": "降落伞", "label": "复合"}], "register": "通用", "sense_fingerprint": "飞机、飞船、跳伞者等从空中向下落到地面或水面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：飞机从空中安全落到机场，用“降落”。"}, {"text": "下潜", "is_correct": false, "explanation": "搭配：“下潜”用于潜水艇、潜水员，不用于飞机落地。"}, {"text": "停泊", "is_correct": false, "explanation": "搭配：“停泊”指船只停靠在水面，飞机不说停泊。"}, {"text": "沉没", "is_correct": false, "explanation": "语义：“沉没”指沉入水中，与安全落在机场矛盾。"}], "explanations": {"降落": "正确：飞机从空中安全落到机场，用“降落”。", "下潜": "搭配：“下潜”用于潜水艇、潜水员，不用于飞机落地。", "停泊": "搭配：“停泊”指船只停靠在水面，飞机不说停泊。", "沉没": "语义：“沉没”指沉入水中，与安全落在机场矛盾。"}, "sentence_index": 0, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯降落到一楼。", "explanation": "这里应该用〈下降〉。降落指从空中落到地面，电梯垂直向下运行要说下降。"}, {"text": "轮船降落在码头。", "explanation": "这里应该用〈停靠〉。降落指从空中落向地面，船只靠岸要说停靠。"}, {"text": "他在比赛中降落了。", "explanation": "这里应该用〈落后〉。降落只表示从空中落下，比赛中处于劣势要说落后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：直升机从空中落到地面，风把草吹弯，与“降落”的含义相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”只用于人或动物，直升机不吃饭。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”只用于人，直升机不能唱歌。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或灯灭掉，与直升机的动作不符。"}], "explanations": {"降落": "正确：直升机从空中落到地面，风把草吹弯，与“降落”的含义相符。", "吃饭": "搭配：“吃饭”只用于人或动物，直升机不吃饭。", "唱歌": "搭配：“唱歌”只用于人，直升机不能唱歌。", "熄灭": "语义：“熄灭”指火或灯灭掉，与直升机的动作不符。"}, "sentence_index": 6, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在门口降落。", "explanation": "这里应该用〈停车〉。降落指从空中落到地面，车辆停下要说停车。"}, {"text": "火车明天降落在北京。", "explanation": "这里应该用〈抵达〉。降落指从空中落下，火车到站要说抵达。"}, {"text": "学生们下午就降落了。", "explanation": "这里应该用〈下课〉。降落指物体从空中向下落，学校结束上课要说下课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直升机从屋顶降落的很慢。", "corrected_sentence": "直升机从屋顶降落得很慢。", "error_description": "错误：补语标记用了“的”（降落的很慢）；正确：“得”。“得”引出动词后的状态补语，“的”不能直接接在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机昨晚降落地很平稳，乘客都很安全。", "corrected_sentence": "飞机昨晚降落得很平稳，乘客都很安全。", "error_description": "错误：补语标记用了“地”（降落地很平稳）；正确：“得”。“地”是动词前的状语标记，动词后引出补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
