INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12260, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "各不相同，有差别。", "primary_collocate": null, "pronunciation": "gè yì", "ipa": "kɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "各异", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大家的看法各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几座城市的风俗各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们的兴趣爱好各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的饮食习惯各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花的颜色和形状各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的性格各异，没有两个人完全一样。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的天气各异，北方冷，南方热。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些商店的价格各异，有贵的也有便宜的。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的做法虽然各异，但目标是一样的。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "各不相同、有差别，多作谓语，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各异", "is_correct": true, "explanation": "正确：“各异”指各不相同，与“不同飞行阶段”所面临的挑战相呼应。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“相同”与前面的“不同飞行阶段”矛盾，挑战在不同阶段不会相同。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与“不同飞行阶段”所面临的挑战相矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "搭配：“挑战”可以说“各异”或“单一”，不说“固定”的挑战。"}], "explanations": {"各异": "正确：“各异”指各不相同，与“不同飞行阶段”所面临的挑战相呼应。", "相同": "语义：“相同”与前面的“不同飞行阶段”矛盾，挑战在不同阶段不会相同。", "单一": "语义：“单一”指只有一种，与“不同飞行阶段”所面临的挑战相矛盾。", "固定": "搭配：“挑战”可以说“各异”或“单一”，不说“固定”的挑战。"}, "sentence_index": 0, "correct_answer": "各异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市里有很多各异。", "explanation": "这里应该用〈水果〉。“各异”是形容词，不能单独充当名词，“很多各异”不通。"}, {"text": "他们三个人各异地走进了教室。", "explanation": "这里应该用〈分别〉。“各异”说的是彼此不同，表示几个人各自分开做某事时要用〈分别〉。"}, {"text": "他们在教室里各异地读书。", "explanation": "这里应该用〈各自〉。“各异”说的是事物之间彼此不同，不表示“每人分开做某事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各异", "is_correct": true, "explanation": "正确：“各异”与“没有两个人完全一样”相符，说明性格彼此不同。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“相同”与“没有两个人完全一样”矛盾，说明同学们的性格彼此一样。"}, {"text": "一致", "is_correct": false, "explanation": "语义：“一致”指彼此相同，与“没有两个人完全一样”的意思矛盾。"}, {"text": "统一", "is_correct": false, "explanation": "搭配：“统一”多用于标准、行动、要求，不说人的性格统一。"}], "explanations": {"各异": "正确：“各异”与“没有两个人完全一样”相符，说明性格彼此不同。", "相同": "语义：“相同”与“没有两个人完全一样”矛盾，说明同学们的性格彼此一样。", "一致": "语义：“一致”指彼此相同，与“没有两个人完全一样”的意思矛盾。", "统一": "搭配：“统一”多用于标准、行动、要求，不说人的性格统一。"}, "sentence_index": 6, "correct_answer": "各异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的兴趣各异，只有一个。", "explanation": "这里应该用〈单一〉。“各异”指多个方面彼此不同，与“只有一个”矛盾。"}, {"text": "这些杯子的颜色各异，它们的颜色完全一样。", "explanation": "这里应该用〈相同〉。“各异”说的是彼此不同，与“颜色完全一样”相反；形容颜色统一时要用〈相同〉。"}, {"text": "这几把伞的颜色各异，全都是黑色的。", "explanation": "这里应该用〈一样〉。“各异”说的是彼此不同，与“全都是黑色的”相矛盾；颜色统一时要用〈一样〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个班的考试内容很各异。", "corrected_sentence": "两个班的考试内容各异。", "error_description": "错误：“很各异”。正确：“各异”。“各异”本身已表示各不相同，是描述状态的形容词，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三所学校的教学方法被各异。", "corrected_sentence": "这三所学校的教学方法各异。", "error_description": "错误：“被各异”。正确：“各异”。“各异”是状态形容词，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
