INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机机翼后缘的可动翼面，用于增加升力或改变飞行姿态。", "primary_collocate": null, "pronunciation": "jīn yì", "ipa": "tɕin˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "襟翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机降落时，飞行员会放下襟翼。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "襟翼在机翼的后面，可以增加升力。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞前，工程师检查了襟翼。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放下襟翼后，飞机的速度慢了下来。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机着陆时，襟翼向下伸出。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "襟翼坏了，飞机不能安全降落。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员按下按钮，襟翼慢慢收了起来。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机翼后缘的襟翼能改变飞机的飞行姿态。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机的襟翼是电动的。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对襟翼", "label": "量词"}, {"form": "后缘襟翼", "label": "复合"}], "register": "专业", "sense_fingerprint": "机翼后缘可动翼面，增加升力、改变姿态，航空术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "襟翼", "is_correct": true, "explanation": "正确：“襟翼”是机翼后缘可以展开的翼面，与“展开”及“动态适应”相符。"}, {"text": "机身", "is_correct": false, "explanation": "语义：机身不会像襟翼或缝翼那样展开，与句意不合。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机不是展开的部件，不能与缝翼并列说“展开”。"}, {"text": "车轮", "is_correct": false, "explanation": "搭配：“展开”多用于翼面、伞、地图等，不说“车轮展开”。"}], "explanations": {"襟翼": "正确：“襟翼”是机翼后缘可以展开的翼面，与“展开”及“动态适应”相符。", "机身": "语义：机身不会像襟翼或缝翼那样展开，与句意不合。", "发动机": "语义：发动机不是展开的部件，不能与缝翼并列说“展开”。", "车轮": "搭配：“展开”多用于翼面、伞、地图等，不说“车轮展开”。"}, "sentence_index": 0, "correct_answer": "襟翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "起飞前，工程师检查了一把襟翼。", "explanation": "这里应该用〈个〉或〈对〉。“把”用于有柄的器具，襟翼是机翼上的翼面，不能用“把”。"}, {"text": "飞机转弯时要靠襟翼来控制方向。", "explanation": "这里应该用〈副翼〉。襟翼用于起降时增加升力，控制转弯要用〈副翼〉。"}, {"text": "起飞前，工程师检查了一座襟翼。", "explanation": "这里应该用〈个〉或〈对〉。“座”用于山、桥、建筑等大型固定的东西，襟翼不能用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "襟翼", "is_correct": true, "explanation": "正确：“襟翼”坏了会影响飞机的起降，与“不能安全降落”相符。"}, {"text": "洗手间", "is_correct": false, "explanation": "语义：洗手间坏了不会影响飞机能否安全降落，与句意矛盾。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：餐桌与飞机的起降无关，不能导致飞机不能安全降落。"}, {"text": "调料", "is_correct": false, "explanation": "语义：调料即使坏了，也与飞机能否安全降落无关，句意不合。"}], "explanations": {"襟翼": "正确：“襟翼”坏了会影响飞机的起降，与“不能安全降落”相符。", "洗手间": "语义：洗手间坏了不会影响飞机能否安全降落，与句意矛盾。", "餐桌": "语义：餐桌与飞机的起降无关，不能导致飞机不能安全降落。", "调料": "语义：调料即使坏了，也与飞机能否安全降落无关，句意不合。"}, "sentence_index": 6, "correct_answer": "襟翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机左右转弯要靠襟翼。", "explanation": "这里应该用〈方向舵〉。襟翼用于增加升力，不用于左右转向。"}, {"text": "这架飞机的一根襟翼是电动的。", "explanation": "这里应该用〈个〉或〈对〉。“根”用于细长的东西，襟翼是翼面，不能用“根”。"}, {"text": "襟翼给飞机提供动力。", "explanation": "这里应该用〈发动机〉。襟翼不提供动力，它只用于改变机翼的升力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机降落前，飞行员要放下一把襟翼。", "corrected_sentence": "飞机降落前，飞行员要放下襟翼。", "error_description": "错误：“一把襟翼”。正确：“襟翼”前不用量词“把”，直接说“襟翼”即可。“把”用于有柄的器具，襟翼不适用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "襟翼慢慢收起了来。", "corrected_sentence": "襟翼慢慢收起来了。", "error_description": "错误：“收起了来”。正确：“收起来了”（也可说“收了起来”）。“了”不能插在“起”和“来”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
