INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由多个不同或相同的事物、部分组合而成的整体。", "primary_collocate": null, "pronunciation": "jí hé tǐ", "ipa": "tɕi˧˥ xɤ˧˥ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "集合体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市是不同文化的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个国家是很多民族的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画是许多小图片的集合体。", "target_word": "集合体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林不只是树，而是动植物的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公司是几个小团队的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子其实是无数小石头的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人的身体是很多器官的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个博物馆是各国文物的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些零件放在一起，就成了一个集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "由多个事物或部分组合而成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集合体", "is_correct": true, "explanation": "正确答案：集合体。“技术的集合体”指由多种技术组成的整体，与后文的“外化表现”相合。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是由多个部分组合成的整体，“技术的汽油”说不通。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块是一块实物，无法与“技术”构成“是……的”关系。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：“技术的盐”不是常用说法，“盐”不能表示由多方面组成的整体。"}], "explanations": {"集合体": "正确答案：集合体。“技术的集合体”指由多种技术组成的整体，与后文的“外化表现”相合。", "汽油": "语义：汽油是燃料，不是由多个部分组合成的整体，“技术的汽油”说不通。", "石块": "语义：石块是一块实物，无法与“技术”构成“是……的”关系。", "盐": "搭配：“技术的盐”不是常用说法，“盐”不能表示由多方面组成的整体。"}, "sentence_index": 0, "correct_answer": "集合体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班在操场上集合体，准备去参观博物馆。", "explanation": "这里应该用〈集合〉。〈集合〉可作动词，表示人聚拢；〈集合体〉是名词，不能当动词用。"}, {"text": "物理课上，老师说光速是一个很大的集合体。", "explanation": "这里应该用〈数值〉。〈集合体〉指由多个部分组成的整体；光速是一个固定的物理量，并不由部分组成。"}, {"text": "他把这些零件拆散了，就成了一个集合体。", "explanation": "这里应该用〈零件〉。〈集合体〉指组合在一起的整体；零件拆散后不再构成整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集合体", "is_correct": true, "explanation": "正确答案：集合体。沙子由无数小石头组成，“无数小石头的集合体”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不能说明沙子由哪些小石头组成。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官属性，不能表示由很多石头组成的整体。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“是……的声音”不能表示由很多小石头组合而成的整体。"}], "explanations": {"集合体": "正确答案：集合体。沙子由无数小石头组成，“无数小石头的集合体”符合句意。", "颜色": "语义：颜色是事物的属性，不能说明沙子由哪些小石头组成。", "味道": "语义：味道是感官属性，不能表示由很多石头组成的整体。", "声音": "搭配：“是……的声音”不能表示由很多小石头组合而成的整体。"}, "sentence_index": 6, "correct_answer": "集合体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数学课上，老师讲了集合体的概念和运算。", "explanation": "这里应该用〈集合〉。数学术语是“集合”，“集合体”不是数学概念。"}, {"text": "他的年龄是一个很大的集合体。", "explanation": "这里应该用〈数字〉。〈集合体〉指由多个部分组成的整体；年龄是一个数，并不由部分组成。"}, {"text": "他很集合体，大家都喜欢和他玩。", "explanation": "这里应该用〈合群〉。〈集合体〉是名词，不能用来形容性格；形容愿意与人相处，应说〈合群〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团队是由很多人才组成的一块集合体。", "corrected_sentence": "这个团队是由很多人才组成的一个集合体。", "error_description": "“一块集合体”错，应为“一个集合体”。集合体不是块状物，量词用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一堆积木是很多小块的集合体们。", "corrected_sentence": "这一堆积木是很多小块的集合体。", "error_description": "“们”通常只加在指人的名词后，不能加在“集合体”这类事物名词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
