INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然法则指自然界中客观存在的、不以人的意志为转移的规律或定律。", "primary_collocate": null, "pronunciation": "zì rán fǎ zé", "ipa": "tsɿ˥˩ ʐan˧˥ fa˨˩˦ tsɤ˧˥", "syllable_count": 4, "sentences": [{"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "自然法则", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人不能改变自然法则。", "target_word": "自然法则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家一直在寻找自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天以后是夏天，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛顿发现了一条重要的自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生老病死都是自然法则，谁也躲不开。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "违反自然法则的事，最后常常会失败。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理课上，我们学习了很多自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说人要尊重自然法则，不能乱来。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水往低处流，这是一个简单的自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "书面语", "sense_fingerprint": "自然界客观存在、不以人的意志为转移的规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：“自然法则”指自然界客观存在的规律，与“人类对……深刻理解的外化表现”相合。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”是语言的组织规则，句子说的是航空工程体现的物理规律，填入后意思不通。"}, {"text": "食谱", "is_correct": false, "explanation": "搭配：“深刻理解”多与规律、本质等抽象事理搭配，“食谱”是具体的菜单，不能被深刻理解。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是地域性的语言变体，与航空工程的句意无关，填入后不成立。"}], "explanations": {"自然法则": "正确：“自然法则”指自然界客观存在的规律，与“人类对……深刻理解的外化表现”相合。", "语法": "语义：“语法”是语言的组织规则，句子说的是航空工程体现的物理规律，填入后意思不通。", "食谱": "搭配：“深刻理解”多与规律、本质等抽象事理搭配，“食谱”是具体的菜单，不能被深刻理解。", "方言": "语义：“方言”是地域性的语言变体，与航空工程的句意无关，填入后不成立。"}, "sentence_index": 0, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要学会掌握汉语的自然法则，才能说得流利。", "explanation": "这里应该用〈规律〉。“自然法则”只指自然界中客观存在的规律，语言的语法和用法不能叫自然法则。"}, {"text": "这道数学题要用到一个自然法则。", "explanation": "这里应该用〈公式〉。“自然法则”指自然界的客观规律，数学题用的是人为总结的公式，应说“公式”。"}, {"text": "他打球的自然法则很厉害。", "explanation": "这里应该用〈技巧〉。“自然法则”指自然界的客观规律，球员的打球本领应说“技巧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：“违反自然法则”是常用搭配，“自然法则”指客观规律，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“违反”的对象应是规则、法律、规定，不能说“违反天气”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不是可以违反的规则，句子讲的是违背规律。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的形体外貌，不是可以违反的规则，填入后不成立。"}], "explanations": {"自然法则": "正确：“违反自然法则”是常用搭配，“自然法则”指客观规律，符合句意。", "天气": "搭配：“违反”的对象应是规则、法律、规定，不能说“违反天气”。", "颜色": "语义：颜色是视觉属性，不是可以违反的规则，句子讲的是违背规律。", "身材": "语义：“身材”指人的形体外貌，不是可以违反的规则，填入后不成立。"}, "sentence_index": 6, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的自然法则写在说明书上，照着做就行。", "explanation": "这里应该用〈使用方法〉。“自然法则”指自然界的客观规律，机器的操作步骤是人写的，应说“使用方法”。"}, {"text": "这个社团的自然法则写得很清楚。", "explanation": "这里应该用〈章程〉。“自然法则”指自然界的规律，社团的规定应说“章程”。"}, {"text": "人要养成好的自然法则，才能受益一生。", "explanation": "这里应该用〈习惯〉。“养成”的对象是个人的行为习惯，自然法则是客观规律，不能养成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家发现了这只自然法则。", "corrected_sentence": "科学家发现了这条自然法则。", "error_description": "量词错误：“自然法则”应用量词“条”，应说“这条自然法则”。“只”用于动物、成对的器官等，不能用来数“自然法则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人类必须遵守这块自然法则。", "corrected_sentence": "人类必须遵守这条自然法则。", "error_description": "“这块自然法则”错，应为“这条自然法则”。“块”用于块状物，“自然法则”应用量词“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
