INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将内在的思想、情感或特质通过外在的形式或行为表现出来。", "primary_collocate": null, "pronunciation": "wài huà", "ipa": "wai̯˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "外化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把心里的感动外化成了一首歌。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用颜色把内心的痛苦外化出来。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好演员能把人物的性格外化为动作。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文化精神外化为古老的建筑。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的善良外化为每一个小小的举动。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不会说话，只能把情绪外化成哭闹。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记是把想法外化的好办法。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的自信外化为一种从容的态度。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人把对故乡的思念外化为文字。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外化了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "把内在的思想、情感、特质通过外在形式或行为表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。"}, {"text": "外挂", "is_correct": false, "explanation": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。"}, {"text": "外汇", "is_correct": false, "explanation": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。"}, {"text": "外患", "is_correct": false, "explanation": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}], "explanations": {"外化": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。", "外挂": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。", "外汇": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。", "外患": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化表现”指内在的理解通过外显形式呈现出来，与“深刻理解”的内在性相符。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘”指忘掉，与“深刻理解”相矛盾，“深刻理解的遗忘表现”不通。"}, {"text": "肤浅", "is_correct": false, "explanation": "语义：“肤浅”与“深刻理解”直接对立，句意自相矛盾。"}, {"text": "片面", "is_correct": false, "explanation": "搭配：“片面”多修饰“理解、看法”，不说“片面表现”，与“深刻理解”也互相矛盾。"}], "explanations": {"外化": "正确：“外化表现”指内在的理解通过外显形式呈现出来，与“深刻理解”的内在性相符。", "遗忘": "语义：“遗忘”指忘掉，与“深刻理解”相矛盾，“深刻理解的遗忘表现”不通。", "肤浅": "语义：“肤浅”与“深刻理解”直接对立，句意自相矛盾。", "片面": "搭配：“片面”多修饰“理解、看法”，不说“片面表现”，与“深刻理解”也互相矛盾。"}, "sentence_index": 0, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书桌外化，然后搬到了客厅。", "explanation": "这里误把“外化”当成〈移动〉的意思，把实物挪到别处。“外化”只指把内在的思想、情感表现于外，书桌不属于这一范畴。"}, {"text": "他把那根木头外化成了一把椅子。", "explanation": "这里误把“外化”当成〈制作〉的意思。外化指把内在的思想、情感表现于外，木头加工成椅子不属于这一范畴。"}, {"text": "下雨后，他把地上的湿气外化出来。", "explanation": "这里误把“外化”当成〈散发〉的意思（湿气从地面散发出来）。“外化”指思想、情感由内向外表现，湿气是自然现象，不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。"}, {"text": "外环", "is_correct": false, "explanation": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。"}, {"text": "坏话", "is_correct": false, "explanation": "huài 比 wài 多了声母 h，坏话指不好听的话，意思不同。"}, {"text": "怪话", "is_correct": false, "explanation": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}], "explanations": {"外化": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。", "外环": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。", "坏话": "huài 比 wài 多了声母 h，坏话指不好听的话，意思不同。", "怪话": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化成哭闹”表示情绪由内向外显露，与“只能”的语境相符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“哭闹”相反，哭闹是把情绪显露出来。"}, {"text": "压抑", "is_correct": false, "explanation": "搭配：“压抑”指压制，不能以“哭闹”作为结果，搭配不当。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”与“哭闹”的显露方向相反，句意矛盾。"}], "explanations": {"外化": "正确：“外化成哭闹”表示情绪由内向外显露，与“只能”的语境相符。", "隐藏": "语义：“隐藏”与“哭闹”相反，哭闹是把情绪显露出来。", "压抑": "搭配：“压抑”指压制，不能以“哭闹”作为结果，搭配不当。", "掩盖": "语义：“掩盖”与“哭闹”的显露方向相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把文字外化为对故乡的思念。", "explanation": "这里误把“外化”当成〈内化〉的意思，方向说反了。“外化”是由内向外表现，而这句是从外在的文字转为内在的思念。"}, {"text": "他把对故乡的思念外化在心里，从不说出口。", "explanation": "这里误把“外化”当成〈隐藏〉的意思（藏在心里）。“外化”是把内在的东西表现于外，与“在心里”“从不说出口”相矛盾。"}, {"text": "他把弟弟外化成了一个玩具。", "explanation": "这里误把“外化”当成〈变成〉的意思，把人说成了玩具。“外化”的对象是思想、情感等内在的东西，不能用于指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把心里的愤怒被外化出来了。", "corrected_sentence": "她把心里的愤怒外化出来了。", "error_description": "错误：“把”与“被”同用，构成“把……被……”的双重标记，应删去“被”，写作“她把心里的愤怒外化出来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的委屈很快外化了成眼泪。", "corrected_sentence": "她的委屈很快外化成了眼泪。", "error_description": "“了”的位置错误：完成体“了”应放在补语“成”之后，正确说法是“外化成了”，“外化了成”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物在活动中显示出来的行为、态度或成绩。", "primary_collocate": null, "pronunciation": "biǎo xiàn", "ipa": "piɑʊ˨˩˦ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "期末考试结束后，老师认真地评价了每个人的表现。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在舞台上的表现很自然。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天在课上的表现很好。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸她这次考试的表现不错。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在学校的表现让老师很满意。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最近在工作中的表现越来越好。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，他的表现让大家很吃惊。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好表现得到了经理的表扬。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这场比赛里的表现很稳定。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最近的表现很让我放心。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表现力", "label": "复合词"}, {"form": "表現", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表现:名词:人或事物在活动中显示出的行为、态度或成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f6b3972-a8a9-4c30-a116-104a85e3fab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：表现 biǎo xiàn，指人或事物在活动中显示出的行为、态度或成绩。"}, {"text": "表面", "is_correct": false, "explanation": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。"}, {"text": "标线", "is_correct": false, "explanation": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。"}, {"text": "表象", "is_correct": false, "explanation": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}], "explanations": {"表现": "正确：表现 biǎo xiàn，指人或事物在活动中显示出的行为、态度或成绩。", "表面": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。", "标线": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。", "表象": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}, "sentence_index": null, "correct_answer": "表现"}, "level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“评价了每个人的表现”指人在考试中显示出的行为或成绩，这里应填“表现”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不是人在考试中显示出的行为或成绩，“评价天气”句意不通。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，与人的表现无关，“评价门票”句意不通。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是建筑部件，与人的表现无关，“评价墙壁”句意不通。"}], "explanations": {"表现": "正确：“评价了每个人的表现”指人在考试中显示出的行为或成绩，这里应填“表现”。", "天气": "语义：天气是自然状况，不是人在考试中显示出的行为或成绩，“评价天气”句意不通。", "门票": "语义：门票是入场凭证，与人的表现无关，“评价门票”句意不通。", "墙壁": "语义：墙壁是建筑部件，与人的表现无关，“评价墙壁”句意不通。"}, "sentence_index": 0, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师当众表现了他。", "explanation": "这里应该用〈表扬〉。当众赞许某人要说“表扬”，表现指人或事物在活动中显示出的行为、态度或成绩，不表示赞扬别人。"}, {"text": "他向老师表现了原因。", "explanation": "这里应该用〈解释〉。说明原因要说“解释”，表现不表示说明道理。"}, {"text": "桌子的表现很光滑。", "explanation": "这里应该用〈表面〉。形容物体外层光滑要说“表面”，表现不能指物体的外层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“比赛中，他的表现让大家很吃惊”中，表现指他在比赛中显示出的行为或成绩。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎是车辆部件，与人在比赛中显示的行为或成绩无关，“他的轮胎让大家很吃惊”句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，与比赛中的行为或成绩无关，“他的冰箱让大家很吃惊”句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁用具，与比赛中的行为或成绩无关，“他的钥匙让大家很吃惊”句意不通。"}], "explanations": {"表现": "正确：“比赛中，他的表现让大家很吃惊”中，表现指他在比赛中显示出的行为或成绩。", "轮胎": "语义：轮胎是车辆部件，与人在比赛中显示的行为或成绩无关，“他的轮胎让大家很吃惊”句意不通。", "冰箱": "语义：冰箱是家电，与比赛中的行为或成绩无关，“他的冰箱让大家很吃惊”句意不通。", "钥匙": "语义：钥匙是开锁用具，与比赛中的行为或成绩无关，“他的钥匙让大家很吃惊”句意不通。"}, "sentence_index": 6, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的表现很苗条。", "explanation": "这里应该用〈身材〉。形容体型要说“身材”，表现指行为、态度或成绩，不能形容人的体型。"}, {"text": "这块蛋糕的表现很甜。", "explanation": "这里应该用〈味道〉。形容食物的甜要说“味道”，表现不能用来描述食物的味道。"}, {"text": "这朵花的表现很香。", "explanation": "这里应该用〈气味〉。形容花的香要说“气味”，表现不能用来描述气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在演出中有一只很精彩的表现。", "corrected_sentence": "他在演出中有一次很精彩的表现。", "error_description": "量词错误：“表现”应用量词“次”，“只”用于动物等个体，不能计量表现。正确应为“一次很精彩的表现”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子的表现的很稳定，大家都很放心。", "corrected_sentence": "这个孩子的表现很稳定，大家都很放心。", "error_description": "多出“的”：“表现”后直接接谓语“很稳定”，不需要“的”。“这个孩子的表现的很稳定”应删去“表现”后的“的”，正确为“这个孩子的表现很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "正确：“动荡”指局势不安定，与“平稳”构成反义，可用于句中的“局势”。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴形容心里愉快，与“平稳”没有反义关系，句中说的是局势。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足或颜色鲜亮，与“平稳”不构成反义。"}, {"text": "清爽", "is_correct": false, "explanation": "清爽形容舒适、干净的感觉，与“平稳”不构成反义。"}], "correct_answer": "动荡", "explanations": {"动荡": "正确：“动荡”指局势不安定，与“平稳”构成反义，可用于句中的“局势”。", "高兴": "高兴形容心里愉快，与“平稳”没有反义关系，句中说的是局势。", "明亮": "明亮形容光线充足或颜色鲜亮，与“平稳”不构成反义。", "清爽": "清爽形容舒适、干净的感觉，与“平稳”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体或状态稳定、不晃动；也可形容局势、心情等平静、没有波动。", "primary_collocate": null, "pronunciation": "píng wěn", "ipa": "pʰiŋ˧˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "平稳", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机在高空飞得很平稳。", "target_word": "平稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车开得很平稳，我在车上睡着了。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完音乐，她的心情慢慢平稳了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在海上走得很平稳，没有一点晃动。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，城市的物价一直很平稳。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子平稳地放在桌子上。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人的呼吸已经平稳了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车时，要让车身保持平稳。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的局势终于平稳下来了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体运行稳定不晃动；局势、心情、数值平静无波动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳起降”指飞机起飞和降落时稳稳当当、不晃动，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来形容飞机起降的状态。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧哗，与起降时稳定的状态不符。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容味道、声音或面容，不能修饰“起降”。"}], "explanations": {"平稳": "正确：“平稳起降”指飞机起飞和降落时稳稳当当、不晃动，符合句意。", "清脆": "语义：“清脆”形容声音，不能用来形容飞机起降的状态。", "热闹": "语义：“热闹”形容场面喧哗，与起降时稳定的状态不符。", "甜美": "搭配：“甜美”多形容味道、声音或面容，不能修饰“起降”。"}, "sentence_index": 0, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里很平稳，大家都在看书。", "explanation": "这里应该用〈安静〉。“平稳”说的是不晃动或没有波动，图书馆里没有声音应说“安静”。"}, {"text": "街上很平稳，大家都在买东西。", "explanation": "这里应该用〈热闹〉。“平稳”说的是没有波动，人多、声音大的景象应说“热闹”。"}, {"text": "这个西瓜很平稳，吃起来很甜。", "explanation": "这里应该用〈新鲜〉。“平稳”说的是不晃动或没有波动，不能形容水果的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳地放”说放置时杯子不晃动，符合句意。"}, {"text": "热烈", "is_correct": false, "explanation": "语义：“热烈”形容情绪或场面高涨，不能用来形容放置杯子的动作。"}, {"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人的性格，杯子不能腼腆地放在桌上。"}, {"text": "丰盛", "is_correct": false, "explanation": "搭配：“丰盛”修饰饭菜，不能修饰“放”这个动作。"}], "explanations": {"平稳": "正确：“平稳地放”说放置时杯子不晃动，符合句意。", "热烈": "语义：“热烈”形容情绪或场面高涨，不能用来形容放置杯子的动作。", "腼腆": "语义：“腼腆”形容人的性格，杯子不能腼腆地放在桌上。", "丰盛": "搭配：“丰盛”修饰饭菜，不能修饰“放”这个动作。"}, "sentence_index": 6, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天空平稳，万里无云。", "explanation": "这里应该用〈晴朗〉。“平稳”说的是状态没有波动，天空的样子应说“晴朗”。"}, {"text": "这间屋子的味道很平稳，闻起来很舒服。", "explanation": "这里应该用〈清新〉。“平稳”说的是不晃动或没有波动，气味的清爽应说“清新”。"}, {"text": "今天的晚饭很平稳，桌上摆满了菜。", "explanation": "这里应该用〈丰盛〉。“平稳”说的是没有波动，饭菜的种类和数量多应说“丰盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面终于平稳出来了。", "corrected_sentence": "湖面终于平稳下来了。", "error_description": "补语错误：表示状态变得平稳应用趋向补语「下来」，应说「平稳下来」，「平稳出来」不符合说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车开地很平稳。", "corrected_sentence": "这辆车开得很平稳。", "error_description": "结构助词错误：动词「开」后接补语，结构助词应用「得」，应说「开得很平稳」，不能用「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指飞机起飞和降落的过程。", "primary_collocate": null, "pronunciation": "qǐ jiàng", "ipa": "t͡ɕʰi˨˩˦ t͡ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "起降", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个机场每天有上百次飞机起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾天气，飞机起降会受到影响。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员正在练习夜间起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条跑道是供飞机起降的。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，今天机场暂停了起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型飞机起降不需要很长的跑道。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大时，飞机起降很危险。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在塔台指挥飞机起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛上的机场只能起降小飞机。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起降了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "飞机起飞和降落的整个过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：“平稳起降”指飞机平稳地起飞和降落，与“可控性”的语境相符。"}, {"text": "颠簸", "is_correct": false, "explanation": "语义：“颠簸”与“平稳”相反，句意自相矛盾。"}, {"text": "失控", "is_correct": false, "explanation": "语义：“失控”与“可控性”相反，与“严谨遵循”的语境矛盾。"}, {"text": "坠落", "is_correct": false, "explanation": "搭配：“平稳”不修饰“坠落”，“平稳坠落”自相矛盾。"}], "explanations": {"起降": "正确：“平稳起降”指飞机平稳地起飞和降落，与“可控性”的语境相符。", "颠簸": "语义：“颠簸”与“平稳”相反，句意自相矛盾。", "失控": "语义：“失控”与“可控性”相反，与“严谨遵循”的语境矛盾。", "坠落": "搭配：“平稳”不修饰“坠落”，“平稳坠落”自相矛盾。"}, "sentence_index": 0, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑自行车练习起降。", "explanation": "这里误把“起降”当成〈起落〉的意思（车轮上下起落）。“起降”专指飞机的起飞和降落，自行车不能起降。"}, {"text": "这个湖的水位每天都在起降。", "explanation": "这里误把“起降”当成〈涨落〉的意思（水位的上下变化）。“起降”专指飞机的起飞和降落，不能用于水位。"}, {"text": "电梯每天在楼层之间起降。", "explanation": "这里应该用〈升降〉。升降可用于电梯、温度、水位等，起降专指飞机的起飞和降落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：小型飞机的起飞和降落需要跑道，句意成立。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或婴幼儿，不能用于飞机，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与飞机的跑道需求无关，句意不通。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“飞机哭泣”不是合理的搭配，飞机不会哭泣，与句意无关。"}], "explanations": {"起降": "正确：小型飞机的起飞和降落需要跑道，句意成立。", "喂养": "搭配：“喂养”的对象是动物或婴幼儿，不能用于飞机，句意不通。", "翻译": "语义：“翻译”指转换语言，与飞机的跑道需求无关，句意不通。", "哭泣": "搭配：“飞机哭泣”不是合理的搭配，飞机不会哭泣，与句意无关。"}, "sentence_index": 6, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的物价又起降了一次。", "explanation": "“起降”只指飞机的起飞和降落，物价的涨落不能说“起降”。"}, {"text": "他的情绪在这座岛上起降不定。", "explanation": "“起降”不用于情绪的起伏，情绪的变化不能用“起降”。"}, {"text": "这座岛上的机场只能起降一座大楼。", "explanation": "这里误把“起降”当成〈吊运〉的意思（把大楼吊起、放下）。“起降”专指飞机的起飞和降落，大楼不是飞机，不能起降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那架飞机今天把这里起降了。", "corrected_sentence": "那架飞机今天在这里起降了。", "error_description": "介词错误：“起降”指飞机起飞和降落，不能带“把”字宾语，“把这里起降了”不通；表示地点应该用“在这里”，正确说法是“那架飞机今天在这里起降了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小型飞机在这里安全地起降地。", "corrected_sentence": "小型飞机在这里安全地起降。", "error_description": "结构错误：“地”用来把修饰语连到动词上，只能接在修饰成分之后，不能接在动词“起降”之后；“起降地”不成词，整句不通。状语“安全地”应保留在动词前，正确说法是“安全地起降”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：「马虎」指做事粗略、不细致，与「严谨」周密相反。"}, {"text": "遥远", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容距离长。"}, {"text": "热烈", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容情绪高涨。"}, {"text": "简单", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容不复杂。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：「马虎」指做事粗略、不细致，与「严谨」周密相反。", "遥远": "与「严谨」没有反义关系，形容距离长。", "热烈": "与「严谨」没有反义关系，形容情绪高涨。", "简单": "与「严谨」没有反义关系，形容不复杂。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "草率", "is_correct": true, "explanation": "反义：「草率」指做事随便、不周密，与「严谨」相反。"}, {"text": "灵巧", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容动作或手艺灵活。"}, {"text": "沉重", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容分量大或心情压抑。"}, {"text": "响亮", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容声音洪亮。"}], "correct_answer": "草率", "explanations": {"草率": "反义：「草率」指做事随便、不周密，与「严谨」相反。", "灵巧": "与「严谨」没有反义关系，形容动作或手艺灵活。", "沉重": "与「严谨」没有反义关系，形容分量大或心情压抑。", "响亮": "与「严谨」没有反义关系，形容声音洪亮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容态度严肃谨慎，做事细致周密，没有疏漏。", "primary_collocate": null, "pronunciation": "yán jǐn", "ipa": "jɛn˧˥ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "严谨", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "王老师做事很严谨，从不出错。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她处理这件事很严谨，每一步都认真考虑。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查得很严谨，一点问题也没放过。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对数据的态度十分严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究需要严谨的态度。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位律师说话严谨，每个字都想过。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师严谨地检查了每一个零件。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他核对每一笔账都非常严谨。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国人给我的印象是工作严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "态度严肃谨慎，做事、文章、论证周密无疏漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：严格周密地遵循规律，与「物理定律」「结果」的语境相符，是唯一能填入空位的词。"}, {"text": "松散", "is_correct": false, "explanation": "语义：松散指结构不紧凑、约束少，与「严格遵循物理定律」的意思相反，读来不通。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：「遵循」的对象是规律，「随意」不能修饰对规律的遵循。"}, {"text": "草率", "is_correct": false, "explanation": "语义：草率指做事粗疏、不周密，与「卓越能力」及严格遵循的语境相反。"}], "explanations": {"严谨": "严谨：严格周密地遵循规律，与「物理定律」「结果」的语境相符，是唯一能填入空位的词。", "松散": "语义：松散指结构不紧凑、约束少，与「严格遵循物理定律」的意思相反，读来不通。", "随意": "搭配：「遵循」的对象是规律，「随意」不能修饰对规律的遵循。", "草率": "语义：草率指做事粗疏、不周密，与「卓越能力」及严格遵循的语境相反。"}, "sentence_index": 0, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的门窗很严谨，一丝风都透不进来。", "explanation": "这里应该用〈严密〉。严密形容物体封闭、没有缝隙；严谨形容人做事认真细致，不用于门窗。"}, {"text": "他的表情很严谨。", "explanation": "这里应该用〈严肃〉。严肃形容表情、气氛；严谨形容做事周密，不形容表情。"}, {"text": "他的声音很严谨。", "explanation": "这里应该用〈严厉〉。严厉形容言语、神情的苛刻；严谨形容做事周密，不用于描述声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：形容说话周密、字斟句酌，与「每个字都想过」的语境相符。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：懒散指松懈、不认真，与「每个字都想过」矛盾。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：粗心指不细心、容易出错，与「每个字都想过」矛盾。"}, {"text": "轻率", "is_correct": false, "explanation": "语义：轻率指随便、不慎重，与「每个字都想过」矛盾。"}], "explanations": {"严谨": "严谨：形容说话周密、字斟句酌，与「每个字都想过」的语境相符。", "懒散": "语义：懒散指松懈、不认真，与「每个字都想过」矛盾。", "粗心": "语义：粗心指不细心、容易出错，与「每个字都想过」矛盾。", "轻率": "语义：轻率指随便、不慎重，与「每个字都想过」矛盾。"}, "sentence_index": 6, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人照顾得很严谨。", "explanation": "这里应该用〈周到〉。周到形容照顾、服务的细致；严谨形容做事、治学的周密，不用于照顾别人。"}, {"text": "他对朋友很严谨。", "explanation": "这里应该用〈严格〉。严格形容对人、对要求的苛刻；严谨形容做事周密，不用于描述对朋友的相处。"}, {"text": "他明知有危险，仍然冲进了火场，非常严谨。", "explanation": "这里应该用〈勇敢〉。勇敢形容不怕危险的品质和行动；严谨形容做事周密，不用于描述冲进火场的胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她写报告写地很严谨，没有错字。", "corrected_sentence": "她写报告写得很严谨，没有错字。", "error_description": "「写地很严谨」应为「写得很严谨」：「严谨」作动词「写」的程度补语，补语前要用「得」，「地」只用于状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生是个严谨地人，诊断从没失误。", "corrected_sentence": "这位医生是个严谨的人，诊断从没失误。", "error_description": "「严谨地人」应为「严谨的人」：「严谨」修饰名词「人」作定语，要用「的」，「地」只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或特点表现得非常清楚，使人容易看见或了解。", "primary_collocate": null, "pronunciation": "zhāng xiǎn", "ipa": "ʈ͡ʂɑŋ˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "彰显", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件礼服彰显了她的好品味。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的老街彰显着历史的魅力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的善良在小事中彰显出来。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的旗袍彰显了东方的美。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛彰显了球队的实力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简单的设计彰显出品牌的个性。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难面前，最能彰显一个人的品格。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宏伟的大楼彰显了城市的经济实力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些作品彰显了作者的才华。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彰显了", "label": "完成体"}, {"form": "彰显着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "事物或特点表现得十分清楚，让人容易看出或了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示使工程智慧的卓越能力清楚地表现出来，与“也……了”顺承展示优点的语境相合。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“损害”指伤害、破坏，与“严谨遵循的结果”和“卓越能力”的褒义语境相反。"}, {"text": "掩饰", "is_correct": false, "explanation": "搭配：“掩饰”多接感情、错误、缺点，不说掩饰工程智慧的卓越能力。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”指刻意不让人知道，与句中“也……了”表示展示优点的语义相反。"}], "explanations": {"彰显": "正确：“彰显”表示使工程智慧的卓越能力清楚地表现出来，与“也……了”顺承展示优点的语境相合。", "损害": "语义：“损害”指伤害、破坏，与“严谨遵循的结果”和“卓越能力”的褒义语境相反。", "掩饰": "搭配：“掩饰”多接感情、错误、缺点，不说掩饰工程智慧的卓越能力。", "隐瞒": "语义：“隐瞒”指刻意不让人知道，与句中“也……了”表示展示优点的语义相反。"}, "sentence_index": 0, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束花把香味彰显得无影无踪。", "explanation": "这里误用“彰显”的“清楚呈现”义：香味无影无踪与“清楚呈现”矛盾，句意不通。"}, {"text": "厚厚的云彰显了月亮的光芒。", "explanation": "这里应该用〈掩盖〉。彰显是使事物明显地呈现，云层遮住月光要用掩盖，两者意思相反。"}, {"text": "这次实验彰显了问题的原因，却把它藏得严严实实。", "explanation": "“彰显”使原因清楚呈现，与后文“藏得严严实实”互相矛盾，句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示使品牌个性清楚地显现，与“简单的设计”的语境相合，“出”作结果补语。"}, {"text": "挤出", "is_correct": false, "explanation": "语义：“挤出”指用力使东西从狭小处出来，用于抽象的设计个性不合。"}, {"text": "推出", "is_correct": false, "explanation": "搭配：“推出”多接产品、服务、节目，不说“推出品牌的个性”。"}, {"text": "冒出", "is_correct": false, "explanation": "语义：“冒出”指突然出现，多用于烟、汗、念头，与经过设计体现个性的语境不合。"}], "explanations": {"彰显": "正确：“彰显”表示使品牌个性清楚地显现，与“简单的设计”的语境相合，“出”作结果补语。", "挤出": "语义：“挤出”指用力使东西从狭小处出来，用于抽象的设计个性不合。", "推出": "搭配：“推出”多接产品、服务、节目，不说“推出品牌的个性”。", "冒出": "语义：“冒出”指突然出现，多用于烟、汗、念头，与经过设计体现个性的语境不合。"}, "sentence_index": 6, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把秘密彰显在心里。", "explanation": "这里应该用〈隐藏〉。彰显是让好的品质或特点明显地呈现，秘密藏在心里要用隐藏。"}, {"text": "他的真实年龄被彰显得模糊不清。", "explanation": "这里误用“彰显”：彰显是使事物清楚地呈现，与“模糊不清”的意思相反，句意自相矛盾。"}, {"text": "大雨彰显了路上的脚印。", "explanation": "这里应该用〈抹去〉。彰显是使事物明显地被看见，脚印被雨水冲掉要用抹去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位设计师的作品很彰显了独特的审美。", "corrected_sentence": "这位设计师的作品彰显了独特的审美。", "error_description": "错误：在“彰显”前加了副词“很”。“很”不能修饰动词“彰显”，应删去，写作“彰显了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次展览彰显着了城市的文化底蕴。", "corrected_sentence": "这次展览彰显了城市的文化底蕴。", "error_description": "错误：“彰显”后同时用了持续体“着”和完成体“了”，两者不能并用。应写作“彰显了”或“彰显着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
