INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸，指父亲，是子女对男性直系长辈的称呼。", "primary_collocate": null, "pronunciation": "bà ba", "ipa": "pa⁵¹ pa", "syllable_count": 2, "sentences": [{"text": "爸爸把这个故事讲给孩子听。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸每天开车送我去学校。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸下班回家，先给妈妈打电话。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸带我去公园放风筝。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸在医院工作，他是一名医生。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着说：“你做得很好。”", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，爸爸总是给我讲故事。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的头发白了，但他还是每天跑步。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是父亲节，我给爸爸买了一份礼物。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈结婚二十年了。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老爸", "label": "口语称呼"}, {"form": "爸爸们", "label": "复数"}, {"form": "一个爸爸", "label": "量词：个"}, {"form": "一位爸爸", "label": "量词：位"}], "register": "口语", "sense_fingerprint": "名词：父亲，子女对父亲的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指父亲。"}, {"text": "巴巴", "is_correct": false, "explanation": "bā ba 与 bà ba 第一音节声调不同（第一声），意思是急切、迫切，与父亲无关。"}, {"text": "怕怕", "is_correct": false, "explanation": "怕怕读作 pà pa。它的声调和轻声都与 bà ba 相同，只有声母不同（p 与 b）。这是儿语，意思是害怕，与父亲无关。"}, {"text": "白白", "is_correct": false, "explanation": "白白读作 bái bai。第一音节是第二声，韵母是 ai。意思是徒然、没有代价地，与父亲无关。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指父亲。", "巴巴": "bā ba 与 bà ba 第一音节声调不同（第一声），意思是急切、迫切，与父亲无关。", "怕怕": "怕怕读作 pà pa。它的声调和轻声都与 bà ba 相同，只有声母不同（p 与 b）。这是儿语，意思是害怕，与父亲无关。", "白白": "白白读作 bái bai。第一音节是第二声，韵母是 ai。意思是徒然、没有代价地，与父亲无关。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：父亲给孩子讲故事，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能把故事传给孩子，故事的传递者必须是有生命的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会讲故事，“从……传到孩子”要求一个能传承故事的人作为起点。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“从窗户传到孩子”不成立，“传”的起点应是能传承故事的人，而不是建筑部件。"}], "explanations": {"爸爸": "爸爸：父亲给孩子讲故事，符合句意。", "椅子": "语义：椅子不能把故事传给孩子，故事的传递者必须是有生命的人。", "石头": "语义：石头不会讲故事，“从……传到孩子”要求一个能传承故事的人作为起点。", "窗户": "搭配：“从窗户传到孩子”不成立，“传”的起点应是能传承故事的人，而不是建筑部件。"}, "sentence_index": 0, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸是我妈妈的妈妈，每次来都会给我做好吃的。", "explanation": "这里应该用〈外婆〉。爸爸指男性父亲，不能指母亲的母亲；母亲的母亲应称〈外婆〉。"}, {"text": "爸爸是我爸爸的弟弟。", "explanation": "这里应该用〈叔叔〉。爸爸指父亲，不能指父亲的弟弟；父亲的弟弟应称〈叔叔〉。"}, {"text": "我的爸爸今年八岁，每天背着书包去上学，还很调皮。", "explanation": "这里应该用〈弟弟〉。爸爸指父亲，不能指八岁、背着书包上学的小男孩；这样的小男孩应称〈弟弟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指父亲。"}, {"text": "叭叭", "is_correct": false, "explanation": "bā ba 与 bà ba 第一音节声调不同（第一声），叭叭是喇叭声的拟声词。"}, {"text": "罢了", "is_correct": false, "explanation": "罢了读作 bà le。第一音节与 bà ba 相同，第二音节不同。意思是“而已”，与父亲无关。"}, {"text": "拜拜", "is_correct": false, "explanation": "拜拜读作 bài bai。第一音节同为第四声，但韵母不同（ai 与 a）。意思是再见，与父亲无关。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指父亲。", "叭叭": "bā ba 与 bà ba 第一音节声调不同（第一声），叭叭是喇叭声的拟声词。", "罢了": "罢了读作 bà le。第一音节与 bà ba 相同，第二音节不同。意思是“而已”，与父亲无关。", "拜拜": "拜拜读作 bài bai。第一音节同为第四声，但韵母不同（ai 与 a）。意思是再见，与父亲无关。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：小时候父亲常给孩子讲故事，符合“小时候”和“讲故事”的语境。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会讲故事，“讲故事”的施事必须是人。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“给我讲故事”要求有言语能力的主语，雨伞不能讲故事。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会讲故事，“讲故事”的施事必须是人。"}], "explanations": {"爸爸": "爸爸：小时候父亲常给孩子讲故事，符合“小时候”和“讲故事”的语境。", "黑板": "语义：黑板不会讲故事，“讲故事”的施事必须是人。", "雨伞": "搭配：“给我讲故事”要求有言语能力的主语，雨伞不能讲故事。", "桌子": "语义：桌子不会讲故事，“讲故事”的施事必须是人。"}, "sentence_index": 6, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸今年上小学一年级。", "explanation": "这里应该用〈儿子〉。爸爸是成年父亲，不能指正在上小学的孩子；这句说的应是〈儿子〉。"}, {"text": "我的爸爸比我大两岁，周末常和我一起打篮球。", "explanation": "这里应该用〈哥哥〉。爸爸指父亲，不可能只比孩子大两岁；比我大两岁的男性亲人应称〈哥哥〉。"}, {"text": "刚出生的爸爸还不会说话。", "explanation": "这里应该用〈婴儿〉。爸爸指成年的父亲，刚出生、还不会说话的应是〈婴儿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "邻居家的一只爸爸正在教孩子骑车。", "corrected_sentence": "邻居家的一位爸爸正在教孩子骑车。", "error_description": "量词错误：“爸爸”指人，应该用量词“位”（或“个”），“只”用于动物，不能说“一只爸爸”。正确说法是“一位爸爸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的爸爸们今天很忙，没有时间陪我。", "corrected_sentence": "我的爸爸今天很忙，没有时间陪我。", "error_description": "数量不符：句中只指“我”的一位父亲，而“我的爸爸们”指多位父亲，与语境不符，应说“我的爸爸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
