INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上由土石构成的高耸部分。", "primary_collocate": null, "pronunciation": "shān", "ipa": "ʂan˥", "syllable_count": 1, "sentences": [{"text": "故事里有动物，有山，有河。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我家后面有一座山。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去山上玩。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山很高，我爬不上去。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的空气特别好。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一条小河。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬过那座山。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪还没有化。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山上有很多树。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云盖着远处的山。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "山路", "label": "复合"}], "register": "中性", "sense_fingerprint": "地面上由土石构成的高耸部分，自然地貌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面上由土石构成的高耸部分。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}], "explanations": {"山": "正确。shān（第一声），指地面上由土石构成的高耸部分。", "三": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。", "伤": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。", "善": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。", "闪": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。", "身": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“动物”“河”都是自然事物，与“山”并列，构成自然景物的列举。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与动物、河并列时不属于同一类自然事物，在故事的景物列举中不合理。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不是自然景物，与“动物”“河”不成一类，列举中不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“有……，有河”的并列是自然景物，“面包”是食品，放入这一列举中搭配不当。"}], "explanations": {"山": "正确。“动物”“河”都是自然事物，与“山”并列，构成自然景物的列举。", "冰箱": "语义：冰箱是家用电器，与动物、河并列时不属于同一类自然事物，在故事的景物列举中不合理。", "铅笔": "语义：铅笔是文具，不是自然景物，与“动物”“河”不成一类，列举中不通。", "面包": "搭配：“有……，有河”的并列是自然景物，“面包”是食品，放入这一列举中搭配不当。"}, "sentence_index": 0, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家后面有一只山。", "explanation": "这里应该用〈座〉。山的量词是“座”，“只”多用于动物等，不能用于山。"}, {"text": "我们在河边钓了一座山。", "explanation": "这里不能说“钓”。“钓”的对象是鱼等水生动物，山不能被钓。"}, {"text": "那座山很快，我爬不上去。", "explanation": "这里应该用〈高〉。“快”形容速度，不能用来描述山的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12286, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面上由土石构成的高耸部分。"}, {"text": "商", "is_correct": false, "explanation": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“商业”。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 shān（第一声）声母不同（x 与 sh），意思是“先”。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。"}], "explanations": {"山": "正确。shān（第一声），指地面上由土石构成的高耸部分。", "商": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“商业”。", "善": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。", "先": "xiān（第一声）与 shān（第一声）声母不同（x 与 sh），意思是“先”。", "深": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“那座山”量词“座”与“爬过”的地面地形相合。"}, {"text": "河", "is_correct": false, "explanation": "搭配：河流的量词是“条”，不说“那座河”；“爬过”也不用于河流。"}, {"text": "海", "is_correct": false, "explanation": "语义：海是广阔的水域，不能像“爬”那样攀登。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头的量词是“块”，不说“那座石头”，与“爬过”也不搭配。"}], "explanations": {"山": "正确。“那座山”量词“座”与“爬过”的地面地形相合。", "河": "搭配：河流的量词是“条”，不说“那座河”；“爬过”也不用于河流。", "海": "语义：海是广阔的水域，不能像“爬”那样攀登。", "石头": "搭配：石头的量词是“块”，不说“那座石头”，与“爬过”也不搭配。"}, "sentence_index": 6, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把山打开了，看见了里面的房子。", "explanation": "这里不能说“打开”。“打开”用于门、箱子等可开合的东西，山是固定的地形。"}, {"text": "他把那座山倒进了杯子里。", "explanation": "这里应该用〈水〉。“倒”的对象应是液体，山是固体地形，不能倒进杯子里。"}, {"text": "我每天都用那座山写字。", "explanation": "这里不能说“用……写字”。山不是书写工具，“用”后应接笔、纸等工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们爬了一只很高的山。", "corrected_sentence": "我们爬了一座很高的山。", "error_description": "量词错误：“山”的量词应用“座”，不用“只”。“只”多用于小动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年爬着那座山。", "corrected_sentence": "他去年爬过那座山。", "error_description": "体标错误：“着”表示动作或状态的持续，不能用于“去年”这种已经完成的经历；表示经历应该用“过”，说“爬过那座山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真", "is_correct": true, "explanation": "真：与“假”构成反义词，指真实、不虚假。"}, {"text": "旧", "is_correct": false, "explanation": "旧：是形容词，但与“假”不构成反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮：是形容词，但与“假”不构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软：是形容词，但与“假”不构成反义关系。"}], "correct_answer": "真", "explanations": {"真": "真：与“假”构成反义词，指真实、不虚假。", "旧": "旧：是形容词，但与“假”不构成反义关系。", "亮": "亮：是形容词，但与“假”不构成反义关系。", "软": "软：是形容词，但与“假”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
