INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12293, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照音乐节奏移动身体，常作为一种娱乐或表演活动。", "primary_collocate": null, "pronunciation": "tiào wǔ", "ipa": "tʰiɑʊ̯⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "有的地方打鼓讲故事，有的地方跳舞讲故事。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "周末他们去广场跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天晚上都去公园跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就喜欢跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上大家一起跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会跳舞？", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在舞台上跳舞表演。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟朋友去跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶也喜欢跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一响，大家就开始跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了舞", "label": "体标"}, {"form": "跳着舞", "label": "体标"}, {"form": "跳过舞", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：作为娱乐或表演随音乐起舞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "跳舞：此处指以舞蹈形式讲故事，与前文“打鼓讲故事”相对应，是唯一能填入的词。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不是讲故事的方式，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理不是讲故事的方式，与前文并列结构不协调。"}, {"text": "缴费", "is_correct": false, "explanation": "搭配：“缴费”需要费用对象，不能作为讲故事的方式与前文并列。"}], "explanations": {"跳舞": "跳舞：此处指以舞蹈形式讲故事，与前文“打鼓讲故事”相对应，是唯一能填入的词。", "睡觉": "语义：睡觉不是讲故事的方式，句意不通。", "修理": "语义：修理不是讲故事的方式，与前文并列结构不协调。", "缴费": "搭配：“缴费”需要费用对象，不能作为讲故事的方式与前文并列。"}, "sentence_index": 0, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口渴了，想去跳舞一杯水。", "explanation": "这里应该用〈喝〉。口渴时要喝水；跳舞是随音乐舞动身体，不能带“一杯水”作宾语。"}, {"text": "她拿起笔开始跳舞一封信。", "explanation": "这里应该用〈写〉。用笔写信；跳舞是舞动身体，不能带“一封信”。"}, {"text": "我们每天在教室里跳舞汉语课。", "explanation": "这里应该用〈上〉。“上汉语课”是固定说法；跳舞不能带“课”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "跳舞：此处是娱乐表演的意思，与“在舞台上表演”搭配，是唯一能填入的词。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是表演活动，与“在舞台上……表演”搭配不通。"}, {"text": "耕地", "is_correct": false, "explanation": "配价：“耕地”需要地块作宾语，“在舞台上耕地表演”不成立。"}, {"text": "洗衣", "is_correct": false, "explanation": "语义：洗衣不是舞台表演的形式，句意不通。"}], "explanations": {"跳舞": "跳舞：此处是娱乐表演的意思，与“在舞台上表演”搭配，是唯一能填入的词。", "考试": "语义：“考试”不是表演活动，与“在舞台上……表演”搭配不通。", "耕地": "配价：“耕地”需要地块作宾语，“在舞台上耕地表演”不成立。", "洗衣": "语义：洗衣不是舞台表演的形式，句意不通。"}, "sentence_index": 6, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跳舞跳过了一米八。", "explanation": "这里应该用〈跳高〉。跳舞不用来表示跳跃的高度。"}, {"text": "他每天跳舞两百下，锻炼身体。", "explanation": "这里应该用〈跳绳〉。跳绳按次数计算，说“两百下”；跳舞是随音乐舞动身体，不用次数计量。"}, {"text": "他第一次从飞机上跳舞，吓得腿都软了。", "explanation": "这里应该用〈跳伞〉。跳舞不指从飞机上跳下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她跳舞跳的很好。", "corrected_sentence": "她跳舞跳得很好。", "error_description": "错误：补语标记“得”误写为“的”。正确：“跳舞”中重复的动词“跳”后接补语，要用“得”，说“跳得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们草地上一起跳舞。", "corrected_sentence": "孩子们在草地上一起跳舞。", "error_description": "错误：表示地点的介词“在”漏掉了。正确：应说“孩子们在草地上一起跳舞”，地点要用“在”引出，位于动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
