INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指儿童，通常用于称呼或指代年龄较小的孩子。", "primary_collocate": null, "pronunciation": "xiǎo péng yǒu", "ipa": "ɕjɑʊ˨˩ pʰɤŋ˧˥ joʊ˨˩", "syllable_count": 3, "sentences": [{"text": "小朋友听故事，学会听和说。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这个小朋友今年五岁了。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请小朋友排好队。", "target_word": "小朋友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里有很多小朋友在玩。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友，你叫什么名字？", "target_word": "小朋友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给小朋友买了一本书。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们都喜欢吃糖。", "target_word": "小朋友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个小朋友跑得很快。", "target_word": "小朋友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过马路的时候，小朋友要拉着大人的手。", "target_word": "小朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我邻居家的小朋友。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小朋友们", "label": "复数"}, {"form": "一个小朋友", "label": "量词"}, {"form": "一位小朋友", "label": "量词"}], "register": "中性", "sense_fingerprint": "指年纪较小的孩子，也用来称呼孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小朋友", "is_correct": true, "explanation": "“小朋友”指年纪小的孩子，能听故事、学习听和说，符合语境。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能听故事，也不会学习听和说，与句子的语境矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能听故事，也不能学习语言，与句子的语境矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“听故事”和“学会听和说”需要能感知与学习的施事，汽车不能充当这一角色。"}], "explanations": {"小朋友": "“小朋友”指年纪小的孩子，能听故事、学习听和说，符合语境。", "椅子": "语义：椅子不能听故事，也不会学习听和说，与句子的语境矛盾。", "石头": "语义：石头不能听故事，也不能学习语言，与句子的语境矛盾。", "汽车": "配价：“听故事”和“学会听和说”需要能感知与学习的施事，汽车不能充当这一角色。"}, "sentence_index": 0, "correct_answer": "小朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小朋友每天在医院做手术。", "explanation": "这里应该用〈外科医生〉。小朋友指年纪较小的孩子，不能指在医院做手术的医生。"}, {"text": "我和小朋友一起去公司开会。", "explanation": "这里应该用〈同事〉。小朋友指年纪较小的孩子，不能指与我一起工作的同事。"}, {"text": "这家公司的小朋友都很努力工作。", "explanation": "这里应该用〈员工〉。小朋友指年纪较小的孩子，不能指在公司工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小朋友", "is_correct": true, "explanation": "“小朋友”是能喜欢吃糖的孩子，与后面的“们”组成“小朋友们”，符合语境。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“喜欢吃糖”需要能感受和进食的主语，书包没有这种能力。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不吃糖，也没有“喜欢”的感受，与句子语境矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能吃糖，句子说的是能吃糖的人，与语境冲突。"}], "explanations": {"小朋友": "“小朋友”是能喜欢吃糖的孩子，与后面的“们”组成“小朋友们”，符合语境。", "书包": "配价：“喜欢吃糖”需要能感受和进食的主语，书包没有这种能力。", "大树": "语义：大树不吃糖，也没有“喜欢”的感受，与句子语境矛盾。", "电脑": "语义：电脑不能吃糖，句子说的是能吃糖的人，与语境冲突。"}, "sentence_index": 6, "correct_answer": "小朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隔壁那位小朋友八十岁了，身体还很好。", "explanation": "这里应该用〈老人〉。小朋友指年纪较小的孩子，不能用来指八十岁的老人。"}, {"text": "我姐姐是小朋友，正在学习外语。", "explanation": "这里应该用〈大学生〉。小朋友指年纪较小的孩子，不能用来指正在学习外语的大学生。"}, {"text": "这位小朋友管理着一家大型银行。", "explanation": "这里应该用〈行长〉。小朋友指年纪较小的孩子，不能指管理银行的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只小朋友在路边捡树叶。", "corrected_sentence": "两个小朋友在路边捡树叶。", "error_description": "量词错误：“小朋友”指人，应用量词“个”或“位”，不能用“只”（“只”多用于动物等）。错误形式是“两只小朋友”，正确形式是“两个小朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个小朋友们在河边钓鱼。", "corrected_sentence": "三个小朋友在河边钓鱼。", "error_description": "词尾错误：“们”表示复数，不能与数词“三个”同时使用。错误形式是“三个小朋友们”，正确形式是“三个小朋友”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷漠", "is_correct": true, "explanation": "“冷漠”与“温暖”在表示人的情感态度时构成反义关系，指对人冷淡、缺少关心。"}, {"text": "复杂", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“复杂”形容事物头绪多、难理清。"}, {"text": "清楚", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“清楚”形容明白、不模糊。"}, {"text": "迅速", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“迅速”形容速度快。"}], "correct_answer": "冷漠", "explanations": {"冷漠": "“冷漠”与“温暖”在表示人的情感态度时构成反义关系，指对人冷淡、缺少关心。", "复杂": "与“温暖”没有反义或近义关系，“复杂”形容事物头绪多、难理清。", "清楚": "与“温暖”没有反义或近义关系，“清楚”形容明白、不模糊。", "迅速": "与“温暖”没有反义或近义关系，“迅速”形容速度快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷漠", "is_correct": true, "explanation": "“冷漠”与“温暖”在表示人的情感态度时构成反义关系，指对人冷淡、缺少关心。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“粗糙”形容表面不光滑。"}, {"text": "明亮", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“明亮”形容光线充足。"}, {"text": "迟钝", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“迟钝”形容反应慢。"}], "correct_answer": "冷漠", "explanations": {"冷漠": "“冷漠”与“温暖”在表示人的情感态度时构成反义关系，指对人冷淡、缺少关心。", "粗糙": "与“温暖”没有反义或近义关系，“粗糙”形容表面不光滑。", "明亮": "与“温暖”没有反义或近义关系，“明亮”形容光线充足。", "迟钝": "与“温暖”没有反义或近义关系，“迟钝”形容反应慢。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "让人感到亲切和情感满足的氛围或感觉", "primary_collocate": null, "pronunciation": "wēn nuǎn", "ipa": "wən˥ nwan˨˩", "syllable_count": 2, "sentences": [{"text": "现在，有些人用手机讲，但面对面讲故事更温暖。", "target_word": "温暖", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "朋友的话让我觉得很温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个家虽然小，但是很温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的笑容很温暖。", "target_word": "温暖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们的关心让他感到温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话的声音很温暖。", "target_word": "温暖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一碗热汤，一句问候，真温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到大家都来帮忙，我心里很温暖。", "target_word": "温暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个温暖的故事。", "target_word": "温暖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的拥抱让我觉得特别温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "温暖的", "label": "定语形式"}, {"form": "很温暖", "label": "程度搭配"}], "register": "中性", "sense_fingerprint": "人情、氛围、话语带来的亲切与心里的暖意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "“温暖”形容面对面讲故事带来的亲切感，与“但”后面的正面对比相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”表示疏远、不热情，与“但”前后形成的正面对比相反，不符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”指温度低，面对面讲故事不会因此变得寒冷，与语境不符。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不能用来修饰“讲故事”这样的行为。"}], "explanations": {"温暖": "“温暖”形容面对面讲故事带来的亲切感，与“但”后面的正面对比相符。", "冷淡": "语义：“冷淡”表示疏远、不热情，与“但”前后形成的正面对比相反，不符合句意。", "寒冷": "语义：“寒冷”指温度低，面对面讲故事不会因此变得寒冷，与语境不符。", "狭窄": "搭配：“狭窄”形容空间，不能用来修饰“讲故事”这样的行为。"}, "sentence_index": 0, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目的预算很温暖，不会超支。", "explanation": "这里应该用〈充足〉。温暖形容亲切的情感、氛围或温度，不能用来形容预算的多少。"}, {"text": "他面对突发的危机很温暖。", "explanation": "这里应该用〈冷静〉。温暖表示让人感到亲切、有暖意，形容面对危机时的镇定应该用“冷静”。"}, {"text": "这次考试的成绩很温暖。", "explanation": "这里应该用〈优秀〉。温暖形容人际关系、氛围或温度，不能用来评价考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "“温暖”形容一碗热汤和一句问候带来的温情，与句意一致。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”与“热汤”矛盾，也与句中表达的温情相反。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容环境没有人气，与“热汤”和“问候”的温情语境冲突。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容坡度，不能用来修饰“问候”。"}], "explanations": {"温暖": "“温暖”形容一碗热汤和一句问候带来的温情，与句意一致。", "冰冷": "语义：“冰冷”与“热汤”矛盾，也与句中表达的温情相反。", "冷清": "语义：“冷清”形容环境没有人气，与“热汤”和“问候”的温情语境冲突。", "陡峭": "搭配：“陡峭”形容坡度，不能用来修饰“问候”。"}, "sentence_index": 6, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他遇到火灾时非常温暖。", "explanation": "这里应该用〈镇定〉。温暖表示让人感到亲切的暖意，形容遇险时的沉着应该用“镇定”。"}, {"text": "快递员把包裹送得很温暖。", "explanation": "这里应该用〈迅速〉。温暖形容的是亲切的情感或氛围，不能用来形容送件的速度。"}, {"text": "这道数学题他算得很温暖。", "explanation": "这里应该用〈准确〉。温暖形容亲切的感受，不能用来评价计算的正误；评价计算是否正确应用“准确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的话让我心里很很温暖。", "corrected_sentence": "妈妈的话让我心里很温暖。", "error_description": "重复副词：程度副词“很”只用一次，修饰形容词“温暖”。错误形式是“很很温暖”，正确形式是“很温暖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一位温暖老人。", "corrected_sentence": "这是一位温暖的老人。", "error_description": "助词缺失：形容词“温暖”修饰名词“老人”时，中间要加“的”。错误形式是“温暖老人”，正确形式是“温暖的老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
