INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把信息、物品或任务交给下面的人，让它们继续传递下去。", "primary_collocate": null, "pronunciation": "chuán xià qù", "ipa": "ʈʂʰwan˧˥ ɕja˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "老师把练习本交给第一排，让他们一个一个传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张表传下去，每个人都要写名字。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一排的同学把卷子拿一份，其他的传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把通知发给组长，组长再传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒杯一个一个地传下去，最后到了老人手里。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事先告诉班长，再由班长传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人把糖拿一颗，剩下的传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站成一排，把水桶传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总部的命令很快就传下去了。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把礼物从前面传下去，每人拿一个。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傳下去", "label": "繁体"}, {"form": "传下去了", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西、消息或任务交给下一个人，一个接一个往下递", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传下去", "is_correct": true, "explanation": "正确答案：「传下去」指把练习本一个接一个往后递，与「一个一个」相合。"}, {"text": "吞下去", "is_correct": false, "explanation": "语义：「吞下去」是把食物咽下，练习本不能吞。"}, {"text": "睡下去", "is_correct": false, "explanation": "语义：「睡下去」指继续睡觉，不能带「练习本」这样的对象。"}, {"text": "哭下去", "is_correct": false, "explanation": "语义：「哭下去」指继续哭，与把练习本交给别人无关。"}], "explanations": {"传下去": "正确答案：「传下去」指把练习本一个接一个往后递，与「一个一个」相合。", "吞下去": "语义：「吞下去」是把食物咽下，练习本不能吞。", "睡下去": "语义：「睡下去」指继续睡觉，不能带「练习本」这样的对象。", "哭下去": "语义：「哭下去」指继续哭，与把练习本交给别人无关。"}, "sentence_index": 0, "correct_answer": "传下去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把那支笔传下去给讲台上的老师。", "explanation": "这里应该用〈递〉。「传下去」指一个接一个往下递，直接交给面前的某一个人时要用「递」。"}, {"text": "请你把这封信传下去给校长。", "explanation": "这里应该用〈转交〉。「传下去」是向下一层层递送，交给校长这样的上级要用「转交」。"}, {"text": "他把辞职信传下去交给老板。", "explanation": "这里应该用〈递交〉。「传下去」是一层层往下传，交给老板这样的上级要用「递交」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传下去", "is_correct": true, "explanation": "正确答案：「剩下的传下去」指把剩余的糖继续往后递，与前一句分糖的意思一致。"}, {"text": "吃下去", "is_correct": false, "explanation": "语义：「吃下去」是自己吃掉，与「剩下的」要交给后面的人的意思不符。"}, {"text": "留下去", "is_correct": false, "explanation": "语义：「留下去」是留在自己手里，与句中把东西继续交给后面的人的意思相反。"}, {"text": "锁下去", "is_correct": false, "explanation": "搭配：「锁」用于门、箱子等，不能用于糖，「锁下去」与「剩下的糖」不搭。"}], "explanations": {"传下去": "正确答案：「剩下的传下去」指把剩余的糖继续往后递，与前一句分糖的意思一致。", "吃下去": "语义：「吃下去」是自己吃掉，与「剩下的」要交给后面的人的意思不符。", "留下去": "语义：「留下去」是留在自己手里，与句中把东西继续交给后面的人的意思相反。", "锁下去": "搭配：「锁」用于门、箱子等，不能用于糖，「锁下去」与「剩下的糖」不搭。"}, "sentence_index": 6, "correct_answer": "传下去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的旧书传下去给图书馆。", "explanation": "这里应该用〈赠送〉。「传下去」是一层层往下递，捐给图书馆这样的机构要用「赠送」。"}, {"text": "班长把作业传下去给老师。", "explanation": "这里应该用〈上交〉。「传下去」是向下递，交给老师这样的上级要用「上交」。"}, {"text": "他把这本书传下去还给了图书馆。", "explanation": "这里应该用〈归还〉。「传下去」是往下递给别人继续传，还给图书馆要用「归还」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把这些卷子一个个地传下去了，直到最后一排。", "corrected_sentence": "请把这些卷子一个个地传下去，直到最后一排。", "error_description": "体标错误：以“请”提出的祈使要求不能在动词后加“了”，应说“请把这些卷子一个个地传下去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人站在车上，把地上的砖头一块块传下去。", "corrected_sentence": "工人站在车上，把地上的砖头一块块传上去。", "error_description": "补语方向错误：砖头从地面递到车上是向上，应说「传上去」；「传下去」方向相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
