INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12303, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助他人脱离危险、病痛或困境，使对方获得安全或健康。", "primary_collocate": null, "pronunciation": "jiù rén", "ipa": "tɕjoʊ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这些故事常常是民间传说，比如关于动物说话或者英雄救人的故事。", "target_word": "救人", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "看到路边的老人摔倒了，他立刻跑过去救人。", "target_word": "救人", "complexity_tier": "T3", "furigana": "jiù rén", "sentence_source": "generated"}, {"text": "河里有个孩子，他跳下去救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员冲进火里救人。", "target_word": "救人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看到有人掉进水里，大家都想去救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救人要紧，我们快打电话叫救护车吧。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学了急救，就是为了以后能救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察说，这位老人昨天救人时受了伤。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了救人，自己跳进了冷水里。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救人的医生每天都工作到很晚。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "救了人", "label": "完成体"}, {"form": "救过人", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使人脱离危险或病痛、恢复安全健康的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45914aa1-3807-4f84-b9f5-40c8d21dc009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救人", "is_correct": true, "explanation": "救人 jiù rén：正确答案，指帮助他人脱离危险或病痛。"}, {"text": "九人", "is_correct": false, "explanation": "九人 jiǔ rén：jiǔ（第三声）与 jiù（第四声）声调不同，意思是九个人。"}, {"text": "就任", "is_correct": false, "explanation": "就任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是正式担任职务。"}, {"text": "旧任", "is_correct": false, "explanation": "旧任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是前任。"}], "explanations": {"救人": "救人 jiù rén：正确答案，指帮助他人脱离危险或病痛。", "九人": "九人 jiǔ rén：jiǔ（第三声）与 jiù（第四声）声调不同，意思是九个人。", "就任": "就任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是正式担任职务。", "旧任": "旧任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是前任。"}, "sentence_index": null, "correct_answer": "救人"}, "level_3": {"options": [{"text": "救人", "is_correct": true, "explanation": "正确：“救人”指救助他人，与“英雄”和“故事”的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，不能作“英雄”的谓语，“英雄桌子的故事”不通。"}, {"text": "米饭", "is_correct": false, "explanation": "词性：“米饭”是名词，不能表示英雄的行为，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "配价：“下雨”是不及物动词，不能带施事和动作对象，不能说“英雄下雨的故事”。"}], "explanations": {"救人": "正确：“救人”指救助他人，与“英雄”和“故事”的语境相符。", "桌子": "词性：“桌子”是名词，不能作“英雄”的谓语，“英雄桌子的故事”不通。", "米饭": "词性：“米饭”是名词，不能表示英雄的行为，句意不通。", "下雨": "配价：“下雨”是不及物动词，不能带施事和动作对象，不能说“英雄下雨的故事”。"}, "sentence_index": 0, "correct_answer": "救人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只掉进水池的小鸭子还在扑腾，他跑过去救人。", "explanation": "这里应该用〈捞出〉。“救人”的对象只能是人，救掉进水池的小鸭子不能用它。"}, {"text": "路边的花盆倒了，他弯腰跑过去救人。", "explanation": "这里应该用〈扶起〉。“救人”只指救助人，不能用于花盆。"}, {"text": "他的手机掉进水里了，他跑过去救人。", "explanation": "这里应该用〈找回〉。“救人”只指救助人，不能用于手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12303, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救人", "is_correct": true, "explanation": "救人 jiù rén：正确答案，指帮助他人脱离危险或病痛。"}, {"text": "求人", "is_correct": false, "explanation": "求人 qiú rén：声母 q 与 j 不同，qiú 是第二声，jiù 是第四声。意思是请求别人帮忙。"}, {"text": "留人", "is_correct": false, "explanation": "留人 liú rén：声母 l 与 j 不同，liú 是第二声，jiù 是第四声。意思是让人留下。"}, {"text": "揪人", "is_correct": false, "explanation": "揪人 jiū rén：jiū 是第一声，jiù 是第四声，两者声调不同。意思是抓住、拉住别人。"}], "explanations": {"救人": "救人 jiù rén：正确答案，指帮助他人脱离危险或病痛。", "求人": "求人 qiú rén：声母 q 与 j 不同，qiú 是第二声，jiù 是第四声。意思是请求别人帮忙。", "留人": "留人 liú rén：声母 l 与 j 不同，liú 是第二声，jiù 是第四声。意思是让人留下。", "揪人": "揪人 jiū rén：jiū 是第一声，jiù 是第四声，两者声调不同。意思是抓住、拉住别人。"}, "sentence_index": null, "correct_answer": "救人"}, "level_3": {"options": [{"text": "救人", "is_correct": true, "explanation": "正确：“救人”与“学了急救”的目的相符。"}, {"text": "抽烟", "is_correct": false, "explanation": "语义：“抽烟”与“学急救”的目的完全不相关，不合理。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“学急救”的目的是帮助他人，不是“唱歌”。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”与“学急救”的目的相反，句意不通。"}], "explanations": {"救人": "正确：“救人”与“学了急救”的目的相符。", "抽烟": "语义：“抽烟”与“学急救”的目的完全不相关，不合理。", "唱歌": "语义：“学急救”的目的是帮助他人，不是“唱歌”。", "欺负": "语义：“欺负”与“学急救”的目的相反，句意不通。"}, "sentence_index": 6, "correct_answer": "救人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的电脑死机了，他赶紧跑过去救人。", "explanation": "这里应该用〈修〉。“救人”只用于人，不能指修理电脑。"}, {"text": "他把那盆快枯萎的花搬到阳光下，这是在救人。", "explanation": "这里应该用〈养护〉。“救人”只用于人，不能用于花草。"}, {"text": "他一见到那只破旧的钟表，就想跑过去救人。", "explanation": "这里应该用〈修复〉。“救人”的对象是人，不能用于钟表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个救人得消防员很勇敢。", "corrected_sentence": "那个救人的消防员很勇敢。", "error_description": "错误形式：“救人得消防员”。正确形式：“救人的消防员”。修饰名词时，“救人”后应用结构助词“的”，不能用补语标记“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位消防员昨天救人过。", "corrected_sentence": "那位消防员昨天救人了。", "error_description": "错误形式：“救人过”。正确形式：“救人了”。表示动作已经完成用“了”；“过”表示经历，应放在动词后、宾语前（如“救过人”），不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
