INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12307, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指为人处世，即一个人在待人接物、言行举止方面的表现和品德。", "primary_collocate": null, "pronunciation": "zuò rén", "ipa": "tsuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "叙事不只是为了娱乐，还能教人做人的道理。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷常说，做人要诚实，不能骗人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人很低调，从不炫耀自己。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学做事之前，先要学会做人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母从小就教我怎么做人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要有礼貌，对谁都一样。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做人很正直，大家都信任她。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人别太小气，朋友会离你而去。", "target_word": "做人", "complexity_tier": "T3", "furigana": "zuò rén bié tài xiǎo qì, péng you huì lí nǐ ér qù。", "sentence_source": "generated"}, {"text": "老师不但教知识，也教我们做人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人做得很好，邻居都夸他。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做人处世", "label": "复合"}], "register": "中性", "sense_fingerprint": "为人处世的品德与言行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45914aa1-3807-4f84-b9f5-40c8d21dc009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做人", "is_correct": true, "explanation": "“做人”指为人处世的道理，与“还能教人……的道理”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“教人唱歌的道理”指的不是为人处世，与叙事教人品德的语境不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，“教人桌子的道理”不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能构成“教人……的道理”。"}], "explanations": {"做人": "“做人”指为人处世的道理，与“还能教人……的道理”相符。", "唱歌": "语义：“教人唱歌的道理”指的不是为人处世，与叙事教人品德的语境不符。", "桌子": "语义：“桌子”是物品，“教人桌子的道理”不通。", "苹果": "语义：“苹果”是水果，不能构成“教人……的道理”。"}, "sentence_index": 0, "correct_answer": "做人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在厨房做人，做得很香。", "explanation": "这里应该用〈做饭〉。“做人”指为人处世，不能指做饭。"}, {"text": "他每天早上在操场上做人。", "explanation": "这里应该用〈做操〉。“做人”不指体育活动，不能说在操场上做人。"}, {"text": "这个木匠每天都在做人，做了三张桌子。", "explanation": "这里误把“做人”当成〈制作〉义来用。“做人”指为人处世，不能指制作桌子等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做人", "is_correct": true, "explanation": "“做人”指为人处世的品德，与“她……很正直”的评价相符。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“她做饭很正直”指不了为人品德，句意不通。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“正直”评价的是品德，不能用来形容写字这种技能。"}, {"text": "排队", "is_correct": false, "explanation": "搭配：“很正直”修饰人的品行，不能用来形容排队这种行为。"}], "explanations": {"做人": "“做人”指为人处世的品德，与“她……很正直”的评价相符。", "做饭": "语义：“她做饭很正直”指不了为人品德，句意不通。", "写字": "语义：“正直”评价的是品德，不能用来形容写字这种技能。", "排队": "搭配：“很正直”修饰人的品行，不能用来形容排队这种行为。"}, "sentence_index": 6, "correct_answer": "做人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上在书房做人，做了很多题。", "explanation": "这里误把“做人”当成〈写作业〉义来用。“做人”指为人处世的品德，不能指写作业或做习题。"}, {"text": "他去朋友家做人，吃了一顿饭。", "explanation": "这里应该用〈做客〉。“做人”不能指到别人家里作客。"}, {"text": "他在市场做人，卖了很多东西。", "explanation": "这里应该用〈做生意〉。“做人”不指经营买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得爸爸做人得很踏实。", "corrected_sentence": "我觉得爸爸做人做得很踏实。", "error_description": "错误：“做人”后面的动词“做”漏掉了，“做人得很踏实”不成立。正确：“做人做得很踏实”，用动词“做”带补语“得很踏实”来说明做人的情况。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个会做人老师。", "corrected_sentence": "他是一个会做人的老师。", "error_description": "错误：“会做人”作定语修饰“老师”时漏了“的”。正确：“会做人的老师”，“的”连接修饰语和中心词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
