INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指家族中辈分较高、年龄较大的人。", "primary_collocate": null, "pronunciation": "zhǎng bèi", "ipa": "ʈʂɑŋ˨˩˦ pei˥˩", "syllable_count": 2, "sentences": [{"text": "在一些地方，长辈晚上坐在火炉边给孩子们讲故事。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "见到长辈，要先问好。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，长辈会给孩子红包。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很尊敬家里的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要听长辈的话。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，长辈先坐下，我们再坐。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是我们家最老的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常去看望生病的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日，我给长辈买了礼物。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在长辈面前，不要大声说话。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "长辈们", "label": "复数"}], "register": "中性", "sense_fingerprint": "家族中辈分高、年纪大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45914aa1-3807-4f84-b9f5-40c8d21dc009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指家族中辈分较高、年龄较大的人，与“晚上坐在火炉边给孩子们讲故事”的情境相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能坐在火炉边给孩子们讲故事，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坐在火炉边”与“桌子”不搭配，桌子不能坐，也不能讲故事。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能给孩子们讲故事，句意不通。"}], "explanations": {"长辈": "“长辈”指家族中辈分较高、年龄较大的人，与“晚上坐在火炉边给孩子们讲故事”的情境相符。", "小猫": "语义：小猫是动物，不能坐在火炉边给孩子们讲故事，句意不通。", "桌子": "搭配：“坐在火炉边”与“桌子”不搭配，桌子不能坐，也不能讲故事。", "石头": "语义：石头没有生命，不能给孩子们讲故事，句意不通。"}, "sentence_index": 0, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把长辈放进书包，背着去上学。", "explanation": "这里应该用〈课本〉。长辈指家里年长的人，不能放进书包。"}, {"text": "妈妈做的长辈很好吃。", "explanation": "这里应该用〈点心〉。长辈指人，不能指可以吃的食物。"}, {"text": "我的长辈上课时总坐在我旁边。", "explanation": "这里应该用〈同桌〉。长辈指年长的人，不能指同班上课时坐在身边的同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指年长的家人，与“奶奶是我们家最老的”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，“奶奶是我们家最老的汽车”句意不通。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服是物品，不能指人，“奶奶是……衣服”句意不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不能指人，“奶奶是……闹钟”句意不通。"}], "explanations": {"长辈": "“长辈”指年长的家人，与“奶奶是我们家最老的”相符。", "汽车": "语义：汽车不是人，“奶奶是我们家最老的汽车”句意不通。", "衣服": "语义：衣服是物品，不能指人，“奶奶是……衣服”句意不通。", "闹钟": "语义：闹钟是物件，不能指人，“奶奶是……闹钟”句意不通。"}, "sentence_index": 6, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家来了一只长辈，很热情。", "explanation": "这里应该用〈位〉。长辈指人，量词应用“位”，“只”多用于动物。"}, {"text": "奶奶家的一本长辈很有趣。", "explanation": "这里应该用〈位〉。长辈指人，不能用“本”来计量。"}, {"text": "我们小区来了一台长辈。", "explanation": "这里应该用〈位〉。长辈指人，不能用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两只长辈住在乡下。", "corrected_sentence": "我家有两位长辈住在乡下。", "error_description": "错误：量词“只”用于动物，指人时用错了量词，“两只长辈”不对。正确：“两位长辈”，指人的量词用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家来了三位长辈们，都很热情。", "corrected_sentence": "我家来了三位长辈，都很热情。", "error_description": "错误：名词前已有数量词“三位”时，不能再加复数后缀“们”。正确：“三位长辈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
