INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火炉是一种燃烧燃料（如煤、木柴）产生热量的器具，用于取暖或烹饪。", "primary_collocate": null, "pronunciation": "huǒ lú", "ipa": "xwɔ˨˩˦ lu˧˥", "syllable_count": 2, "sentences": [{"text": "在一些地方，长辈晚上坐在火炉边给孩子们讲故事。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "冬天，我们围着火炉取暖。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在火炉上烧了一壶水。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火炉里的木柴烧得很旺。", "target_word": "火炉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他往火炉里放了几块煤。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐在火炉旁边烤红薯。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的小屋有一个旧火炉。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用火炉做了一锅热汤。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火炉太热了，别靠得太近。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前冬天很冷，很多人家都有火炉。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "火爐", "label": "繁体"}], "register": "中性", "sense_fingerprint": "烧煤或木柴、可取暖也可做饭的炉具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：火炉是可以坐在旁边取暖、讲故事的实体，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，人不能坐在它的边上给孩子们讲故事。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”是抽象概念，不能说“坐在天气边”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能作为可以坐在旁边的参照物。"}], "explanations": {"火炉": "正确：火炉是可以坐在旁边取暖、讲故事的实体，符合句意。", "月亮": "语义：月亮在天上，人不能坐在它的边上给孩子们讲故事。", "天气": "搭配：“天气”是抽象概念，不能说“坐在天气边”。", "空气": "语义：空气是无形的，不能作为可以坐在旁边的参照物。"}, "sentence_index": 0, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天的晚上，全家人围着桌子吃了一个火炉。", "explanation": "这里应该用〈火锅〉。火炉是取暖、烧东西的器具，不能吃；围着桌子吃的是火锅。"}, {"text": "他每天都在火炉里上班。", "explanation": "这里应该用〈办公室〉。火炉是取暖、烧东西的器具，不能在里面上班；上班要去办公室。"}, {"text": "夏天，妈妈把西瓜放进火炉里冷藏。", "explanation": "这里应该用〈冰箱〉。火炉用来取暖、烧东西，不能冷藏食物；冷藏要用冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：山里的小屋里放着旧火炉，符合场景。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站是城市交通设施，与“山里的小屋”的场景不合。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不是可以“有一个旧”的具体物件，不能这样说。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是可以放在小屋里的物件，不能说“有一个旧星期”。"}], "explanations": {"火炉": "正确：山里的小屋里放着旧火炉，符合场景。", "地铁站": "语义：地铁站是城市交通设施，与“山里的小屋”的场景不合。", "天空": "搭配：“天空”不是可以“有一个旧”的具体物件，不能这样说。", "星期": "语义：“星期”是时间单位，不是可以放在小屋里的物件，不能说“有一个旧星期”。"}, "sentence_index": 6, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个火炉突然喷发，喷出了滚烫的岩浆。", "explanation": "这里应该用〈火山〉。喷发是火山的动作，火炉只用来取暖或烧东西，不会喷发。"}, {"text": "夏天的时候，我们打开火炉给屋子降温。", "explanation": "这里应该用〈空调〉。火炉用来取暖，不能降温；给屋子降温要用空调。"}, {"text": "他把火炉戴在手上取暖。", "explanation": "这里应该用〈手套〉。火炉是器具，不能戴在手上；取暖时戴的是手套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷坐在一条火炉旁边看报纸。", "corrected_sentence": "爷爷坐在一个火炉旁边看报纸。", "error_description": "量词错误：“一条火炉”应为“一个火炉”。“条”多用于细长的东西，火炉用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把火炉上熬了一锅粥。", "corrected_sentence": "妈妈在火炉上熬了一锅粥。", "error_description": "介词误用：“把”后应接受事对象，而“火炉上”表示地点，应使用“在”。“把火炉上熬”不通，应为“在火炉上熬了一锅粥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
