INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体的周围部分或边缘。", "primary_collocate": null, "pronunciation": "biān", "ipa": "pjɛn˥", "syllable_count": 1, "sentences": [{"text": "这块石头的边很锋利，小心手。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁门的边生了锈，要刷点油漆。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子的边很尖，小心点儿。", "target_word": "边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子的边破了一个小口。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盘子的边沾了一点油。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书的边折了一个角。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悬崖的边很危险，别走太近。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图的边印着一行小字。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的边有一圈花纹。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纸的边卷起来了，要压平。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊", "label": "繁体"}, {"form": "旁边", "label": "复合"}, {"form": "边上", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体周围的边缘部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：边指物体的周围部分或边缘。"}, {"text": "偏", "is_correct": false, "explanation": "piān（第一声）与 biān 声母不同（p 与 b），意思是偏向，不指物体边缘。"}, {"text": "变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}], "explanations": {"边": "正确：边指物体的周围部分或边缘。", "偏": "piān（第一声）与 biān 声母不同（p 与 b），意思是偏向，不指物体边缘。", "变": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。", "扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, "sentence_index": null, "correct_answer": "边"}, "level_3": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：此处“边”指石头的边缘，锋利的是边缘，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“锋利”来形容，与句意不合。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是具体事物，不能说“锋利”，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“锋利”来形容，与句意不合。"}], "explanations": {"边": "正确：此处“边”指石头的边缘，锋利的是边缘，符合句意。", "颜色": "搭配：“颜色”不能用“锋利”来形容，与句意不合。", "时间": "语义：“时间”不是具体事物，不能说“锋利”，句意不通。", "价格": "搭配：“价格”不能用“锋利”来形容，与句意不合。"}, "sentence_index": 0, "correct_answer": "边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用边煮了一锅汤。", "explanation": "这里应该用〈锅〉。“边”指物体的周围部分，不能用来煮东西；煮汤要用锅。"}, {"text": "这张纸的边在唱歌。", "explanation": "这里应该用〈人〉作主语。“边”指物体的周围部分，不会唱歌；唱歌的应是人。"}, {"text": "这首歌的边很好听。", "explanation": "这里应该用〈旋律〉。“边”指物体的周围部分，歌曲没有这样的部分；好听的是旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：悬崖的边缘很危险，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书本身不会危险，与“悬崖”的危险语境不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“危险”来形容，两者搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是悬崖的一部分，不能说“悬崖的冰箱很危险”。"}], "explanations": {"边": "正确：悬崖的边缘很危险，符合句意。", "书": "语义：书本身不会危险，与“悬崖”的危险语境不合。", "价格": "搭配：“价格”不能用“危险”来形容，两者搭配不当。", "冰箱": "语义：冰箱是家电，不是悬崖的一部分，不能说“悬崖的冰箱很危险”。"}, "sentence_index": 6, "correct_answer": "边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把边端上了桌。", "explanation": "这里应该用〈汤〉。“边”指物体的周围部分，不能端上桌；端上桌的是汤。"}, {"text": "他的边很大方。", "explanation": "这里应该用〈性格〉。“边”指物体的周围部分，形容人的品质要说性格，不能说边。"}, {"text": "这本书的边讲了一个有趣的故事。", "explanation": "这里应该用〈内容〉。“边”指物体的周围部分，不会讲故事；讲故事的是书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子的一只边上放着一个杯子。", "corrected_sentence": "桌子的一条边上放着一个杯子。", "error_description": "量词错误：“一只边”应为“一条边”。“只”不用于“边”这类事物，“边”指一侧时用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碗的边了破。", "corrected_sentence": "碗的边破了。", "error_description": "语序错误：“了”应紧跟动词，“碗的边了破”应为“碗的边破了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
