INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有血缘关系或婚姻关系的一群人，通常包括父母、子女和其他亲属。", "primary_collocate": null, "pronunciation": "jiā zú", "ipa": "tɕja˥ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "这些故事帮助他们了解自己的家族和家乡。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他的家族已经有三百年的历史了。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家族每年春节都聚在一起。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我们讲了家族的故事。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族出过很多有名的医生。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁到了一个很大的家族。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是我们家族里最老的人。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道家族的名字是怎么来的。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的家族从北方搬到了南方。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年夏天，整个家族都去海边玩。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大家族", "label": "复合"}, {"form": "家族史", "label": "复合"}], "register": "中性", "sense_fingerprint": "有血缘或婚姻关系的一大群亲人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正确。“了解自己的家族和家乡”指了解自己所属的亲属群体，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是可以被“了解”的对象，与“故事”“家乡”的语境不合。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”不能与“家乡”并列作为“了解”的对象，语义不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“了解自己的冰箱”的搭配不当，“冰箱”不适合与“家乡”并列作为了解的对象。"}], "explanations": {"家族": "正确。“了解自己的家族和家乡”指了解自己所属的亲属群体，符合句意。", "作业": "语义：“作业”不是可以被“了解”的对象，与“故事”“家乡”的语境不合。", "玩具": "语义：“玩具”不能与“家乡”并列作为“了解”的对象，语义不通。", "冰箱": "搭配：“了解自己的冰箱”的搭配不当，“冰箱”不适合与“家乡”并列作为了解的对象。"}, "sentence_index": 0, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国有五十六个家族。", "explanation": "这里应该用〈民族〉。“家族”指有血缘或婚姻关系的亲属群体，不能用来指一个国家里的各个民族。"}, {"text": "我们班三十个同学是一个家族。", "explanation": "这里应该用〈集体〉。“家族”指有血缘或婚姻关系的亲属群体，同学之间没有这种关系。"}, {"text": "他是我的家族。", "explanation": "“家族”指一群有血缘或婚姻关系的人，不能用来指单独的一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正确。“奶奶是我们家族里最老的人”指家族中的成员，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是由人组成的群体，“河流里最老的人”语义不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不能作为“最老的人”所在的群体，与句意不合。"}, {"text": "词语", "is_correct": false, "explanation": "搭配：“词语里最老的人”的搭配不当，“最老的人”需要指人的群体。"}], "explanations": {"家族": "正确。“奶奶是我们家族里最老的人”指家族中的成员，符合句意。", "河流": "语义：“河流”不是由人组成的群体，“河流里最老的人”语义不通。", "桌子": "语义：“桌子”不能作为“最老的人”所在的群体，与句意不合。", "词语": "搭配：“词语里最老的人”的搭配不当，“最老的人”需要指人的群体。"}, "sentence_index": 6, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家族有三十个学生。", "explanation": "这里应该用〈班级〉。“家族”指有血缘或婚姻关系的亲属群体，“学生”之间没有这种关系，不能归入“家族”。"}, {"text": "家族里种满了漂亮的花。", "explanation": "这里应该用〈花园〉。“家族”指一群有亲属关系的人，不是种花的地方。"}, {"text": "我的家族一个人跑完了马拉松。", "explanation": "这里不能用“家族”指一个人。“家族”指一群有亲属关系的人，“一个人跑完了马拉松”与“家族”的意思矛盾，应改用“我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这条家族每年冬天都去北方看雪。", "corrected_sentence": "我们这个家族每年冬天都去北方看雪。", "error_description": "量词误用：“家族”前应用量词“个”，“这条家族”用了“条”（“条”多用于细长的东西），应改为“这个家族”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们家族老房子。", "corrected_sentence": "这是我们家族的老房子。", "error_description": "助词遗漏：“我们家族”作定语修饰“老房子”，中间需要用“的”，应写作“我们家族的老房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
