INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手做出的各种姿势或动作，用来表达意思或情感。", "primary_collocate": null, "pronunciation": "shǒu shì", "ipa": "ʂou˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "讲故事的人用语言、表情和手势让别人理解他的想法。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他用手势告诉我，这里不能说话。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师做了一个手势，让我们坐下。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的手势是让车停下来。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂，但是看懂了他的手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话的时候，她喜欢用很多手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势的意思是“你真棒”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手势让孩子别害怕。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的手势，意思可能不一样。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在远处做手势，叫我过去。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "手勢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手做的姿势，表达意思或情感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确答案。手势（shǒushì）指用手做的动作，用来表达意思或情感。"}, {"text": "收视", "is_correct": false, "explanation": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。"}, {"text": "首饰", "is_correct": false, "explanation": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。"}, {"text": "收拾", "is_correct": false, "explanation": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。"}, {"text": "收市", "is_correct": false, "explanation": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}], "explanations": {"手势": "正确答案。手势（shǒushì）指用手做的动作，用来表达意思或情感。", "收视": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。", "首饰": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。", "收拾": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。", "收市": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}, "sentence_index": null, "correct_answer": "手势"}, "level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势是用手做的动作，与“语言、表情”并列，都是表达方式。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是表达想法的方式，与“语言、表情”并列说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的高矮胖瘦，不能用来表达想法。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”与表达想法无关，句子说不通。"}], "explanations": {"手势": "正确：手势是用手做的动作，与“语言、表情”并列，都是表达方式。", "天气": "语义：“天气”不是表达想法的方式，与“语言、表情”并列说不通。", "身材": "体貌：“身材”指身体的高矮胖瘦，不能用来表达想法。", "鞋子": "语义：“鞋子”与表达想法无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她露出了开心的手势。", "explanation": "这里应该用〈表情〉。“露出”搭配表情，手势是用手做的动作，不能这样用。"}, {"text": "妈妈戴上一个漂亮的手势，去参加婚礼。", "explanation": "这里应该用〈戒指〉。“戴”搭配戒指、帽子等，手势是用手做的动作，不能戴。"}, {"text": "舞蹈演员转了一圈，穿上了一个手势。", "explanation": "这里应该用〈裙子〉。“穿”搭配衣服、裙子，手势是动作，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势能传达意思，“这个手势的意思是……”说得通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子”是食物，不能表达“你真棒”的意思。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，本身不表达意思，句子不成立。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体部位，不能说它的意思是某句话。"}], "explanations": {"手势": "正确：手势能传达意思，“这个手势的意思是……”说得通。", "饺子": "语义：“饺子”是食物，不能表达“你真棒”的意思。", "手机": "语义：“手机”是通讯工具，本身不表达意思，句子不成立。", "脸": "体貌：“脸”是身体部位，不能说它的意思是某句话。"}, "sentence_index": 6, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在远处开手势，叫我过去。", "explanation": "这里应该用〈灯〉。“开”搭配灯、门等，手势不能被“开”。"}, {"text": "他在远处按手势，叫我过去。", "explanation": "这里应该用〈门铃〉。“按”搭配门铃、按钮，手势不能被“按”。"}, {"text": "上课的时候，手势响了。", "explanation": "这里应该用〈铃声〉。“响”的主语是声音，手势是用手做的动作，不能发出响声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做了一条手势，我就明白了。", "corrected_sentence": "他做了一个手势，我就明白了。", "error_description": "错误：“一条”；正确：“一个”。手势是动作，量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手势跟他打招呼。", "corrected_sentence": "我用手势跟他打招呼。", "error_description": "错误：“手势跟他打招呼”缺少介词“用”；正确：“用手势”。“用”引出工具，手势作为工具时要加“用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
