INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的内心、情感、意愿或大众的普遍心理。", "primary_collocate": null, "pronunciation": "rén xīn", "ipa": "ʐən˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "因为面对面讲故事，能让人心连在一起。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这样的做法很得人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难发生后，人心不安。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都相信他，人心很齐。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的生活变好了，人心也安定了。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位市长很关心大家，所以人心稳定。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的政策让人心安定了下来。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言一多，人心就乱了。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影温暖了人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了坏事，失去了人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人心惶惶", "label": "复合"}, {"form": "人心所向", "label": "复合"}], "register": "中性", "sense_fingerprint": "大众的普遍心理、情绪和意愿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”指人们的内心和情感，能够“连在一起”。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”可以拉近，却不说“连在一起”，与句中搭配不当。"}, {"text": "屏幕", "is_correct": false, "explanation": "语义：“面对面讲故事”强调直接见面，屏幕反而隔开了人，与句意相反。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“连在一起”说人心或关系，不说人数，句子不通。"}], "explanations": {"人心": "“人心”指人们的内心和情感，能够“连在一起”。", "距离": "搭配：“距离”可以拉近，却不说“连在一起”，与句中搭配不当。", "屏幕": "语义：“面对面讲故事”强调直接见面，屏幕反而隔开了人，与句意相反。", "人数": "搭配：“连在一起”说人心或关系，不说人数，句子不通。"}, "sentence_index": 0, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天抽人心。", "explanation": "这里应该用〈烟〉。〈抽〉搭配烟、烟卷等，人心是抽象的心理，不能抽。"}, {"text": "他冷了，就穿上人心。", "explanation": "这里应该用〈外套〉。〈穿〉搭配衣服、鞋袜等，人心不能穿。"}, {"text": "他在树上摘人心。", "explanation": "这里应该用〈苹果〉。〈摘〉搭配果实、花等，人心不能摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”指大众的心理，政策能让它“安定下来”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不会因为政策而“安定下来”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“安定”说社会或人心，不说颜色，搭配不当。"}, {"text": "道路", "is_correct": false, "explanation": "语义：道路不会有情绪，不能说“道路安定下来”。"}], "explanations": {"人心": "“人心”指大众的心理，政策能让它“安定下来”。", "桌子": "语义：桌子是物品，不会因为政策而“安定下来”。", "颜色": "搭配：“安定”说社会或人心，不说颜色，搭配不当。", "道路": "语义：道路不会有情绪，不能说“道路安定下来”。"}, "sentence_index": 6, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要处理好人心关系。", "explanation": "这里应该用〈人际〉。人际指人与人之间的交往关系，人心指大众的普遍心理，不说“人心关系”。"}, {"text": "医生检查了他的人心。", "explanation": "这里应该用〈心脏〉。人心指普遍的心理，是抽象的，不是器官，不能被检查。"}, {"text": "工厂缺人心，需要再招工。", "explanation": "这里应该用〈人手〉。人心指大众心理，不指劳动力，工厂缺人要说“缺人手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事件后，人心变很不安。", "corrected_sentence": "这次事件后，人心变得很不安。", "error_description": "漏掉“得”：“变”后接程度补语“很不安”时要说“变得很不安”，不能说“变很不安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次胜利让人心振奋出来了。", "corrected_sentence": "这次胜利让人心振奋起来了。", "error_description": "补语错误：“振奋”表示情绪由弱到强，应说“起来”，不说“出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喝", "is_correct": false, "explanation": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。"}, {"text": "疏远", "is_correct": true, "explanation": "疏远：与“连在一起”意思相反，指感情变得不亲近。"}, {"text": "写", "is_correct": false, "explanation": "写：与“连在一起”没有反义关系，“写”指用笔记录文字。"}, {"text": "睡", "is_correct": false, "explanation": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}], "correct_answer": "疏远", "explanations": {"喝": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。", "疏远": "疏远：与“连在一起”意思相反，指感情变得不亲近。", "写": "写：与“连在一起”没有反义关系，“写”指用笔记录文字。", "睡": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画", "is_correct": false, "explanation": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。"}, {"text": "疏远", "is_correct": true, "explanation": "疏远：与“连在一起”意思相反，指感情变得不亲近。"}, {"text": "跑", "is_correct": false, "explanation": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。"}, {"text": "跳", "is_correct": false, "explanation": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}], "correct_answer": "疏远", "explanations": {"画": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。", "疏远": "疏远：与“连在一起”意思相反，指感情变得不亲近。", "跑": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。", "跳": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人心、感情或力量相互联结，融为一个整体。", "primary_collocate": null, "pronunciation": "lián zài yì qǐ", "ipa": "ljɛn tsaɪ i tɕʰi", "syllable_count": 4, "sentences": [{"text": "面对面讲故事，能让人心连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人的心连在一起，生活很幸福。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌的时候，大家的心连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事把大家的心连在一起了。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的队伍里，大家的心紧紧连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲和孩子的感情连在一起，分不开。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛让全国人民的心连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的梦想让我们连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让两家人连在一起，成了好朋友。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一首老歌把几代人连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连在一起了", "label": "完成体"}, {"form": "連在一起", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人心、感情或力量相互连接成为整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运送", "is_correct": false, "explanation": "搭配：“运送”针对货物或人员，不能说“运送人心”。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：人心或感情相互连接成一体，与“能让人心”的语境相符。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要带宾语，如“拆房子”，这里缺少宾语，句子说不通。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”指印刷发行书刊，不能说“让人心出版”。"}], "explanations": {"运送": "搭配：“运送”针对货物或人员，不能说“运送人心”。", "连在一起": "连在一起：人心或感情相互连接成一体，与“能让人心”的语境相符。", "拆": "配价：“拆”要带宾语，如“拆房子”，这里缺少宾语，句子说不通。", "出版": "搭配：“出版”指印刷发行书刊，不能说“让人心出版”。"}, "sentence_index": 0, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这三笔开销连在一起，超过了一万块。", "explanation": "这里应该用〈加在一起〉。“连在一起”指事物相互接合，计算总数要说“加在一起”。"}, {"text": "几个老同学连在一起吃了顿饭。", "explanation": "这里应该用〈聚在一起〉。“连在一起”指事物相互接合成整体，人们相聚吃饭要说“聚在一起”。"}, {"text": "他连在一起哭了三天。", "explanation": "这里应该用〈连续〉。“连在一起”指相互连接，不表示时间上接连不断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装修", "is_correct": false, "explanation": "搭配：“装修”多用于房屋，不能说“装修人民的心”。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算数或估量，与“比赛让全国人民”的语境不符，句子说不通。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：人心或感情相互连接成一体，与“比赛让全国人民”的语境相符。"}, {"text": "发射", "is_correct": false, "explanation": "搭配：“发射”用于火箭、卫星等，不能说“发射人心”。"}], "explanations": {"装修": "搭配：“装修”多用于房屋，不能说“装修人民的心”。", "计算": "语义：“计算”指算数或估量，与“比赛让全国人民”的语境不符，句子说不通。", "连在一起": "连在一起：人心或感情相互连接成一体，与“比赛让全国人民”的语境相符。", "发射": "搭配：“发射”用于火箭、卫星等，不能说“发射人心”。"}, "sentence_index": 6, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几台服务器连在一起，可以共享数据。", "explanation": "这里指用设备互相联网，是“连在一起”的另一个义项；本句说的是设备，不是人心或感情相连。"}, {"text": "车厢里的乘客连在一起站着。", "explanation": "这里应该用〈挤在一起〉。“连在一起”指物体接合，形容人群拥挤要说“挤在一起”。"}, {"text": "几种酱料连在一起，调出了一种新味道。", "explanation": "这里应该用〈混在一起〉。“连在一起”指物体接合成整体，几种调料相融要说“混在一起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母的心把连在一起了，家里很温暖。", "corrected_sentence": "父母的心连在一起了，家里很温暖。", "error_description": "“把”字句中，“把”后必须带宾语。这里“把”后直接接动词“连”，没有宾语，应去掉“把”，说“父母的心连在一起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动让两家人的心很连在一起，关系更好了。", "corrected_sentence": "这次活动让两家人的心紧紧连在一起，关系更好了。", "error_description": "“很”是程度副词，不能修饰“连在一起”这类动词结构；这里应用“紧紧”修饰，表示感情联系牢固，正确为“紧紧连在一起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
