INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "屏幕是电子设备上用于显示图像和文字的部件。", "primary_collocate": null, "pronunciation": "píng mù", "ipa": "pʰiŋ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "这种交流比看屏幕更有温度。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我的手机屏幕太小了。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屏幕上的字太小，我看不清。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直看着屏幕，没有说话。", "target_word": "屏幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块屏幕很大，看电影很清楚。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把屏幕调亮一点。", "target_word": "屏幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕太亮，晚上看会累。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在屏幕上写了今天的作业。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕坏了，我要去修。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屏幕上有一只小猫。", "target_word": "屏幕", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "手机屏幕", "label": "复合"}, {"form": "电脑屏幕", "label": "复合"}], "register": "中性", "sense_fingerprint": "手机、平板等电子设备上显示图像和文字的部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屏幕", "is_correct": true, "explanation": "“屏幕”是看的对象，与面对面的“交流”形成对比。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“看”不接“空气”，“比看空气”搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头冷硬，与“有温度”相反，句子不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音是听的，不能“看”，“比看声音”搭配不当。"}], "explanations": {"屏幕": "“屏幕”是看的对象，与面对面的“交流”形成对比。", "空气": "搭配：“看”不接“空气”，“比看空气”搭配不当。", "石头": "语义：石头冷硬，与“有温度”相反，句子不通。", "声音": "搭配：声音是听的，不能“看”，“比看声音”搭配不当。"}, "sentence_index": 0, "correct_answer": "屏幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打开屏幕，让屋里有了新鲜空气。", "explanation": "这里应该用〈窗户〉。屏幕是显示画面的部件，不能开关来通风。"}, {"text": "他推开屏幕走了出去。", "explanation": "这里应该用〈门〉。屏幕不能推开让人出入，出入要用门。"}, {"text": "她拉开屏幕，拿出了一支笔。", "explanation": "这里应该用〈抽屉〉。屏幕不能拉开取物，取物要用抽屉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屏幕", "is_correct": true, "explanation": "“手机屏幕”会发光，太亮会让晚上看的人觉得累。"}, {"text": "铃声", "is_correct": false, "explanation": "搭配：“亮”形容光线，不说“铃声太亮”，搭配不当。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池不发光，不会“太亮”，与句意不符。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不发光，与“太亮”和“看会累”都对不上。"}], "explanations": {"屏幕": "“手机屏幕”会发光，太亮会让晚上看的人觉得累。", "铃声": "搭配：“亮”形容光线，不说“铃声太亮”，搭配不当。", "电池": "语义：电池不发光，不会“太亮”，与句意不符。", "耳朵": "语义：耳朵不发光，与“太亮”和“看会累”都对不上。"}, "sentence_index": 6, "correct_answer": "屏幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块屏幕很甜。", "explanation": "这里应该用〈蛋糕〉。屏幕是显示画面的部件，不能用〈甜〉这种味觉词来形容。"}, {"text": "我坐在屏幕上休息。", "explanation": "这里应该用〈沙发〉。屏幕是显示画面的部件，不能用来坐；坐着休息要用沙发。"}, {"text": "妈妈煮屏幕。", "explanation": "这里应该用〈饺子〉。〈煮〉搭配饺子、面条等，屏幕不能煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕突然亮了出去。", "corrected_sentence": "屏幕突然亮了起来。", "error_description": "补语错误：屏幕由暗变亮，应说“亮了起来”，不说“亮了出去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客厅的墙上挂着一只屏幕，正在播放新闻。", "corrected_sentence": "客厅的墙上挂着一块屏幕，正在播放新闻。", "error_description": "量词错误：“屏幕”应用〈块〉，〈只〉用于动物、手脚等，不能计量屏幕。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
