INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用严厉的话告诉别人要改正错误。", "primary_collocate": null, "pronunciation": "xùn jiè", "ipa": "ɕyn˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "口头传统并非简单的信息传递，而是一种动态的、仪式性的交流实践，它将民间传说、道德训诫与集体记忆编织进代际传承的经纬之中。", "target_word": "训诫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师给了他一次严厉的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官对男孩进行了训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有听进父亲的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的训诫让大家都不敢再迟到。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次训诫之后，他再也没犯过错。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察给了司机一次口头训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对队长的训诫，球员低下了头。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老师的训诫记在了心里。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对违规的员工提出了严肃的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "上级或长辈用严厉的话指出错误、要求改正的告诫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "“训诫”指严厉指出错误的告诫，与“民间传说、道德”一起传承的语境相符。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告是商业宣传，不是代代相传的道德内容。"}, {"text": "税收", "is_correct": false, "explanation": "搭配：“税收”不能与“道德”并列作传承的内容。"}, {"text": "气象", "is_correct": false, "explanation": "语义：气象指天气状况，与道德传承无关。"}], "explanations": {"训诫": "“训诫”指严厉指出错误的告诫，与“民间传说、道德”一起传承的语境相符。", "广告": "语义：广告是商业宣传，不是代代相传的道德内容。", "税收": "搭配：“税收”不能与“道德”并列作传承的内容。", "气象": "语义：气象指天气状况，与道德传承无关。"}, "sentence_index": 0, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在班会上训诫了我的进步。", "explanation": "这里应该用〈表扬〉。“训诫”是严厉指出错误，不用于夸奖进步。"}, {"text": "老师用训诫的话安慰了我。", "explanation": "这里应该用〈安慰〉。“训诫”是严厉的告诫，不用于温和的安慰。"}, {"text": "老师用训诫的话让我更有信心。", "explanation": "这里应该用〈鼓励〉。“训诫”是严厉指出错误，不用来给人信心，表达鼓舞要用〈鼓励〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "“口头训诫”指警察口头指出司机的错误并告诫，语境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是工作的报酬，警察不会给司机“口头工资”。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影片，不能作为警察给司机的告诫。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“口头”不与“花朵”搭配，句意不通。"}], "explanations": {"训诫": "“口头训诫”指警察口头指出司机的错误并告诫，语境相符。", "工资": "语义：工资是工作的报酬，警察不会给司机“口头工资”。", "电影": "语义：电影是影片，不能作为警察给司机的告诫。", "花朵": "搭配：“口头”不与“花朵”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司对优秀员工给予了丰厚的训诫。", "explanation": "这里应该用〈奖励〉。“训诫”是严厉指出错误，不用于奖赏优秀员工。"}, {"text": "我真诚地训诫大家的帮助。", "explanation": "这里应该用〈感谢〉。“训诫”是严厉的告诫，不用于表达感激。"}, {"text": "长辈给了我们美好的训诫。", "explanation": "这里应该用〈祝福〉。“训诫”是严厉指出错误，不用于美好的祝愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练对队员进行了一把严肃的训诫。", "corrected_sentence": "教练对队员进行了一次严肃的训诫。", "error_description": "错误：量词“把”，应为“次”。“把”用于有柄的器物，训诫是一次次进行的动作，应用动作量词“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长对他进行了一棵训诫。", "corrected_sentence": "校长对他进行了一次训诫。", "error_description": "错误：量词“棵”，应为“次”。“棵”用于植物，训诫是一次次进行的动作，应用动作量词“次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "出是“进”的反义词，指从里面到外面，“出了电梯”即离开电梯。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，与“进”没有相反关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是身体落在座位上的动作，与“进”没有相反关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑是面部表情，与“进”没有相反关系。"}], "correct_answer": "出", "explanations": {"出": "出是“进”的反义词，指从里面到外面，“出了电梯”即离开电梯。", "跑": "跑是快速移动的动作，与“进”没有相反关系。", "坐": "坐是身体落在座位上的动作，与“进”没有相反关系。", "笑": "笑是面部表情，与“进”没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "出是“进”的反义词，指从里面到外面，“出门”即从屋里走到外面。"}, {"text": "躺", "is_correct": false, "explanation": "躺是身体平卧的动作，与“进”没有相反关系。"}, {"text": "读", "is_correct": false, "explanation": "读是看书出声或默念的动作，与“进”没有相反关系。"}, {"text": "哭", "is_correct": false, "explanation": "哭是流泪发出声音的表现，与“进”没有相反关系。"}], "correct_answer": "出", "explanations": {"出": "出是“进”的反义词，指从里面到外面，“出门”即从屋里走到外面。", "躺": "躺是身体平卧的动作，与“进”没有相反关系。", "读": "读是看书出声或默念的动作，与“进”没有相反关系。", "哭": "哭是流泪发出声音的表现，与“进”没有相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外面到里面；进入。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "老师进了教室。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请进，门没有锁。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进门的时候，我正在做饭。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一个一个进了电梯。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷，我们进屋吧。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没进过这家商店。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先敲门，再进房间。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫进了盒子，不肯出来。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子慢慢进了停车场。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都进店里躲雨。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进了", "label": "体标"}, {"form": "进过", "label": "体标"}, {"form": "进来", "label": "复合"}, {"form": "进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或物从外面移动到里面某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进", "is_correct": true, "explanation": "进 jìn：从外面到里面，意思是进入。"}, {"text": "金", "is_correct": false, "explanation": "金 jīn 与 jìn 声调不同（第一声），意思是金子。"}, {"text": "镜", "is_correct": false, "explanation": "镜 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是镜子。"}, {"text": "信", "is_correct": false, "explanation": "信 xìn 与 jìn 声母不同（x 与 j），意思是信件。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn 与 jìn 声调不同（第三声），意思是拉紧、紧张。"}, {"text": "计", "is_correct": false, "explanation": "计 jì 与 jìn 少了韵尾 -n，意思是计算、计划。"}], "explanations": {"进": "进 jìn：从外面到里面，意思是进入。", "金": "金 jīn 与 jìn 声调不同（第一声），意思是金子。", "镜": "镜 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是镜子。", "信": "信 xìn 与 jìn 声母不同（x 与 j），意思是信件。", "紧": "紧 jǐn 与 jìn 声调不同（第三声），意思是拉紧、紧张。", "计": "计 jì 与 jìn 少了韵尾 -n，意思是计算、计划。"}, "sentence_index": null, "correct_answer": "进"}, "level_3": {"options": [{"text": "进", "is_correct": true, "explanation": "进：“进了教室”即走进教室，与“老师”和“教室”相合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：吃的宾语应是食物，不能带“教室”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的宾语应是歌曲，不能说唱教室。"}, {"text": "脱", "is_correct": false, "explanation": "配价：脱的宾语应是衣物，不能带“教室”。"}], "explanations": {"进": "进：“进了教室”即走进教室，与“老师”和“教室”相合。", "吃": "配价：吃的宾语应是食物，不能带“教室”。", "唱": "搭配：唱的宾语应是歌曲，不能说唱教室。", "脱": "配价：脱的宾语应是衣物，不能带“教室”。"}, "sentence_index": 0, "correct_answer": "进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚从屋里出来，又进了外面。", "explanation": "这里应该用〈出去〉。进表示从外面到里面，“外面”正是进入的反方向，不能说“进了外面”。"}, {"text": "我们在山里进了一个小时的路。", "explanation": "这里应该用〈走〉。进表示进入，不指行走；走路要说“走了一个小时的路”。"}, {"text": "他每天进了一个小时的篮球，练得很辛苦。", "explanation": "这里应该用〈打〉。进表示进入，不指打球；打篮球要说“打了一个小时的篮球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "进", "is_correct": true, "explanation": "进 jìn：从外面到里面，意思是进入。"}, {"text": "斤", "is_correct": false, "explanation": "斤 jīn 与 jìn 声调不同（第一声），意思是重量单位斤。"}, {"text": "静", "is_correct": false, "explanation": "静 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是安静。"}, {"text": "仅", "is_correct": false, "explanation": "仅 jǐn 与 jìn 声调不同（第三声），意思是只、仅仅。"}, {"text": "记", "is_correct": false, "explanation": "记 jì 与 jìn 少了韵尾 -n，意思是记住、记录。"}], "explanations": {"进": "进 jìn：从外面到里面，意思是进入。", "斤": "斤 jīn 与 jìn 声调不同（第一声），意思是重量单位斤。", "静": "静 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是安静。", "仅": "仅 jǐn 与 jìn 声调不同（第三声），意思是只、仅仅。", "记": "记 jì 与 jìn 少了韵尾 -n，意思是记住、记录。"}, "sentence_index": null, "correct_answer": "进"}, "level_3": {"options": [{"text": "进", "is_correct": true, "explanation": "进：“进房间”即走进房间，与“敲门”的先后顺序相合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿的动作，不能咬房间。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘的宾语应是花果，不能说摘房间。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”不能直接带“房间”作宾语，说“跳房间”不成立。"}], "explanations": {"进": "进：“进房间”即走进房间，与“敲门”的先后顺序相合。", "咬": "语义：咬是用牙齿的动作，不能咬房间。", "摘": "搭配：摘的宾语应是花果，不能说摘房间。", "跳": "配价：“跳”不能直接带“房间”作宾语，说“跳房间”不成立。"}, "sentence_index": 6, "correct_answer": "进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "时间进了三点，大家该吃饭了。", "explanation": "这里应该用〈到〉。进表示进入某个空间，不用于时间；时间到了某一点要说“到”。"}, {"text": "他进了一张照片，挂在墙上。", "explanation": "这里应该用〈拍〉。进表示进入，不指拍照；拍照要说“拍了一张照片”。"}, {"text": "妈妈给我们进了一桌好菜。", "explanation": "这里应该用〈端〉。进表示进入，不指端上菜肴；端菜要说“端了一桌好菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钥匙进了口袋。", "corrected_sentence": "他把钥匙放进了口袋。", "error_description": "错误：把字句中漏掉了动词“放”，直接用“进”带宾语。正确应补上“放”，说“放进了口袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他进了过这个房间。", "corrected_sentence": "他进过这个房间。", "error_description": "错误：“进”后同时用了“了”和“过”。正确只用“过”，说“进过”，表示曾经进入过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
