INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12337, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示某个动作或情况到目前为止还没有发生，通常用来否定已经完成的状态。", "primary_collocate": null, "pronunciation": "shàng wèi", "ipa": "ʂɑŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这项工作尚未完成。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议尚未开始，大家先坐一下。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题尚未解决，我们还要再想办法。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他尚未回答我的问题。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新书尚未出版，现在还买不到。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结果尚未公布，请大家耐心等待。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子尚未成年，不能一个人开车。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，他的病尚未好转。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "目前尚未发现任何问题。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "文件尚未签字，所以还不能用。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面副词，表示到目前为止某事还没有发生或完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚未", "is_correct": true, "explanation": "「尚未」表示截至目前还没完成，与“这项工作”的语境相合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示每次都如此，一项工作只完成一次，句子不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示有时发生，与这项工作只完成一次的情况矛盾。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：「从不」用于否定习惯性动作，不能修饰一次性的“完成”。"}], "explanations": {"尚未": "「尚未」表示截至目前还没完成，与“这项工作”的语境相合。", "总是": "语义：「总是」表示每次都如此，一项工作只完成一次，句子不通。", "偶尔": "语义：「偶尔」表示有时发生，与这项工作只完成一次的情况矛盾。", "从不": "搭配：「从不」用于否定习惯性动作，不能修饰一次性的“完成”。"}, "sentence_index": 0, "correct_answer": "尚未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病情很重，但尚未在好转。", "explanation": "这里应该用〈还〉。尚未只表示还没发生的变化，不能与「在」连用来说明状态仍在持续，应说「还没好转」。"}, {"text": "他的眼睛尚未是蓝色的。", "explanation": "这里应该用〈一直〉。尚未只用于会发生变化的事，不能说明一直如此的固有属性，眼睛颜色不会是「尚未」才变成蓝色。"}, {"text": "这件事早已尚未告诉他。", "explanation": "这里误用〈尚未〉。事情很久以前就已发生，尚未只表示还没发生，应说「还没告诉他」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚未", "is_correct": true, "explanation": "「尚未」表示还没成年，与后句“不能一个人开车”的限制相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经成年」与后句“不能一个人开车”的理由相矛盾。"}, {"text": "早已", "is_correct": false, "explanation": "语义：「早已成年」同样与“不能一个人开车”的限制冲突。"}, {"text": "业已", "is_correct": false, "explanation": "语义：「业已成年」与后句“不能一个人开车”的限制相矛盾。"}], "explanations": {"尚未": "「尚未」表示还没成年，与后句“不能一个人开车”的限制相合。", "已经": "语义：「已经成年」与后句“不能一个人开车”的理由相矛盾。", "早已": "语义：「早已成年」同样与“不能一个人开车”的限制冲突。", "业已": "语义：「业已成年」与后句“不能一个人开车”的限制相矛盾。"}, "sentence_index": 6, "correct_answer": "尚未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次出门都尚未关灯。", "explanation": "这里应该用〈没〉。尚未指一件具体的事截至目前还没发生，不能用于每次都重复的习惯。"}, {"text": "这份合同已经尚未签字。", "explanation": "这里误用〈尚未〉。签字已完成，尚未只表示还没发生，应说「还没签字」。"}, {"text": "这个问题我们早就尚未解决。", "explanation": "这里误用〈尚未〉。问题很久以前就已解决，尚未只表示还没发生，应说「还没解决」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告尚未没写完，明天再交。", "corrected_sentence": "这份报告尚未写完，明天再交。", "error_description": "错误形式：“尚未没写完”；正确形式：“尚未写完”。〈尚未〉已经表示否定，不能再加〈没〉，应说「尚未写完」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事尚未结束了，我们先等等。", "corrected_sentence": "这件事尚未结束，我们先等等。", "error_description": "〈尚未〉表示截至目前还没发生，不能再加〈了〉表示已经完成，应说「尚未结束」或「还没结束呢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
