INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人说话传递信息和情感的有声表达方式", "primary_collocate": null, "pronunciation": "shēng yīn", "ipa": "ʂɤŋ˥ in˥", "syllable_count": 2, "sentences": [{"text": "她的声音很好听。", "target_word": "声音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话里传来妈妈的声音。", "target_word": "声音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师的声音很大，后面也能听见。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听声音，我就知道是你。", "target_word": "声音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话的声音越来越小。", "target_word": "声音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的声音里带着一点难过。", "target_word": "声音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你小声一点，不要提高声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的声音让大家都笑了。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的声音有点哑，可能感冒了。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话那头的声音听起来很着急。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个声音", "label": "量词"}, {"form": "一种声音", "label": "量词"}], "register": "中性", "sense_fingerprint": "人说话时发出的、能传递信息和情感的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用“好听”来形容。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指人发出的嗓音，可以用“好听”形容，与“她的……很好听”搭配，是正确答案。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“好听”只用于声音、歌曲等听觉对象，不能形容颜色。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，“好听”只能形容声音，不能用来说身材。"}], "explanations": {"味道": "语义：“味道”指气味或滋味，不能用“好听”来形容。", "声音": "“声音”指人发出的嗓音，可以用“好听”形容，与“她的……很好听”搭配，是正确答案。", "颜色": "搭配：“好听”只用于声音、歌曲等听觉对象，不能形容颜色。", "身材": "体貌：“身材”指体形，“好听”只能形容声音，不能用来说身材。"}, "sentence_index": 0, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外传来一只很大的声音。", "explanation": "这里应该用〈阵〉。“只”一般用于某些动物或成对的东西，“声音”要用“阵”“个”“种”等量词，不能用“只”。"}, {"text": "她把这个声音折成两半放进了包里。", "explanation": "这里把“声音”误当成可以折起来、放进包里的实物。“声音”是人说话发出的有声表达，没有形状，不能折叠。"}, {"text": "他伸手摸了摸这个声音。", "explanation": "这里把“声音”误当成了有形的实物，与“摸”搭配。“声音”是耳朵听到的响声，没有形状，不能用手去摸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，与“小声一点”说的音量要求无关。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指发出的响声，“提高”和“小声一点”都是针对音量说的，是正确答案。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“提高”不能跟“年龄”搭配，人的年龄只会增长，不能说“提高年龄”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热，与“小声一点”说的音量无关。"}], "explanations": {"速度": "语义：“速度”指快慢，与“小声一点”说的音量要求无关。", "声音": "“声音”指发出的响声，“提高”和“小声一点”都是针对音量说的，是正确答案。", "年龄": "搭配：“提高”不能跟“年龄”搭配，人的年龄只会增长，不能说“提高年龄”。", "温度": "语义：“温度”指冷热，与“小声一点”说的音量无关。"}, "sentence_index": 6, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很胖，大家都笑了。", "explanation": "这里应该用〈粗〉或〈细〉。“胖”用于形容体积大的人或物，声音的音色不能用“胖”来形容，这里误把它当成了体形的说法。"}, {"text": "这首歌的声音很辣，我不喜欢。", "explanation": "〈辣〉是味觉形容词，“声音”是耳朵听到的，不能用味道来形容。"}, {"text": "妈妈把这个声音放进了冰箱。", "explanation": "这里把“声音”误当成可以装进冰箱的实物。“声音”是耳朵听到的响声，没有形状，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电话里传来一只陌生的声音，问我是不是王老师。", "corrected_sentence": "电话里传来一个陌生的声音，问我是不是王老师。", "error_description": "“声音”的量词应用“个”，不用“只”。“只”一般用于动物或成对的东西，“一只声音”错误，应说“一个声音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼上传来一个沙哑声音，喊我下去吃饭。", "corrected_sentence": "楼上传来一个沙哑的声音，喊我下去吃饭。", "error_description": "错误形式：“沙哑声音”；正确形式：“沙哑的声音”。“沙哑”修饰“声音”时要加“的”，应说“沙哑的声音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
