INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在野外用木柴等可燃物堆集起来燃烧的火堆，常用于露营、聚会等。", "primary_collocate": null, "pronunciation": "gōu huǒ", "ipa": "kou˥ xuɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "村里的老人常在篝火旁讲古老的传说。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上，我们围着篝火唱歌。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在篝火旁听故事。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "营地中间有一堆篝火。", "target_word": "篝火", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风很大，篝火很快就灭了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在河边点起了一堆篝火。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一边烤肉，一边看着篝火。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火的光照红了大家的脸。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮以前，篝火慢慢变小了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往篝火里放了几块木头。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}], "register": "中性", "sense_fingerprint": "野外堆木柴燃烧的火堆，用于露营、聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“在篝火旁”指老人在火堆旁讲传说，符合“篝火”在野外燃烧的场景。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是厨房里的制冷家电，老人不会在冰箱旁讲传说，与场景不合。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是洗涤衣物的家电，与讲述古老传说的场景无关。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放废弃物的容器，与讲述传说的场景不合。"}], "explanations": {"篝火": "正确：“在篝火旁”指老人在火堆旁讲传说，符合“篝火”在野外燃烧的场景。", "冰箱": "语义：冰箱是厨房里的制冷家电，老人不会在冰箱旁讲传说，与场景不合。", "洗衣机": "语义：洗衣机是洗涤衣物的家电，与讲述古老传说的场景无关。", "垃圾桶": "语义：垃圾桶是盛放废弃物的容器，与讲述传说的场景不合。"}, "sentence_index": 0, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房的灶台里烧着篝火，锅里的水很快就开了。", "explanation": "这里应该用〈柴火〉。篝火是在野外堆起来燃烧的火，灶台里烧的是柴火。"}, {"text": "停电了，妈妈在桌上点了一根篝火。", "explanation": "这里应该用〈蜡烛〉。篝火是在野外堆起来的火堆，不能放在桌上，也不论“根”；室内照明用的是蜡烛。"}, {"text": "夜空中绽放着五彩的篝火。", "explanation": "这里应该用〈烟花〉。篝火是堆在地上燃烧的火，不会在夜空中绽放；五彩绽放的火光说的是烟花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“一边烤肉，一边看着篝火”，烤肉与篝火的场景一致。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：烤肉要用火加热，冰箱是制冷的，与“烤肉”的场景不协调。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，不能与“烤肉”的场景相配。"}, {"text": "文具", "is_correct": false, "explanation": "搭配：“看着”后接可见的景象或人，“文具”一般不作这样的对象。"}], "explanations": {"篝火": "正确：“一边烤肉，一边看着篝火”，烤肉与篝火的场景一致。", "冰箱": "语义：烤肉要用火加热，冰箱是制冷的，与“烤肉”的场景不协调。", "冰块": "语义：冰块遇热会融化，不能与“烤肉”的场景相配。", "文具": "搭配：“看着”后接可见的景象或人，“文具”一般不作这样的对象。"}, "sentence_index": 6, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的篝火很暖和，大家都围在一起。", "explanation": "这里应该用〈炉火〉。篝火是在野外堆木柴燃烧的火，屋里取暖一般用炉火。"}, {"text": "夜里我们举着篝火走路，照亮了山路。", "explanation": "这里应该用〈火把〉。篝火是堆在地上的火，不能举着走路；手持照明要用火把。"}, {"text": "屋顶的篝火很亮。", "explanation": "这里应该用〈电灯〉。篝火是堆在地上燃烧的火，不会装在屋顶；屋顶照明要用电灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜深了，村民们在空地上点起了一根篝火。", "corrected_sentence": "夜深了，村民们在空地上点起了一堆篝火。", "error_description": "量词错误：“篝火”的量词应为“堆”，“根”用于细长的东西。正确形式是“一堆篝火”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上，村民们在河边点起了一张篝火。", "corrected_sentence": "晚上，村民们在河边点起了一堆篝火。", "error_description": "量词错误：“篝火”的量词应为“堆”，“张”用于纸、桌子等平面的东西。正确形式是“一堆篝火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
