INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容声音高低起伏、停顿转折，富有节奏和变化。", "primary_collocate": null, "pronunciation": "yì yáng dùn cuò", "ipa": "i⁵¹ jaŋ³⁵ tuən⁵¹ tsʰuo⁵¹", "syllable_count": 4, "sentences": [{"text": "在书写系统尚未普及的社会里，长者以声音为媒介，在篝火旁、庭院中或节庆仪式上，通过抑扬顿挫的语调重构历史——这种叙事行为本身就是一种社会凝聚的仪式，它不依赖文本的固定性，而是通过每一次讲述的微妙变异，使历史保持活性，成为可被重新诠释的活体经验。", "target_word": "抑扬顿挫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师读诗的声音抑扬顿挫，同学们都听得入神。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话抑扬顿挫，台下的人听得很认真。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位播音员的朗读抑扬顿挫，非常好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她念课文时抑扬顿挫，像在唱歌一样。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷读报纸总是抑扬顿挫的，像在演讲。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员念台词抑扬顿挫，观众听了都鼓掌。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朗诵抑扬顿挫，让我想起了小时候的老师。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲故事抑扬顿挫，孩子们都安静下来。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗要读得抑扬顿挫才好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "声音高低起伏、停顿转折而有节奏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8255edc7-1bda-449e-b03b-0b60ad03ab09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。抑扬顿挫形容声音高低起伏、停顿有致，与“以声音为媒介”的讲述相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间大，不能修饰语调，“宽敞的语调”说不通。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”是颜色词，不能修饰语调，“通过雪白的语调”说不通。"}, {"text": "茂盛", "is_correct": false, "explanation": "搭配：“茂盛”形容草木，不能修饰语调。"}], "explanations": {"抑扬顿挫": "正确。抑扬顿挫形容声音高低起伏、停顿有致，与“以声音为媒介”的讲述相合。", "宽敞": "搭配：“宽敞”形容空间大，不能修饰语调，“宽敞的语调”说不通。", "雪白": "搭配：“雪白”是颜色词，不能修饰语调，“通过雪白的语调”说不通。", "茂盛": "搭配：“茂盛”形容草木，不能修饰语调。"}, "sentence_index": 0, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位播音员的朗读抑扬顿挫，语调毫无起伏。", "explanation": "这里应该用〈平淡〉。抑扬顿挫指声音有起伏，与“毫无起伏”自相矛盾；形容朗读平板应说〈平淡〉。"}, {"text": "这把椅子抑扬顿挫，坐起来很舒服。", "explanation": "这里应该用〈舒适〉。抑扬顿挫只形容声音的高低起伏，不能用来形容椅子这类物体。"}, {"text": "妈妈默读报纸，字句读得很抑扬顿挫。", "explanation": "这里误把〈抑扬顿挫〉当成了〈仔细〉的意思。该词只指有声朗读时的声音起伏，默读没有声音，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。念台词时声音有起伏、有停顿，与后文观众鼓掌相符。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：含糊指发音不清，观众听后鼓掌的反应与之矛盾。"}, {"text": "呆滞", "is_correct": false, "explanation": "体貌：呆滞多形容眼神、表情，不用来描写念台词的声音。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡指态度不热情，与观众听后热烈鼓掌的反应相矛盾。"}], "explanations": {"抑扬顿挫": "正确。念台词时声音有起伏、有停顿，与后文观众鼓掌相符。", "含糊": "语义：含糊指发音不清，观众听后鼓掌的反应与之矛盾。", "呆滞": "体貌：呆滞多形容眼神、表情，不用来描写念台词的声音。", "冷淡": "语义：冷淡指态度不热情，与观众听后热烈鼓掌的反应相矛盾。"}, "sentence_index": 6, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他结结巴巴地念诗，每一句都抑扬顿挫。", "explanation": "这里误把〈抑扬顿挫〉当成了〈流利〉的同义词。该词只描写声音的起伏和停顿有致，与断断续续的朗读无关。"}, {"text": "这座山抑扬顿挫，非常好看。", "explanation": "这里应该用〈起伏〉。抑扬顿挫只形容声音的高低停顿，不能形容山的形状。"}, {"text": "他的脾气抑扬顿挫，一会儿高一会儿低。", "explanation": "这里应该用〈喜怒无常〉。抑扬顿挫说的是声音的起伏，不能形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人用抑扬顿挫地声音讲故事。", "corrected_sentence": "老人用抑扬顿挫的声音讲故事。", "error_description": "“地”应改为“的”。“抑扬顿挫”修饰名词“声音”，作定语须用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他朗诵得抑扬顿挫地，同学们都很喜欢听。", "corrected_sentence": "他朗诵得抑扬顿挫，同学们都很喜欢听。", "error_description": "“抑扬顿挫”在“得”后作补语，不能再加“地”，应删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
