INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话或朗读时，句子里声音高低、轻重、快慢的变化，用来表达不同的意思和感情。", "primary_collocate": null, "pronunciation": "yǔ diào", "ipa": "y²¹⁴ tjɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "在书写系统尚未普及的社会里，长者以声音为媒介，在篝火旁、庭院中或节庆仪式上，通过抑扬顿挫的语调重构历史——这种叙事行为本身就是一种社会凝聚的仪式，它不依赖文本的固定性，而是通过每一次讲述的微妙变异，使历史保持活性，成为可被重新诠释的活体经验。", "target_word": "语调", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同一句话，语调不同，意思也不同。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语调很温柔，孩子慢慢安静了。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学中文时，语调和声调一样重要。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听她的语调，我知道她有点生气。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑问句的语调通常往上走。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的语调太平，没有感情。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说话的语调让我觉得很亲切。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用开心的语调回答了我的问题。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朗读时要注意语调的变化。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "句子里声音高低轻重快慢的变化，表达意思和感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8255edc7-1bda-449e-b03b-0b60ad03ab09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。讲述以声音为媒介，“抑扬顿挫的语调”指声音高低起伏的变化。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”是气味，不能用“抑扬顿挫的”修饰，句中说不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：音量指声音的大小，不能用“抑扬顿挫”修饰，也与句中的高低变化不符。"}, {"text": "字形", "is_correct": false, "explanation": "语义：字形是书写的形态，与“以声音为媒介”的语境冲突。"}], "explanations": {"语调": "正确。讲述以声音为媒介，“抑扬顿挫的语调”指声音高低起伏的变化。", "香味": "搭配：“香味”是气味，不能用“抑扬顿挫的”修饰，句中说不通。", "音量": "搭配：音量指声音的大小，不能用“抑扬顿挫”修饰，也与句中的高低变化不符。", "字形": "语义：字形是书写的形态，与“以声音为媒介”的语境冲突。"}, "sentence_index": 0, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学中文时，每个字的语调都要写准。", "explanation": "这里应该用〈笔画〉。语调指说话时声音的变化，不指书写；写字要说〈笔画〉。"}, {"text": "这张桌子的语调很结实。", "explanation": "这里应该用〈质地〉。语调只指说话时声音的变化，形容桌子结实应说质地。"}, {"text": "他一句话也没说，语调却很激动。", "explanation": "这里误把〈语调〉当成了〈神情〉。语调只指说话时声音的变化，没有说话时谈不上语调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。“语调太平”指说话时声音的高低变化不足，与“没有感情”相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通话设备，不能用“太平”形容，也与语调无关。"}, {"text": "发音", "is_correct": false, "explanation": "搭配：发音指字音是否准确，不用“太平”形容，也与“没有感情”的语境不合。"}, {"text": "笔迹", "is_correct": false, "explanation": "语义：笔迹是书写的痕迹，不能用来形容说话的声音。"}], "explanations": {"语调": "正确。“语调太平”指说话时声音的高低变化不足，与“没有感情”相合。", "电话": "语义：电话是通话设备，不能用“太平”形容，也与语调无关。", "发音": "搭配：发音指字音是否准确，不用“太平”形容，也与“没有感情”的语境不合。", "笔迹": "语义：笔迹是书写的痕迹，不能用来形容说话的声音。"}, "sentence_index": 6, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快学会了新语调，能和外国人交谈。", "explanation": "这里误把〈语调〉当成了〈语言〉。语调只指说话时声音的变化，不是一门语言，应说〈语言〉。"}, {"text": "这道菜的语调太咸了，我吃不下。", "explanation": "这里应该用〈味道〉。语调指说话时声音的变化，形容菜咸要用味道。"}, {"text": "这台电视的语调很清楚，画面也很好。", "explanation": "这里误把〈语调〉当成了〈音质〉。语调只指说话时声音的变化，形容电视的声音清楚应说〈音质〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的语调很温和得，我一下子放松了。", "corrected_sentence": "他的语调很温和，我一下子放松了。", "error_description": "“得”后面缺少补语，不能直接用在形容词“温和”之后；应删去“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朗读时要注意语调地起伏。", "corrected_sentence": "朗读时要注意语调的起伏。", "error_description": "“地”应改为“的”。“语调”修饰名词“起伏”，作定语须用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散与凝聚（集中在一起）意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "研究是深入探讨，与凝聚没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细看、察看，与凝聚没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是把东西从一处运到另一处，与凝聚没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散与凝聚（集中在一起）意思相反。", "研究": "研究是深入探讨，与凝聚没有反义关系。", "观察": "观察是仔细看、察看，与凝聚没有反义关系。", "搬运": "搬运是把东西从一处运到另一处，与凝聚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散与凝聚（集中在一起）意思相反。"}, {"text": "解释", "is_correct": false, "explanation": "解释是说明道理或含义，与凝聚没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理是使损坏的东西恢复原状，与凝聚没有反义关系。"}, {"text": "安排", "is_correct": false, "explanation": "安排是处理、布置事情，与凝聚没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散与凝聚（集中在一起）意思相反。", "解释": "解释是说明道理或含义，与凝聚没有反义关系。", "修理": "修理是使损坏的东西恢复原状，与凝聚没有反义关系。", "安排": "安排是处理、布置事情，与凝聚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指气体、液体等聚集；也比喻思想、感情等集中。", "primary_collocate": null, "pronunciation": "níng jù", "ipa": "niŋ˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "凝聚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌凝聚了老师们多年的心血。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的力量凝聚在一起，困难就不可怕了。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动凝聚了全村人的希望。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场比赛能凝聚整个城市的人心。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书凝聚着作者一生的经验。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的目标把大家凝聚在一起。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要凝聚更多的力量来做这件事。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话凝聚了所有人的信心。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子凝聚着一家人的回忆。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝聚了", "label": "体标"}, {"form": "凝聚着", "label": "体标"}, {"form": "凝聚力", "label": "复合"}], "register": "书面", "sense_fingerprint": "比喻思想、感情、力量、心血等集中在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31956932-1185-4de5-add8-d2c55acac8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚（níng jù）是本题目标词，指思想、感情、力量等集中在一起。"}, {"text": "名句", "is_correct": false, "explanation": "名句（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是有名的句子。"}, {"text": "名剧", "is_correct": false, "explanation": "名剧（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是著名的戏剧。"}, {"text": "凭据", "is_correct": false, "explanation": "凭据（píng jù）与凝聚（níng jù）的声母不同：p 与 n，意思是作为依据的证据。"}], "explanations": {"凝聚": "凝聚（níng jù）是本题目标词，指思想、感情、力量等集中在一起。", "名句": "名句（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是有名的句子。", "名剧": "名剧（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是著名的戏剧。", "凭据": "凭据（píng jù）与凝聚（níng jù）的声母不同：p 与 n，意思是作为依据的证据。"}, "sentence_index": null, "correct_answer": "凝聚"}, "level_3": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚表示力量、希望等集中在一起，与「凝聚起一种具象而坚韧的希望」的语境吻合，是本句的正确答案。"}, {"text": "分散", "is_correct": false, "explanation": "语义：分散指分开、散开，与句中「希望」被集中起来的意思相反。"}, {"text": "涣散", "is_correct": false, "explanation": "语义：涣散指松散、没有凝聚力，与「坚韧的希望」的语义冲突。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭多用于火焰、灯光，不能与「起」连用来组成「熄灭起一种希望」这样的结构。"}], "explanations": {"凝聚": "凝聚表示力量、希望等集中在一起，与「凝聚起一种具象而坚韧的希望」的语境吻合，是本句的正确答案。", "分散": "语义：分散指分开、散开，与句中「希望」被集中起来的意思相反。", "涣散": "语义：涣散指松散、没有凝聚力，与「坚韧的希望」的语义冲突。", "熄灭": "搭配：熄灭多用于火焰、灯光，不能与「起」连用来组成「熄灭起一种希望」这样的结构。"}, "sentence_index": 0, "correct_answer": "凝聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凝聚了一地碎玻璃。", "explanation": "这里应该用〈扫〉。凝聚指力量、人心、感情或液体、气体聚成一体，不用于清理碎玻璃。"}, {"text": "他亲手凝聚了一张桌子。", "explanation": "这里应该用〈制作〉。做桌子用的是制作，凝聚指东西聚集到一起，多用于力量、感情、气体、液体等，不用于做出器物。"}, {"text": "路边凝聚了很多落叶。", "explanation": "这里应该用〈堆积〉。凝聚用于抽象的力量或情感聚在一起，不用于落叶等具体物品堆在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚表示大家被集中在一起，与「共同的目标把大家……在一起」的语境吻合，是本句的正确答案。"}, {"text": "散布", "is_correct": false, "explanation": "语义：散布指分散到各处，与「把大家……在一起」的聚合语义相反。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：拆散指使分开、使分离，与句中「在一起」直接冲突。"}, {"text": "消磨", "is_correct": false, "explanation": "配价：消磨需接时间、意志等对象，不能组成「把大家消磨在一起」这样的结构。"}], "explanations": {"凝聚": "凝聚表示大家被集中在一起，与「共同的目标把大家……在一起」的语境吻合，是本句的正确答案。", "散布": "语义：散布指分散到各处，与「把大家……在一起」的聚合语义相反。", "拆散": "语义：拆散指使分开、使分离，与句中「在一起」直接冲突。", "消磨": "配价：消磨需接时间、意志等对象，不能组成「把大家消磨在一起」这样的结构。"}, "sentence_index": 6, "correct_answer": "凝聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一点点凝聚了不少零钱。", "explanation": "这里应该用〈积攒〉。积攒指一点点存起来，凝聚强调聚成一体，多用于力量、人心、感情，不用于零钱。"}, {"text": "会计凝聚了全部账目。", "explanation": "这里应该用〈汇总〉。汇总指把各项数字合在一起，凝聚不用于账目。"}, {"text": "妈妈凝聚了一锅粥。", "explanation": "这里应该用〈熬〉。凝聚指力量、人心、感情或液体、气体聚成一体，不用于做饭；熬粥应说熬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家的力量凝聚来，困难就不可怕了。", "corrected_sentence": "大家的力量凝聚起来，困难就不可怕了。", "error_description": "补语错误：「凝聚」后的趋向补语应为「起来」，不能只用「来」，应说「凝聚起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出把全校同学凝聚起在一起。", "corrected_sentence": "这次演出把全校同学凝聚在一起。", "error_description": "补语错误：「凝聚」后已接「在一起」，不能再加「起」，两者不能并用，应说「凝聚在一起」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流动性", "is_correct": true, "explanation": "“流动性”指事物能够移动、变化的特性，与“固定性”意思相反。"}, {"text": "硬度", "is_correct": false, "explanation": "“硬度”指物体抵抗压力的程度，与“固定性”不构成反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "“颜色”指色彩，与“固定性”不是反义关系。"}, {"text": "味道", "is_correct": false, "explanation": "“味道”指气味或滋味，与“固定性”没有反义关系。"}], "correct_answer": "流动性", "explanations": {"流动性": "“流动性”指事物能够移动、变化的特性，与“固定性”意思相反。", "硬度": "“硬度”指物体抵抗压力的程度，与“固定性”不构成反义关系。", "颜色": "“颜色”指色彩，与“固定性”不是反义关系。", "味道": "“味道”指气味或滋味，与“固定性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流动性", "is_correct": true, "explanation": "“流动性”指事物能够移动、变化的特性，与“固定性”意思相反。"}, {"text": "亮度", "is_correct": false, "explanation": "“亮度”指光线明亮的程度，与“固定性”没有反义关系。"}, {"text": "密度", "is_correct": false, "explanation": "“密度”指单位体积的质量，与“固定性”不构成反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "“温度”指冷热程度，与“固定性”没有反义关系。"}], "correct_answer": "流动性", "explanations": {"流动性": "“流动性”指事物能够移动、变化的特性，与“固定性”意思相反。", "亮度": "“亮度”指光线明亮的程度，与“固定性”没有反义关系。", "密度": "“密度”指单位体积的质量，与“固定性”不构成反义关系。", "温度": "“温度”指冷热程度，与“固定性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物保持稳定、不易变化或移动的特性。", "primary_collocate": null, "pronunciation": "gù dìng xìng", "ipa": "ku˥˩ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种材料的固定性很好，不容易变形。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子的固定性不够，一碰就会动。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安装时，要先检查零件的固定性。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种胶水的固定性很强。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语言的固定性让人们可以互相理解。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，帐篷的固定性特别重要。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个架子的固定性太差，我不敢放重东西。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们检查了机器的固定性。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，规则要有一定的固定性。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个书架的固定性很好，放着书也不会倒。", "target_word": "固定性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "事物稳定、不易变化或移动的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，与“不容易变形”描述的物理性质无关。"}, {"text": "固定性", "is_correct": true, "explanation": "“固定性”指材料牢固、不易变形的特性，与后半句相符，是正确答案。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般用于人或生物，不能说材料的“年龄”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与是否变形无关。"}], "explanations": {"价格": "语义：“价格”指钱数，与“不容易变形”描述的物理性质无关。", "固定性": "“固定性”指材料牢固、不易变形的特性，与后半句相符，是正确答案。", "年龄": "搭配：“年龄”一般用于人或生物，不能说材料的“年龄”。", "颜色": "语义：“颜色”指色彩，与是否变形无关。"}, "sentence_index": 0, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把固定性装进了箱子里。", "explanation": "这里把“固定性”误当成了可以装进箱子的实物。“固定性”是抽象的性质，不是物体，不能装进箱子。"}, {"text": "这个人的固定性很大方。", "explanation": "“大方”形容人的性格，“固定性”指事物不易移动的特性，不能用来形容人。"}, {"text": "这次比赛的固定性很快。", "explanation": "“快”指速度，“固定性”不指速度，不能说“很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "语义：“口味”指食物的滋味，与架子无关。"}, {"text": "固定性", "is_correct": true, "explanation": "“固定性”指架子牢固、不易移动的特性，与“太差，不敢放重东西”相符，是正确答案。"}, {"text": "音色", "is_correct": false, "explanation": "语义：“音色”指声音的特点，不能用来形容架子。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”用于人，不能用来描述家具。"}], "explanations": {"口味": "语义：“口味”指食物的滋味，与架子无关。", "固定性": "“固定性”指架子牢固、不易移动的特性，与“太差，不敢放重东西”相符，是正确答案。", "音色": "语义：“音色”指声音的特点，不能用来形容架子。", "学历": "搭配：“学历”用于人，不能用来描述家具。"}, "sentence_index": 6, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个书架的固定性很好吃。", "explanation": "“好吃”是味觉评价，“固定性”指事物稳固的特性，不能用来说“好吃”。"}, {"text": "这个书架的固定性很聪明。", "explanation": "“聪明”形容人的智力，“固定性”指事物稳固的特性，不能说“很聪明”。"}, {"text": "这个书架的固定性很红。", "explanation": "〈红〉是颜色词，“固定性”不是颜色，不能说“很红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种零件的一只固定性很好，装上去很牢。", "corrected_sentence": "这种零件的固定性很好，装上去很牢。", "error_description": "错误形式：“一只固定性”；正确形式：“固定性”。〈固定性〉是抽象名词，不能用量词〈只〉计量，前面不加数量词，应说「这种零件的固定性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子的固定性好很，坐上去也不会晃。", "corrected_sentence": "这把椅子的固定性很好，坐上去也不会晃。", "error_description": "“很”应放在形容词“好”前面修饰“好”，应说“很好”，不能说“好很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
