INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "睡眠过程中出现的一系列视觉、听觉等心理活动，也指不切实际的幻想。", "primary_collocate": null, "pronunciation": "mèng", "ipa": "məŋ˥˩", "syllable_count": 1, "sentences": [{"text": "昨晚我做了一个奇怪的梦。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梦太真了，我醒来还很害怕。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当医生是我从小的梦。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的梦终于变成了现实。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜我从梦里醒了过来。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一个梦，不要太当真。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的梦是去世界各地旅行。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梦里我回到了小时候的家。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的梦很大，要一步一步去实现。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的梦我一点也不记得了。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夢", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "做梦", "label": "复合"}, {"form": "梦想", "label": "复合"}, {"form": "梦境", "label": "复合"}], "register": "中性", "sense_fingerprint": "睡眠中的心理活动；也指幻想、理想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba9a7b9-9fdc-48f2-ac56-de532a27db8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦（mèng）是本题目标词，指睡眠中出现的心理活动，也指不切实际的幻想。"}, {"text": "猛", "is_correct": false, "explanation": "猛（měng，第三声）与 mèng（第四声）声调不同，意思是凶猛。"}, {"text": "闷", "is_correct": false, "explanation": "闷（mèn）与 mèng 只差韵尾（en 与 eng），意思是闷热。"}, {"text": "蒙", "is_correct": false, "explanation": "蒙（méng，第二声）与 mèng 声调不同，意思是蒙住。"}, {"text": "萌", "is_correct": false, "explanation": "萌（méng，第二声）与 mèng 声调不同，意思是萌芽。"}], "explanations": {"梦": "梦（mèng）是本题目标词，指睡眠中出现的心理活动，也指不切实际的幻想。", "猛": "猛（měng，第三声）与 mèng（第四声）声调不同，意思是凶猛。", "闷": "闷（mèn）与 mèng 只差韵尾（en 与 eng），意思是闷热。", "蒙": "蒙（méng，第二声）与 mèng 声调不同，意思是蒙住。", "萌": "萌（méng，第二声）与 mèng 声调不同，意思是萌芽。"}, "sentence_index": null, "correct_answer": "梦"}, "level_3": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦与“昨晚我做了一个奇怪的”搭配，指睡眠中出现的心理活动。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做”不能带“天气”，“做了一个奇怪的天气”不成立。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“做”不能带“河流”，“做了一个河流”没有这样的说法。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”是早上吃的，与“昨晚”的时间冲突。"}], "explanations": {"梦": "梦与“昨晚我做了一个奇怪的”搭配，指睡眠中出现的心理活动。", "天气": "搭配：“做”不能带“天气”，“做了一个奇怪的天气”不成立。", "河流": "搭配：“做”不能带“河流”，“做了一个河流”没有这样的说法。", "早饭": "语义：“早饭”是早上吃的，与“昨晚”的时间冲突。"}, "sentence_index": 0, "correct_answer": "梦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的梦挂在教室的墙上。", "explanation": "这里应该用〈成绩单〉。梦指睡眠中的心理活动或不切实际的幻想，不能挂在墙上展示，成绩单才能张贴。"}, {"text": "这次会议的梦定在下个月召开。", "explanation": "这里应该用〈安排〉。梦指睡眠中的心理活动或不切实际的幻想，不能指会议的时间安排，时间安排要用安排。"}, {"text": "这个梦很好，我们用它吧。", "explanation": "这里应该用〈方案〉。梦不能作为可以直接采用的具体方案，方案才能被选用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12353, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦（mèng）是本题目标词，指睡眠中出现的心理活动，也指不切实际的幻想。"}, {"text": "盟", "is_correct": false, "explanation": "盟（méng，第二声）与 mèng 声调不同，意思是结盟。"}, {"text": "懵", "is_correct": false, "explanation": "懵（měng，第三声）与 mèng 声调不同，意思是糊涂。"}, {"text": "锰", "is_correct": false, "explanation": "锰（měng，第三声）与 mèng 声调不同，是一种金属元素。"}, {"text": "焖", "is_correct": false, "explanation": "焖（mèn）与 mèng 只差韵尾（en 与 eng），意思是用小火慢煮。"}], "explanations": {"梦": "梦（mèng）是本题目标词，指睡眠中出现的心理活动，也指不切实际的幻想。", "盟": "盟（méng，第二声）与 mèng 声调不同，意思是结盟。", "懵": "懵（měng，第三声）与 mèng 声调不同，意思是糊涂。", "锰": "锰（měng，第三声）与 mèng 声调不同，是一种金属元素。", "焖": "焖（mèn）与 mèng 只差韵尾（en 与 eng），意思是用小火慢煮。"}, "sentence_index": null, "correct_answer": "梦"}, "level_3": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦与“她的”搭配，指她心中的理想或幻想，与“是去世界各地旅行”相符。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：“牛奶”不是计划或愿望，“她的牛奶是去世界各地旅行”不成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不能被当作要去旅行的目标，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“是……旅行”要求主语是计划或愿望，“身高”不能这样搭配。"}], "explanations": {"梦": "梦与“她的”搭配，指她心中的理想或幻想，与“是去世界各地旅行”相符。", "牛奶": "语义：“牛奶”不是计划或愿望，“她的牛奶是去世界各地旅行”不成立。", "眼睛": "语义：“眼睛”不能被当作要去旅行的目标，句子说不通。", "身高": "搭配：“是……旅行”要求主语是计划或愿望，“身高”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "梦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个梦明天必须完成。", "explanation": "这里应该用〈任务〉。梦指睡眠中的心理活动或幻想，不能指需要完成的任务。"}, {"text": "梦今天晚上要写完。", "explanation": "这里应该用〈作业〉。梦不是可以写完的东西，要写完的应是作业。"}, {"text": "这个月的梦是五千元。", "explanation": "这里应该用〈工资〉。梦不能表示金额，每月领取的钱数要用工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近做了一只奇怪的梦。", "corrected_sentence": "我最近做了一场奇怪的梦。", "error_description": "量词错误：“梦”前不能用量词“只”，“只”一般用于动物等。应改为“场”或“个”，正确说法是“我最近做了一场奇怪的梦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没做了过这样的梦。", "corrected_sentence": "我从没做过这样的梦。", "error_description": "体标错误：“做过”表示曾经经历过，“了”和“过”不能同时用在同一动词后。应说“我从没做过这样的梦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
