INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情的前后经过用语言或文字有条理地说出来或写下来。", "primary_collocate": null, "pronunciation": "xù shù", "ipa": "ɕy˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "叙述", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他向警察叙述了事情的经过。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按时间顺序叙述这件事。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者用简单的话叙述了旅行的过程。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她叙述得很清楚，大家都听懂了。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章叙述了一位老人的一生。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们叙述昨天的经历。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太会叙述，说得乱七八糟。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人叙述了当天晚上发生的事。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中叙述的故事发生在南方小城。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "叙述了", "label": "体标"}, {"form": "叙述着", "label": "体标"}, {"form": "叙述过", "label": "体标"}, {"form": "敘述", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有条理地说出或写下事情经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba9a7b9-9fdc-48f2-ac56-de532a27db8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12356, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：叙述指把事情的前后经过有条理地说出来或写下来。"}, {"text": "玉树", "is_correct": false, "explanation": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。"}, {"text": "虚数", "is_correct": false, "explanation": "声调：xū（第一声）与 xù（第四声）声调不同，意思是虚数（数学术语）。"}, {"text": "蓄水", "is_correct": false, "explanation": "韵母与声调：shuǐ 与 shù 韵母和声调都不同，意思是蓄水。"}], "explanations": {"叙述": "正确：叙述指把事情的前后经过有条理地说出来或写下来。", "玉树": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。", "虚数": "声调：xū（第一声）与 xù（第四声）声调不同，意思是虚数（数学术语）。", "蓄水": "韵母与声调：shuǐ 与 shù 韵母和声调都不同，意思是蓄水。"}, "sentence_index": null, "correct_answer": "叙述"}, "level_3": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：“叙述”是讲述事件经过的意思，与“宇宙观叙述”的说法相合。"}, {"text": "段子", "is_correct": false, "explanation": "语域：“段子”是口语化的玩笑故事，与这段学术化的书面表述不合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是记录费用的单子，与前文的宇宙观和神话事件无关。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：“宇宙观广告”不成搭配，这里要的是讲述祖先行动的叙述。"}], "explanations": {"叙述": "正确：“叙述”是讲述事件经过的意思，与“宇宙观叙述”的说法相合。", "段子": "语域：“段子”是口语化的玩笑故事，与这段学术化的书面表述不合。", "账单": "语义：“账单”是记录费用的单子，与前文的宇宙观和神话事件无关。", "广告": "搭配：“宇宙观广告”不成搭配，这里要的是讲述祖先行动的叙述。"}, "sentence_index": 0, "correct_answer": "叙述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房叙述了一锅汤。", "explanation": "这里应该用〈煮〉。叙述是讲述事情经过，做饭要用〈煮〉。"}, {"text": "他用文字叙述了这幅画的颜色和构图。", "explanation": "这里应该用〈描述〉。叙述用于讲述事件，说明画面的颜色和构图要用〈描述〉。"}, {"text": "工人叙述了钢板的质量。", "explanation": "这里应该用〈检验〉。叙述是讲事件的经过，查验质量要用〈检验〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12356, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：叙述指把事情的前后经过有条理地说出来或写下来。"}, {"text": "续书", "is_correct": false, "explanation": "声调：shū（第一声）与 shù（第四声）声调不同，意思是续书（续集）。"}, {"text": "玉树", "is_correct": false, "explanation": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。"}, {"text": "路数", "is_correct": false, "explanation": "声母：lù 与 xù 声母不同，意思是路数（做事的路子）。"}], "explanations": {"叙述": "正确：叙述指把事情的前后经过有条理地说出来或写下来。", "续书": "声调：shū（第一声）与 shù（第四声）声调不同，意思是续书（续集）。", "玉树": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。", "路数": "声母：lù 与 xù 声母不同，意思是路数（做事的路子）。"}, "sentence_index": null, "correct_answer": "叙述"}, "level_3": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：“叙述”是讲述的意思，与“昨天的经历”搭配。"}, {"text": "烧烤", "is_correct": false, "explanation": "搭配：“烧烤”的对象是食物，不能用于“昨天的经历”。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”需要具体的场所或物品作宾语，不能接“经历”这样的抽象对象。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，与“昨天的经历”的语义不相符。"}], "explanations": {"叙述": "正确：“叙述”是讲述的意思，与“昨天的经历”搭配。", "烧烤": "搭配：“烧烤”的对象是食物，不能用于“昨天的经历”。", "打扫": "配价：“打扫”需要具体的场所或物品作宾语，不能接“经历”这样的抽象对象。", "修理": "语义：“修理”指修复器物，与“昨天的经历”的语义不相符。"}, "sentence_index": 6, "correct_answer": "叙述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他叙述了一碗面条当午饭。", "explanation": "这里应该用〈吃〉。叙述是讲事情经过，不能用于吃东西。"}, {"text": "他用彩笔叙述了一幅风景画。", "explanation": "这里应该用〈描绘〉。叙述是讲述事件，描绘画面要用〈描绘〉。"}, {"text": "老师叙述了这个公式的含义。", "explanation": "这里应该用〈解释〉。叙述讲事件经过，说明公式的含义要用〈解释〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向警察叙述着了当天的情况。", "corrected_sentence": "他向警察叙述了当天的情况。", "error_description": "错误：“叙述着了”，“着”与“了”不能同时出现；正确为“叙述了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师叙述了过昨天的经历。", "corrected_sentence": "老师叙述过昨天的经历。", "error_description": "错误：“叙述了过”，“了”与“过”不能同用；正确为“叙述过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
