INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地貌是指地球表面各种形态的总称，如山地、平原、丘陵、盆地等。", "primary_collocate": null, "pronunciation": "dì mào", "ipa": "ti˥˩ mau˥˩", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "地貌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山地、平原和盆地都是地貌的类型。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的地貌很复杂，有山也有湖。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理课上，老师讲了中国的主要地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水多年冲刷，改变了这里的地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南的喀斯特地貌吸引了很多游客。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用卫星照片研究地貌的变化。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从飞机上看，沙漠地貌像一片金色的海。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地貌不同，当地人的生活方式也不同。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄土高原的地貌很特别，到处是沟。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "地貌学", "label": "复合"}], "register": "书面", "sense_fingerprint": "地球表面各种形态的总称（山地、平原、丘陵、盆地）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd77a6e-512b-404b-8c8e-391df7f0437e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服饰", "is_correct": false, "explanation": "语义：服饰是人为的穿着打扮，不是自然形成的地表形态，与“自然……的形成”矛盾。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表各种形态的总称，可以由自然作用形成，符合句意。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不是地表形态，不能说“自然人口的形成”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面语的语域不合。"}], "explanations": {"服饰": "语义：服饰是人为的穿着打扮，不是自然形成的地表形态，与“自然……的形成”矛盾。", "地貌": "地貌：地表各种形态的总称，可以由自然作用形成，符合句意。", "人口": "语义：人口不是地表形态，不能说“自然人口的形成”。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面语的语域不合。"}, "sentence_index": 0, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子地貌低，一下雨就积水。", "explanation": "这里应该用〈地势〉。地貌指地表形态的类型，不能用“低”来形容；说地面高低、起伏要用〈地势〉。"}, {"text": "夏天的时候，这里的地貌温度很高。", "explanation": "这里应该用〈地表〉。地貌指地表形态，不指地面的温度；说地面冷热要用〈地表〉。"}, {"text": "他的地貌很精神，大家都喜欢。", "explanation": "这里应该用〈样子〉。地貌指地表形态，不指人的外表；形容人看起来怎么样要用〈样子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语法", "is_correct": false, "explanation": "语义：卫星照片拍的是地表，无法用来研究语法的变化。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：卫星照片拍不到玩具的变化，玩具也不是地表形态。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表的形态，可以用卫星照片观察和研究其变化，符合句意。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语，与“科学家”“研究”的书面语域不合。"}], "explanations": {"语法": "语义：卫星照片拍的是地表，无法用来研究语法的变化。", "玩具": "语义：卫星照片拍不到玩具的变化，玩具也不是地表形态。", "地貌": "地貌：地表的形态，可以用卫星照片观察和研究其变化，符合句意。", "哥们儿": "语域：“哥们儿”是口语，与“科学家”“研究”的书面语域不合。"}, "sentence_index": 6, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里地貌很湿，小心滑倒。", "explanation": "这里应该用〈地面〉。地面可以湿、可以滑；地貌是地表形态的类型，不能形容潮湿。"}, {"text": "这是市中心的繁华地貌。", "explanation": "这里应该用〈地段〉。地段指城市中某一区域的位置，可以说繁华；地貌不指位置或繁华程度。"}, {"text": "我把地貌挂在墙上。", "explanation": "这里应该用〈地图〉。地图是画出地形的纸张，可以挂在墙上；地貌是大地表面本身的形态，不能挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只地貌在北方很常见。", "corrected_sentence": "这种地貌在北方很常见。", "error_description": "“地貌”前的量词错误：“只”用于动物等个体，应改为“种”，即“这种地貌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些地貌们在北方很特别。", "corrected_sentence": "这些地貌在北方很特别。", "error_description": "“们”一般只加在指人或拟人的名词后面，地貌是非生命的地表形态，不能加“们”；应去掉“们”，直接说“这些地貌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
