INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话是关于神仙或神化英雄的故事，反映了古代人民对自然现象、社会生活的解释和想象。", "primary_collocate": null, "pronunciation": "shén huà", "ipa": "ʂən˧˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "神话", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国有很多关于月亮的神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女娲补天是一个有名的神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人用神话来解释太阳和雨。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "希腊神话里有很多神和英雄。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱听神话，因为故事很神奇。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书收集了各地的神话和传说。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多古代神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的英雄常常能飞上天。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们讲一个自己国家的神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "则", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "神话故事", "label": "复合"}, {"form": "神話", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代人民对自然与社会的解释和想象，关于神仙和英雄的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd77a6e-512b-404b-8c8e-391df7f0437e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确答案，shén huà，指关于神仙和英雄的古代故事。"}, {"text": "深化", "is_correct": false, "explanation": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。"}, {"text": "人话", "is_correct": false, "explanation": "rén（第二声）与 shén（第二声）声母不同（r／sh），声调相同，意思是“人话”。"}, {"text": "生化", "is_correct": false, "explanation": "shēng（第一声，后鼻音）与 shén（第二声，前鼻音）读音相近，但“生化”指生物化学。"}], "explanations": {"神话": "正确答案，shén huà，指关于神仙和英雄的古代故事。", "深化": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。", "人话": "rén（第二声）与 shén（第二声）声母不同（r／sh），声调相同，意思是“人话”。", "生化": "shēng（第一声，后鼻音）与 shén（第二声，前鼻音）读音相近，但“生化”指生物化学。"}, "sentence_index": null, "correct_answer": "神话"}, "level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。前文提到“宇宙观叙述”和“祖先的行动”，“神话事件”指以神话为内容的事件，符合语境。"}, {"text": "科学", "is_correct": false, "explanation": "语义：“科学事件”与前文“祖先的行动”“宇宙观叙述”的语境不符，不能作为时间循环重启的节点。"}, {"text": "体育", "is_correct": false, "explanation": "语义：“体育事件”与前文的宇宙观和祖先叙述无关，不适合作为时间重启的节点。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲谈，与前文“非文本化的历史表达”的学术语域不合。"}], "explanations": {"神话": "正确。前文提到“宇宙观叙述”和“祖先的行动”，“神话事件”指以神话为内容的事件，符合语境。", "科学": "语义：“科学事件”与前文“祖先的行动”“宇宙观叙述”的语境不符，不能作为时间循环重启的节点。", "体育": "语义：“体育事件”与前文的宇宙观和祖先叙述无关，不适合作为时间重启的节点。", "八卦": "语域：“八卦”是口语化的闲谈，与前文“非文本化的历史表达”的学术语域不合。"}, "sentence_index": 0, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段神话记录了三百年前的一场战争。", "explanation": "这里应该用〈历史〉。神话是关于神仙和英雄的虚构故事，不用来记录真实发生的战争。"}, {"text": "这本神话讲述了鲁迅的一生。", "explanation": "这里应该用〈传记〉。神话讲的是神仙、英雄的故事，不写真实人物的生平。"}, {"text": "这篇神话报道了昨天的一场火灾。", "explanation": "这里应该用〈新闻〉。神话指虚构的神仙、英雄故事，不能用来叙述真实发生的火灾，这类时事应称〈新闻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。与“传说”并列，指关于神仙和英雄的古代故事，符合语境。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不是各地流传的故事，与后面的“传说”不能并列为一本书收集的内容。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“收集”一般用于可以聚集、保存的物件或资料，“脚步”不能被收集。"}, {"text": "电路", "is_correct": false, "explanation": "语义：电路是电学概念，不能与“传说”并列作为一本书收集的内容。"}], "explanations": {"神话": "正确。与“传说”并列，指关于神仙和英雄的古代故事，符合语境。", "数学": "语义：数学不是各地流传的故事，与后面的“传说”不能并列为一本书收集的内容。", "脚步": "搭配：“收集”一般用于可以聚集、保存的物件或资料，“脚步”不能被收集。", "电路": "语义：电路是电学概念，不能与“传说”并列作为一本书收集的内容。"}, "sentence_index": 6, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本神话的主人公是一个爱吃糖的小女孩。", "explanation": "这里应该用〈童话〉。神话写神仙、英雄的故事，写小女孩爱吃糖这类日常童趣的应说童话。"}, {"text": "这则神话讲的是我昨天在超市买菜的经过。", "explanation": "这里应该用〈日记〉。神话写神仙、英雄的故事，记录自己买菜的经过应说日记。"}, {"text": "这则神话介绍了我们学校去年的运动会。", "explanation": "这里应该用〈报道〉。神话是关于神仙和英雄的古代故事，介绍学校真实发生的活动应说报道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听外婆讲一座神话。", "corrected_sentence": "我小时候常听外婆讲一个神话。", "error_description": "“座”是用于山、楼房等大型固定物的量词，不能修饰神话；应改为“一个神话”，“个”是通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些古代神话们都很有意思。", "corrected_sentence": "这些古代神话都很有意思。", "error_description": "“们”一般只加在指人或拟人的名词后面，神话是非人的事物，不能说“神话们”；应去掉“们”，直接说“这些古代神话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
