INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重复或转述别人说过的话或内容。", "primary_collocate": null, "pronunciation": "fù shù", "ipa": "fu⁵¹ ʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "复述", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师让我复述这篇短文。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你复述一下刚才的故事。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老师的话复述了一遍。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复述课文能帮助我们记住内容。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友努力复述妈妈讲的故事。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真听着，然后复述了老师的问题。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生复述得很完整。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者复述了市长的话。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完录音，请用自己的话复述。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复述了", "label": "体标"}, {"form": "复述过", "label": "体标"}], "register": "中性", "sense_fingerprint": "重复或转述他人的话或内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd77a6e-512b-404b-8c8e-391df7f0437e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述 fù shù，指重复或转述别人说过的话或内容。"}, {"text": "复苏", "is_correct": false, "explanation": "fù sū 与 fù shù 声母（s/sh）和声调都不同，意思是恢复生机。"}, {"text": "户数", "is_correct": false, "explanation": "hù shù 与 fù shù 声母不同，意思是户口的数量。"}, {"text": "复书", "is_correct": false, "explanation": "fù shū（第一声）与 fù shù（第四声）声调不同，意思是回信。"}], "explanations": {"复述": "正确：复述 fù shù，指重复或转述别人说过的话或内容。", "复苏": "fù sū 与 fù shù 声母（s/sh）和声调都不同，意思是恢复生机。", "户数": "hù shù 与 fù shù 声母不同，意思是户口的数量。", "复书": "fù shū（第一声）与 fù shù（第四声）声调不同，意思是回信。"}, "sentence_index": null, "correct_answer": "复述"}, "level_3": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述指转述别人讲过的内容，这里指讲述往事的叙述。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于往事。"}, {"text": "启动", "is_correct": false, "explanation": "语义：“启动”指开动机器或程序，与叙述往事无关。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于冲刷或洗印，不能用于往事。"}], "explanations": {"复述": "正确：复述指转述别人讲过的内容，这里指讲述往事的叙述。", "修理": "搭配：“修理”针对器物，不能用于往事。", "启动": "语义：“启动”指开动机器或程序，与叙述往事无关。", "冲洗": "搭配：“冲洗”用于冲刷或洗印，不能用于往事。"}, "sentence_index": 0, "correct_answer": "复述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那扇门复述了一遍。", "explanation": "这里应该用〈关〉。复述只用于话或内容，关门要说关。"}, {"text": "他把那幅画复述了一遍。", "explanation": "这里应该用〈临摹〉。复述只用于话或内容，画要照着再画一遍应说临摹。"}, {"text": "他没听过这个故事，却复述得很完整。", "explanation": "这里应该用〈编造〉。复述要求先接触原内容，没听过的内容只能说编造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述指把听到的问题原样说出来，与“然后”的动作相符。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”用于食物、饮品，不能用于问题。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”指用摄像设备录下画面，与听后的回应无关。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：“撕毁”指把纸张等撕破，与“老师的问题”不符。"}], "explanations": {"复述": "正确：复述指把听到的问题原样说出来，与“然后”的动作相符。", "品尝": "搭配：“品尝”用于食物、饮品，不能用于问题。", "拍摄": "语义：“拍摄”指用摄像设备录下画面，与听后的回应无关。", "撕毁": "语义：“撕毁”指把纸张等撕破，与“老师的问题”不符。"}, "sentence_index": 6, "correct_answer": "复述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病复述了三次。", "explanation": "语义：复述指重复或转述说过的话或内容，病不是话语，病情再次出现应说〈复发〉。"}, {"text": "他把跑步复述了一遍。", "explanation": "语义：复述指重复或转述说过的话或内容，重复动作应说“重复”。"}, {"text": "他把那张桌子复述了一遍。", "explanation": "这里应该用〈擦〉。复述只用于话或内容，擦桌子要说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那段话复述了一个。", "corrected_sentence": "他把那段话复述了一遍。", "error_description": "“复述”的动量词应为“遍”，不能说“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经复述了了那段话。", "corrected_sentence": "他已经复述了那段话。", "error_description": "“复述”后只用一个“了”，“复述了了”重复了体标，应删去多余的那个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
