INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指已经过去的事情，常带有回忆或怀念的情感。", "primary_collocate": null, "pronunciation": "wǎng shì", "ipa": "wɑŋ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "往事", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老人常常想起年轻时的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿再提那些痛苦的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片让她想起许多美好的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友见面时，总爱聊起往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往事一件件浮现在我眼前。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些往事，他一直放在心里。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在窗前，回忆着往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，讲自己的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要总是活在往事里。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "已经过去、带有回忆或怀念情感的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事（wǎng shì）指已经过去的事情，即目标词。"}, {"text": "王室", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是王家的家族。"}, {"text": "忘事", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记事情。"}, {"text": "晚市", "is_correct": false, "explanation": "wǎn 与 wǎng 的韵母不同（an 与 ang），意思是晚上营业的市场。"}], "explanations": {"往事": "往事（wǎng shì）指已经过去的事情，即目标词。", "王室": "wáng（第二声）与 wǎng（第三声）声调不同，意思是王家的家族。", "忘事": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记事情。", "晚市": "wǎn 与 wǎng 的韵母不同（an 与 ang），意思是晚上营业的市场。"}, "sentence_index": null, "correct_answer": "往事"}, "level_3": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事指已经过去的事，可以被“复述”，符合句意。"}, {"text": "未来", "is_correct": false, "explanation": "语义：复述的对象必须是已经发生的事，“未来”尚未发生，无法复述。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是当下的自然状况，不是可以「复述」的故事或事件，与句意不合。"}, {"text": "身份", "is_correct": false, "explanation": "搭配：“复述”的对象是故事或事件，不能说“复述身份”。"}], "explanations": {"往事": "往事指已经过去的事，可以被“复述”，符合句意。", "未来": "语义：复述的对象必须是已经发生的事，“未来”尚未发生，无法复述。", "天气": "语义：天气是当下的自然状况，不是可以「复述」的故事或事件，与句意不合。", "身份": "搭配：“复述”的对象是故事或事件，不能说“复述身份”。"}, "sentence_index": 0, "correct_answer": "往事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学的专业是中国往事。", "explanation": "这里应该用〈历史〉。历史可指学科，往事只指已经过去的具体事情，不能作专业名称。"}, {"text": "他想起了一只往事。", "explanation": "这里应该用〈段〉。往事用“段”或“件”计量，“只”一般用于动物或成对的小物件。"}, {"text": "这个周末我有很多往事要做。", "explanation": "这里应该用〈事情〉。往事指已经过去的事，不能指需要去做的事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事指已经过去的事，可以“放在心里”，符合句意。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“放在心里”多用于回忆或感情，不能用于账单。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不是可以「放在心里」的事情，与句意不合。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：合同是具体的文书，一般不说“放在心里”。"}], "explanations": {"往事": "往事指已经过去的事，可以“放在心里”，符合句意。", "账单": "搭配：“放在心里”多用于回忆或感情，不能用于账单。", "闹钟": "语义：闹钟是物件，不是可以「放在心里」的事情，与句意不合。", "合同": "搭配：合同是具体的文书，一般不说“放在心里”。"}, "sentence_index": 6, "correct_answer": "往事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的往事是关于经济的。", "explanation": "这里应该用〈新闻〉。往事指以前发生的事，不能指今天刚发生、刚报道的消息。"}, {"text": "明天要发生的往事，我们都要提前准备。", "explanation": "这里应该用〈大事〉。往事指已经过去的事，不能指尚未发生的事。"}, {"text": "这只狗是我的往事，每天陪我散步。", "explanation": "这里应该用〈伙伴〉。往事指已经过去的事件，不指可以陪伴的生命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲起年轻时往事。", "corrected_sentence": "他讲起年轻时的往事。", "error_description": "“往事”前面有修饰语“年轻时”，修饰语和名词之间要加“的”，漏掉“的”不自然。正确说法是“年轻时的往事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些往事们，他始终记在心里。", "corrected_sentence": "那些往事，他始终记在心里。", "error_description": "“往事”是抽象名词，不能加“们”表示复数，应说“那些往事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
