INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12366, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "极其崇高而庄严，不可亵渎。", "primary_collocate": null, "pronunciation": "shén shèng", "ipa": "ʂən˧˥ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "神圣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在很多人心中，教堂是神圣的地方。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，教师是一份神圣的工作。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国家是每个公民神圣的责任。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人认为这座山很神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上，两个人说出了神圣的誓言。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对信徒来说，这本书非常神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得“母亲”这个词既普通又神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家安静地走进神圣的寺庙。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这份承诺看得很神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神聖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "崇高庄严、不可亵渎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神圣", "is_correct": true, "explanation": "神圣指崇高庄严，与“激活”的圣化时空及文化实践的语境相符。"}, {"text": "普通", "is_correct": false, "explanation": "语义：句子强调讲述“不仅是在复述”，而是一种文化实践，所激活的时空应崇高庄严，“普通”恰好与此相反。"}, {"text": "好玩", "is_correct": false, "explanation": "语域：“好玩”是口语，不适合这段书面的学术语境。"}, {"text": "廉价", "is_correct": false, "explanation": "搭配：“廉价”形容价格低，不能用来修饰通过讲述激活的仪式性“时空”。"}], "explanations": {"神圣": "神圣指崇高庄严，与“激活”的圣化时空及文化实践的语境相符。", "普通": "语义：句子强调讲述“不仅是在复述”，而是一种文化实践，所激活的时空应崇高庄严，“普通”恰好与此相反。", "好玩": "语域：“好玩”是口语，不适合这段书面的学术语境。", "廉价": "搭配：“廉价”形容价格低，不能用来修饰通过讲述激活的仪式性“时空”。"}, "sentence_index": 0, "correct_answer": "神圣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试很神圣，大家都很紧张。", "explanation": "这里应该用〈重要〉。神圣指崇高庄严，不用于一般的考试等事情。"}, {"text": "这个魔术很神圣，大家都看得很开心。", "explanation": "这里应该用〈神秘〉。神圣指崇高庄严，不指难以理解的东西，也不用于娱乐表演。"}, {"text": "这个发明很神圣，改变了很多人的生活。", "explanation": "这里应该用〈神奇〉。神圣指崇高庄严，不用于描述发明的奇妙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神圣", "is_correct": true, "explanation": "神圣指崇高庄严，“对信徒来说”的书籍属于这一类，符合句意。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”指温度高，是物理属性，不能用来描述书的性质。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”只能形容食物，与“这本书”不搭。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”用于速度，不用于形容书的性质。"}], "explanations": {"神圣": "神圣指崇高庄严，“对信徒来说”的书籍属于这一类，符合句意。", "滚烫": "语义：“滚烫”指温度高，是物理属性，不能用来描述书的性质。", "好吃": "语义：“好吃”只能形容食物，与“这本书”不搭。", "高速": "搭配：“高速”用于速度，不用于形容书的性质。"}, "sentence_index": 6, "correct_answer": "神圣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只玩具熊很神圣，小朋友都喜欢它。", "explanation": "这里应该用〈可爱〉。神圣指崇高庄严，不用于玩具这类日常物品。"}, {"text": "这家饭馆的菜很神圣，大家都抢着吃。", "explanation": "这里应该用〈好吃〉。神圣指崇高庄严，不用于形容食物的味道。"}, {"text": "这件衣服的价格很神圣。", "explanation": "这里应该用〈昂贵〉。神圣指崇高庄严，不用于描述价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是每个教徒神圣地誓言。", "corrected_sentence": "这是每个教徒神圣的誓言。", "error_description": "修饰名词「誓言」时，「神圣」后应用「的」，不用「地」（「地」用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这次聚会看很神圣。", "corrected_sentence": "她把这次聚会看得很神圣。", "error_description": "“把……看”后面带形容词作补语时要用“得”，漏掉“得”不自然，应说“看得很神圣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
