INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指话语或语言具有某种神秘力量，能影响现实，常用于虚构作品。", "primary_collocate": null, "pronunciation": "yán líng", "ipa": "jɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "叙事因此成为一种“言灵”式的存在——语言不仅描述世界，更建构现实。", "target_word": "言灵", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这部小说里的魔法师靠言灵打败了敌人。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个故事里，言灵能让说出口的话变成现实。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主角不小心说错话，言灵就让灾难发生了。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画里的少女用言灵保护了整座城市。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者把言灵写成一种古老的力量。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢在小说中使用言灵的设定。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在漫画里，言灵的力量会随着说话人的心情变化。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事中的王子被言灵困住，只能说真话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本奇幻小说里的言灵，来自古代的传说。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "虚构作品中能改变现实的话语神秘力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，与“语言不仅描述世界，更建构现实”的语境相合。"}, {"text": "石像", "is_correct": false, "explanation": "语义：石像不能“建构现实”，与句中强调语言的作用不符。"}, {"text": "图画", "is_correct": false, "explanation": "语义：图画不是语言，与“语言不仅描述世界”的语境冲突。"}, {"text": "岩石", "is_correct": false, "explanation": "搭配：“建构现实”的主语应是语言，“岩石”与“建构”搭配不当。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，与“语言不仅描述世界，更建构现实”的语境相合。", "石像": "语义：石像不能“建构现实”，与句中强调语言的作用不符。", "图画": "语义：图画不是语言，与“语言不仅描述世界”的语境冲突。", "岩石": "搭配：“建构现实”的主语应是语言，“岩石”与“建构”搭配不当。"}, "sentence_index": 0, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "远处传来一阵奇怪的言灵，像是有人在哭。", "explanation": "这里应该用〈声音〉。言灵指话语的神秘力量，不是耳朵能听见的声音。"}, {"text": "言灵过得很快，转眼就到了年底。", "explanation": "这里应该用〈时间〉。言灵指话语的神秘力量，不是流逝的时间，不能说“过得很快”。"}, {"text": "他郑重地立下言灵，要永远守护家人。", "explanation": "这里应该用〈誓言〉。言灵指话语的神秘力量，不是立下的承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，可以作为小说中的设定，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“设定”指故事中的规则或概念，“桌子”是家具，不能作为设定。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“使用……的设定”要求概念性的对象，“石头”不能用作设定。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能作为小说中的设定。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，可以作为小说中的设定，与句意相符。", "桌子": "语义：“设定”指故事中的规则或概念，“桌子”是家具，不能作为设定。", "石头": "搭配：“使用……的设定”要求概念性的对象，“石头”不能用作设定。", "饭菜": "语义：饭菜是食物，不能作为小说中的设定。"}, "sentence_index": 6, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们向言灵祈祷，希望天下太平。", "explanation": "这里应该用〈神灵〉。言灵指话语的神秘力量，不是有意志的神灵，不能向它祈祷。"}, {"text": "村里突然来了一个言灵，吓坏了大家。", "explanation": "这里应该用〈妖怪〉。言灵指话语的力量，不是会行动的生物。"}, {"text": "他从包里拿出一件言灵，递给了朋友。", "explanation": "这里应该用〈法宝〉。言灵是话语的力量，不是可以拿在手里的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里提到一只言灵，它来自古代。", "corrected_sentence": "书里提到一种言灵，它来自古代。", "error_description": "量词错误：“言灵”是抽象的力量，量词应用“种”，不能用“只”（“只”多用于动物或成对的物品）。正确说法是“一种言灵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家写了一个很有趣言灵设定。", "corrected_sentence": "这位作家写了一个很有趣的言灵设定。", "error_description": "漏掉“的”：“很有趣”修饰“言灵设定”时中间要加“的”。正确说法是“很有趣的言灵设定”，漏掉“的”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
