INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叙述或讲述某件事的人。", "primary_collocate": null, "pronunciation": "jiǎng shù zhě", "ipa": "tɕjɑŋ˨˩˦ ʂu˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "讲述者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个故事的讲述者是一位老渔民。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的讲述者会用声音吸引听众。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的讲述者一直没有出现在画面中。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲述者慢慢说起了四十年前的往事。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说用孩子做讲述者，读起来很亲切。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位讲述者记得每一个细节。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为讲述者，他把事故经过说得很清楚。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中的讲述者不是作者，而是一只猫。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播剧请来一位声音好听的讲述者。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "講述者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "叙述故事或事件的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是每次讲述时根据语境增删情节的人，与句中的“讲述”呼应。"}, {"text": "书写者", "is_correct": false, "explanation": "语义：书写者面对的是固定的文本，与“每一次讲述都是再创造”的对比相矛盾。"}, {"text": "文本", "is_correct": false, "explanation": "搭配：文本本身不能“根据语境”主动增删情节，这里需要有判断能力的行为者。"}, {"text": "观众", "is_correct": false, "explanation": "语义：句中已把“听众构成”列为另一方，观众不能同时成为增删情节的人。"}], "explanations": {"讲述者": "正确：讲述者是每次讲述时根据语境增删情节的人，与句中的“讲述”呼应。", "书写者": "语义：书写者面对的是固定的文本，与“每一次讲述都是再创造”的对比相矛盾。", "文本": "搭配：文本本身不能“根据语境”主动增删情节，这里需要有判断能力的行为者。", "观众": "语义：句中已把“听众构成”列为另一方，观众不能同时成为增删情节的人。"}, "sentence_index": 0, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的讲述者每天负责焊接钢板。", "explanation": "这里应该用〈焊工〉。讲述者指叙述故事或事件的人，负责焊接钢板的是焊工，不能用“讲述者”。"}, {"text": "这位讲述者每天在菜市场卖菜。", "explanation": "这里应该用〈菜贩〉。讲述者指叙述故事或事件的人，每天在菜市场卖菜的是菜贩，不能用“讲述者”。"}, {"text": "台下坐满了讲述者，大家都安静地听着。", "explanation": "这里应该用〈听众〉。讲述者是讲述故事的人，安静坐着听的是听众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是讲述经历并能记得细节的人，“这位”用于指人。"}, {"text": "失忆者", "is_correct": false, "explanation": "语义：失忆者记不住事情，与“记得每一个细节”直接矛盾。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：“作品”不是人，不能用“这位”计数，也不会“记得”细节。"}, {"text": "日记", "is_correct": false, "explanation": "搭配：日记是物件，不能用“这位”修饰，也不会“记得”。"}], "explanations": {"讲述者": "正确：讲述者是讲述经历并能记得细节的人，“这位”用于指人。", "失忆者": "语义：失忆者记不住事情，与“记得每一个细节”直接矛盾。", "作品": "搭配：“作品”不是人，不能用“这位”计数，也不会“记得”细节。", "日记": "搭配：日记是物件，不能用“这位”修饰，也不会“记得”。"}, "sentence_index": 6, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位讲述者帮忙修理电脑。", "explanation": "这里应该用〈维修员〉。讲述者指叙述故事或事件的人，修理电脑的是维修员，不能用“讲述者”。"}, {"text": "这位讲述者正在给病人打针。", "explanation": "这里应该用〈护士〉。讲述者指叙述故事或事件的人，给病人打针的是护士，不能用“讲述者”。"}, {"text": "这位讲述者正在田里插秧。", "explanation": "这里应该用〈农民〉。讲述者指叙述故事或事件的人，在田里插秧的是农民，不能用“讲述者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节目请来一只讲述者，他很会讲故事。", "corrected_sentence": "节目请来一位讲述者，他很会讲故事。", "error_description": "错误在量词：讲述者指人，应用“位”或“个”，不能用“只”。正确说法是“一位讲述者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目需要一位好的讲述者们。", "corrected_sentence": "这个节目需要一位好的讲述者。", "error_description": "错误在复数标记：“一位”表示单数，后面不能再加“们”，应说“一位好的讲述者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
