INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听演讲、广播、音乐等的人。", "primary_collocate": null, "pronunciation": "tīng zhòng", "ipa": "tʰiŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "听众", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "演讲结束后，听众热烈地鼓掌。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台节目有很多年轻听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，听众都安静地听着。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众打来电话，说想听一首老歌。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的演讲让听众笑了好几次。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里说，听众可以发短信参加活动。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下坐着三百多位听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手唱完后，听众还不想离开。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主持人很了解自己的听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽眾", "label": "繁体"}, {"form": "听众席", "label": "复合"}], "register": "中性", "sense_fingerprint": "听演讲、广播或音乐的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是听演讲、广播、音乐的人，与讲述者相对，是讲述所面向的对象。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是人群，无法与“社会需求”一起构成讲述的对象。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能接受讲述，“构成”一词要求人或群体。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“听众构成”搭配的是人群，天气不能作为这里的主体。"}], "explanations": {"听众": "正确：听众是听演讲、广播、音乐的人，与讲述者相对，是讲述所面向的对象。", "温度": "语义：温度不是人群，无法与“社会需求”一起构成讲述的对象。", "海洋": "语义：海洋不能接受讲述，“构成”一词要求人或群体。", "天气": "搭配：“听众构成”搭配的是人群，天气不能作为这里的主体。"}, "sentence_index": 0, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院里坐满了听众。", "explanation": "这里应该用〈观众〉。听众指听演讲、广播、音乐的人，在电影院看电影的是观众。"}, {"text": "这本小说的听众很多。", "explanation": "这里应该用〈读者〉。听众指听的人，阅读小说的是读者。"}, {"text": "电台的听众每天早上播新闻。", "explanation": "这里应该用〈播音员〉。听众指听广播的人，每天早上播新闻的是播音员，不能用“听众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是收听广播、能发短信参加活动的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能收听广播，也不能发短信。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是机器，不会发短信参加活动。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“参加活动”的主语须是有行为能力的人，玻璃不能作主语。"}], "explanations": {"听众": "正确：听众是收听广播、能发短信参加活动的人。", "石头": "语义：石头不能收听广播，也不能发短信。", "空调": "语义：空调是机器，不会发短信参加活动。", "玻璃": "搭配：“参加活动”的主语须是有行为能力的人，玻璃不能作主语。"}, "sentence_index": 6, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的球场上，两万名听众正在踢球。", "explanation": "这里应该用〈球员〉。听众指听演讲、广播、音乐的人，正在踢球的是球员，不能用“听众”。"}, {"text": "公交车上的听众很多。", "explanation": "这里应该用〈乘客〉。听众指听讲话或音乐的人，坐公交车的是乘客。"}, {"text": "婚礼上，听众宣布仪式正式开始。", "explanation": "这里应该用〈司仪〉。听众是听讲话或音乐的人，宣布仪式开始的是司仪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演唱会来了一只听众，他想听老歌。", "corrected_sentence": "这场演唱会来了一位听众，他想听老歌。", "error_description": "错误在量词：听众指人，应用“位”或“个”，不能用“只”。正确说法是“一位听众”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目里来了三台听众，很热闹。", "corrected_sentence": "这个节目里来了三位听众，很热闹。", "error_description": "错误在量词：听众指人，应用“位”或“个”，不能用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会或群体对某种事物、服务或行为的需要。", "primary_collocate": null, "pronunciation": "xū qiú", "ipa": "ɕy˥˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "人们对文化娱乐的需求越来越大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "rén men duì wén huà yú lè de xū qiú yuè lái yuè dà.", "sentence_source": "generated"}, {"text": "城市对公共文化服务的需求很大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "chéng shì duì gōng gòng wén huà fú wù de xū qiú hěn dà.", "sentence_source": "generated"}, {"text": "节假日里，人们对文化演出的需求突然变大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "jié jià rì lǐ, rén men duì wén huà yǎn chū de xū qiú tū rán biàn dà.", "sentence_source": "generated"}, {"text": "现在的年轻人对文化活动的需求越来越多。", "target_word": "需求", "complexity_tier": "T3", "furigana": "xiàn zài de nián qīng rén duì wén huà huó dòng de xū qiú yuè lái yuè duō.", "sentence_source": "generated"}, {"text": "文化市场的需求变小，剧团只好少演出一些。", "target_word": "需求", "complexity_tier": "T3", "furigana": "wén huà shì chǎng de xū qiú biàn xiǎo, jù tuán zhǐ hǎo shǎo yǎn chū yì xiē.", "sentence_source": "generated"}, {"text": "社区根据居民的文化需求，建了一个小图书室。", "target_word": "需求", "complexity_tier": "T3", "furigana": "shè qū gēn jù jū mín de wén huà xū qiú, jiàn le yí gè xiǎo tú shū shì.", "sentence_source": "generated"}, {"text": "现在纸质书的需求没有以前大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "xiàn zài zhǐ zhì shū de xū qiú méi yǒu yǐ qián dà.", "sentence_source": "generated"}, {"text": "这场音乐会满足了观众对艺术的需求。", "target_word": "需求", "complexity_tier": "T3", "furigana": "zhè chǎng yīn yuè huì mǎn zú le guān zhòng duì yì shù de xū qiú.", "sentence_source": "generated"}, {"text": "旅游旺季，人们对文化展览的需求特别大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "lǚ yóu wàng jì, rén men duì wén huà zhǎn lǎn de xū qiú tè bié dà.", "sentence_source": "generated"}, {"text": "农村对文化书籍的需求一直很大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "nóng cūn duì wén huà shū jí de xū qiú yì zhí hěn dà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "市场需求", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会或群体对某种事物、服务或行为的总体需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体征，不是人对文化娱乐的需要，“对文化娱乐的身高越来越大”说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“对文化娱乐的需求”指社会或个人对文化娱乐的需要，“越来越大”描述需要的程度，搭配自然。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是一种凭证，不能成为人对文化娱乐的需要，句子没有合理的意思。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“越来越大”不用来形容时间，时间的增减应说“越来越多”或“越来越长”。"}], "explanations": {"身高": "体貌：身高是人的体征，不是人对文化娱乐的需要，“对文化娱乐的身高越来越大”说不通。", "需求": "正确：“对文化娱乐的需求”指社会或个人对文化娱乐的需要，“越来越大”描述需要的程度，搭配自然。", "门票": "语义：门票是一种凭证，不能成为人对文化娱乐的需要，句子没有合理的意思。", "时间": "搭配：“越来越大”不用来形容时间，时间的增减应说“越来越多”或“越来越长”。"}, "sentence_index": 0, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校对学生的需求很严格。", "explanation": "这里应该用〈要求〉。“严格”形容对人或事的规定与标准，说“对学生的要求很严格”；“需求”不能说严格。"}, {"text": "他的需求是当一名医生。", "explanation": "这里应该用〈梦想〉。“梦想”指心中向往的理想，“需求”指社会或个人必须具备的东西，不能用来表示职业理想。"}, {"text": "这个社区有一只很大的需求。", "explanation": "这里应该用“种”。“只”用于动物或成对的东西，不能用来计量抽象的“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不能说大小，“纸质书的作者没有以前大”说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“纸质书的需求没有以前大”指人们对纸质书的需要量变小，搭配自然。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格用“高”或“低”来形容，不说“没有以前大”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能比较大小，“纸质书的颜色没有以前大”不成立。"}], "explanations": {"作者": "语义：作者是人，不能说大小，“纸质书的作者没有以前大”说不通。", "需求": "正确：“纸质书的需求没有以前大”指人们对纸质书的需要量变小，搭配自然。", "价格": "搭配：价格用“高”或“低”来形容，不说“没有以前大”。", "颜色": "语义：颜色不能比较大小，“纸质书的颜色没有以前大”不成立。"}, "sentence_index": 6, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农村需求更多的文化书籍。", "explanation": "这里应该用〈需要〉。“需求”是名词，不能直接带动词宾语“更多的文化书籍”；“需要”是动词，可以直接带宾语。"}, {"text": "社区需求组织一场文化讲座。", "explanation": "这里应该用〈打算〉。“打算”是动词，可以带动词宾语“组织一场文化讲座”；“需求”是名词，不能直接带动词宾语。"}, {"text": "农村有一条很大的需求。", "explanation": "这里应该用“种”。“条”用于长条形的东西，不能用来计量抽象的“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社会对文化服务的一只需求正在增长。", "corrected_sentence": "社会对文化服务的需求正在增长。", "error_description": "错误在“一只需求”。“需求”是抽象名词，不能用“只”计量；应去掉数量词，或者用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农村对电子书的一朵需求一直很大。", "corrected_sentence": "农村对电子书的需求一直很大。", "error_description": "错误在“一朵需求”。“朵”用于花朵等，不能用来计量抽象的“需求”；应去掉数量词，直接说“需求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展的经过或故事中的事件。", "primary_collocate": null, "pronunciation": "qíng jié", "ipa": "tɕʰiŋ˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "情节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影的情节很复杂，我看了两遍才懂。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要先了解案件的情节，再做决定。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把故事的情节一点一点讲给大家听。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的情节发展得很快。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他案件的情节，他说得很清楚。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的情节很复杂，必须仔细调查。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶讲的故事，情节简单，孩子们都爱听。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按时间顺序说一下故事的情节。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把课文的情节写成短文。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "情節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发展的经过，或故事里的一个个事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体征，不是讲述中可以增删或重构的内容，“对身高进行增删”说不通。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“对情节进行增删或重构”指对事件的具体经过做改动，与前文的讲述语境搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于讲述的内容，不能被“增删或重构”。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是凭证，不是讲述的内容，“对门票进行增删或重构”没有意义。"}], "explanations": {"身高": "体貌：身高是人的体征，不是讲述中可以增删或重构的内容，“对身高进行增删”说不通。", "情节": "正确：“对情节进行增删或重构”指对事件的具体经过做改动，与前文的讲述语境搭配。", "颜色": "语义：颜色不属于讲述的内容，不能被“增删或重构”。", "门票": "语义：门票是凭证，不是讲述的内容，“对门票进行增删或重构”没有意义。"}, "sentence_index": 0, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做这道菜的情节很简单，十分钟就学会了。", "explanation": "这里应该用〈步骤〉。“步骤”指做事的先后环节，做菜、操作多说“步骤”；“情节”只用于故事或事件的经过。"}, {"text": "这个实验的情节很简单，三步就完成了。", "explanation": "这里应该用〈过程〉。“过程”指事物发展变化的阶段，实验、生产多说“过程”；“情节”用于故事或事件的具体经过。"}, {"text": "这本小说有一块很精彩的情节。", "explanation": "这里应该用“段”或“个”。“块”用于块状或片状的东西，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“复杂”不修饰价格，价格应用“高”或“低”来形容。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“这件事的情节很复杂”指事件的具体经过较繁复，需要仔细调查，搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是事情的组成部分，“这件事的天气”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的体征，不能用于事情，“这件事的体重”不成立。"}], "explanations": {"价格": "搭配：“复杂”不修饰价格，价格应用“高”或“低”来形容。", "情节": "正确：“这件事的情节很复杂”指事件的具体经过较繁复，需要仔细调查，搭配自然。", "天气": "语义：天气不是事情的组成部分，“这件事的天气”说不通。", "体重": "体貌：体重是人的体征，不能用于事情，“这件事的体重”不成立。"}, "sentence_index": 6, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件的安装情节很简单，几步就完成了。", "explanation": "这里应该用〈程序〉。“程序”指按步骤进行的操作流程，软件安装用“程序”；“情节”只指故事或事件的具体经过。"}, {"text": "这次演出的情节非常壮观。", "explanation": "这里应该用〈场面〉。“壮观”形容场景和画面，“情节”不能用“壮观”来形容。"}, {"text": "这部小说有一束很有趣的情节。", "explanation": "这里应该用“段”或“个”。“束”多用于花、光线等成束的东西，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说的一朵情节很曲折，我一口气读完了。", "corrected_sentence": "这部小说的情节很曲折，我一口气读完了。", "error_description": "错误在“一朵情节”。“朵”用于花朵等，不能用来计量“情节”；应说“一段”或“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影的一幅情节很感人，我看了两遍。", "corrected_sentence": "这部电影的情节很感人，我看了两遍。", "error_description": "错误在“一幅情节”。“幅”用于画、布等平面作品，不能用来计量抽象的“情节”；应去掉数量词，直接说“情节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
