INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12379, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或状态持续存在，没有中断或消失。", "primary_collocate": null, "pronunciation": "cún xù", "ipa": "tsʰwən˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这种“变异中的存续”机制，使文化核心得以在形式变迁中维持精神连续性。", "target_word": "存续", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水资源并非取之不尽的背景性资源，而是维系文明存续的流动命脉。", "target_word": "存续", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家老店在城里存续了一百年。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要大家努力，传统就能存续下去。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的存续需要足够的资金。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种语言至今还存续着。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林是动物存续的基础。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会存续期间做了很多事。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的习俗在小村里存续至今。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和空气让生命得以存续。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存续了", "label": "体标"}, {"form": "存续着", "label": "体标"}, {"form": "存续期", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物或状态持续存在而不中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存续", "is_correct": true, "explanation": "正确：“变异中的存续”指事物持续存在的过程，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“变异”机制无关，“变异中的颜色机制”说不通。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压属于电学概念，与文化变迁中的机制无关。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“机制”不能与“音量”组合。"}], "explanations": {"存续": "正确：“变异中的存续”指事物持续存在的过程，符合语境。", "颜色": "语义：颜色与“变异”机制无关，“变异中的颜色机制”说不通。", "电压": "语义：电压属于电学概念，与文化变迁中的机制无关。", "音量": "搭配：“机制”不能与“音量”组合。"}, "sentence_index": 0, "correct_answer": "存续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都存续跑步。", "explanation": "这里应该用〈坚持〉。存续指事物或状态持续存在，不能表示人持续做某个动作。"}, {"text": "这场比赛因为大雨存续了。", "explanation": "这里应该用〈中断〉。存续表示持续存在、没有中断，与“中断”意思相反。"}, {"text": "他的梦想在一夜之间存续了。", "explanation": "这里应该用〈破灭〉。存续表示持续存在，不表示事物一下子消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存续", "is_correct": true, "explanation": "正确：“动物存续的基础”指动物能持续存在的条件，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与动物能否持续存在的基础无关。"}, {"text": "体积", "is_correct": false, "explanation": "语义：森林与动物的体积无关，“动物体积的基础”句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能作为森林支撑动物的基础。"}], "explanations": {"存续": "正确：“动物存续的基础”指动物能持续存在的条件，符合语境。", "颜色": "语义：颜色与动物能否持续存在的基础无关。", "体积": "语义：森林与动物的体积无关，“动物体积的基础”句意不通。", "味道": "语义：味道不能作为森林支撑动物的基础。"}, "sentence_index": 6, "correct_answer": "存续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支蜡烛突然存续了。", "explanation": "这里应该用〈熄灭〉。存续表示事物持续存在，不能表示火光突然消失。"}, {"text": "这次旅行因为下雨存续了。", "explanation": "这里应该用〈取消〉。存续表示持续存在，不能表示计划被取消。"}, {"text": "这份热情在一夜之间存续了。", "explanation": "这里应该用〈消失〉。存续表示持续存在，不表示热情一下子消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺靠年轻人才能存续上去。", "corrected_sentence": "这门手艺靠年轻人才能存续下去。", "error_description": "补语错误：表示事物继续存在应说“存续下去”，“上去”表示向上，不能与“存续”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古寺至今仍在存续历史。", "corrected_sentence": "这座古寺至今仍在存续。", "error_description": "宾语错误：“存续”是不及物动词，表示事物持续存在，不能直接带宾语，“存续历史”应改为“存续”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
