INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物持续不间断的性质或状态。", "primary_collocate": null, "pronunciation": "lián xù xìng", "ipa": "ljɛn˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种“变异中的存续”机制，使文化核心得以在形式变迁中维持精神连续性。", "target_word": "连续性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "红绿灯太多，影响了这条路的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡眠的连续性对身体很重要。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的故事缺少连续性，看不懂。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学习要有连续性，不能三天打鱼两天晒网。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据的连续性很好，中间一天也没有少。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "思路一断，工作的连续性就没有了。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段视频的连续性不好，画面总是跳。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保证生产的连续性，工厂二十四小时开机。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保证供水的连续性，水厂全年不停地运转。", "target_word": "连续性", "complexity_tier": "T3", "furigana": "wèi le bǎo zhèng gōng shuǐ de lián xù xìng, shuǐ chǎng quán nián bú tíng de yùn zhuǎn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "連續性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "事物持续不间断的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理性", "is_correct": false, "explanation": "语义：“物理性”指物质的物理特征，与“精神”的延续意义不符。"}, {"text": "化学性", "is_correct": false, "explanation": "搭配：“精神”不能与“化学性”搭配，句子说的是精神层面的延续。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指不间断地延续，“维持精神连续性”符合句意。"}, {"text": "生理性", "is_correct": false, "explanation": "语义：“生理性”指身体的机能特征，与文化精神的延续无关。"}], "explanations": {"物理性": "语义：“物理性”指物质的物理特征，与“精神”的延续意义不符。", "化学性": "搭配：“精神”不能与“化学性”搭配，句子说的是精神层面的延续。", "连续性": "“连续性”指不间断地延续，“维持精神连续性”符合句意。", "生理性": "语义：“生理性”指身体的机能特征，与文化精神的延续无关。"}, "sentence_index": 0, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种涂料的连续性很好，用了好几年颜色都没变。", "explanation": "这里应该用〈持久性〉。连续性指事情不间断，涂料强调耐用、经久，要用持久性。"}, {"text": "这种金属的连续性很强，导电性能很好。", "explanation": "这里应该用〈导电性〉。连续性指不间断，金属导电能力要说导电性。"}, {"text": "这盏灯的连续性很高，照得很亮。", "explanation": "这里应该用〈亮度〉。连续性指不间断，灯的明亮程度要说亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，工作不具有颜色，“工作的颜色就没有了”不通。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”用于材料、物体，不能说工作的硬度。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指工作不间断，“思路一断，工作的连续性就没有了”符合句意。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，工作没有形状，与句意不符。"}], "explanations": {"颜色": "语义：“颜色”指色彩，工作不具有颜色，“工作的颜色就没有了”不通。", "硬度": "搭配：“硬度”用于材料、物体，不能说工作的硬度。", "连续性": "“连续性”指工作不间断，“思路一断，工作的连续性就没有了”符合句意。", "形状": "语义：“形状”指物体的外形，工作没有形状，与句意不符。"}, "sentence_index": 6, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台仪器的连续性很高，测量结果很准。", "explanation": "这里应该用〈精确性〉。连续性指不间断，仪器测量的准确程度要说精确性。"}, {"text": "这块面料的连续性很好，穿着很舒服。", "explanation": "这里应该用〈柔软性〉。连续性指不间断，面料穿着舒服要说柔软性。"}, {"text": "这条毛巾的连续性很强，擦身体很快干。", "explanation": "这里应该用〈吸水性〉。连续性指不间断，毛巾擦干身体靠的是吸水性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水流连续性好很。", "corrected_sentence": "这条河的水流连续性很好。", "error_description": "“很”应放在形容词“好”前，修饰“好”；正确为“连续性很好”，“连续性好很”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告地连续性很强，前后衔接得很好。", "corrected_sentence": "这份报告的连续性很强，前后衔接得很好。", "error_description": "定语标记应用“的”，不能用“地”；正确为“报告的连续性很强”，“报告地连续性很强”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
