INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在民间流传的、关于人物或事件的叙述，常带有神话或历史色彩。", "primary_collocate": null, "pronunciation": "chuán shuō", "ipa": "ʈʂʰwan˧˥ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "口头传统并非简单的信息传递，而是一种动态的、仪式性的交流实践，它将民间传说、道德训诫与集体记忆编织进代际传承的经纬之中。", "target_word": "传说", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "传说", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当一则民间传说跨越千年仍能引发共鸣，其力量不在于事件的考古真实性，而在于它对人性困境的原型性捕捉。", "target_word": "传说", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一个很古老的传说。", "target_word": "传说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "关于这座山，当地有一个美丽的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶给我讲了一个龙的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个传说在民间流传了几百年。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中秋节有嫦娥奔月的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢收集各地的民间传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "传说里的英雄后来变成了一座山。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "则", "label": "量词"}, {"form": "民间传说", "label": "复合"}, {"form": "神话传说", "label": "复合"}, {"form": "傳說", "label": "繁体"}], "register": "中性", "sense_fingerprint": "民间流传、带神话或历史色彩的叙述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传说", "is_correct": true, "explanation": "正确：“民间传说”指民间流传的叙述，可以被编织进代际传承之中。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币不是民间流传的叙述，无法与“道德训诫与集体记忆”并列被编织进传承，句意不通。"}, {"text": "电路", "is_correct": false, "explanation": "语义：电路是技术装置，不能被编织进集体记忆，句意不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“民间”不修饰钢铁这类材料，“民间钢铁”不成词组。"}], "explanations": {"传说": "正确：“民间传说”指民间流传的叙述，可以被编织进代际传承之中。", "货币": "语义：货币不是民间流传的叙述，无法与“道德训诫与集体记忆”并列被编织进传承，句意不通。", "电路": "语义：电路是技术装置，不能被编织进集体记忆，句意不通。", "钢铁": "搭配：“民间”不修饰钢铁这类材料，“民间钢铁”不成词组。"}, "sentence_index": 0, "correct_answer": "传说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我家门口发生了一个很有意思的传说。", "explanation": "这里〈传说〉指流传很久的叙述，不能指昨天刚发生的事，应换成〈事〉。"}, {"text": "这些数字来自官方的传说。", "explanation": "这里〈传说〉指民间流传的叙述，不能作为统计数字的来源，应换成〈报告〉。"}, {"text": "这个传说是他亲眼看见的。", "explanation": "这里应该用〈事情〉。传说是口头流传的叙述，不能说是亲眼见到的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传说", "is_correct": true, "explanation": "正确：“在民间流传”搭配的是口耳相传的叙述，即“传说”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温无法在民间流传，“这个体温在民间流传了几百年”句意不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“流传”不搭配水泥这类有形的建材，不能说“水泥在民间流传”。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是物理量，不能在民间流传，句意不通。"}], "explanations": {"传说": "正确：“在民间流传”搭配的是口耳相传的叙述，即“传说”。", "体温": "语义：体温无法在民间流传，“这个体温在民间流传了几百年”句意不通。", "水泥": "搭配：“流传”不搭配水泥这类有形的建材，不能说“水泥在民间流传”。", "电压": "语义：电压是物理量，不能在民间流传，句意不通。"}, "sentence_index": 6, "correct_answer": "传说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的传说很便宜。", "explanation": "这里应该用〈票价〉。〈传说〉指民间流传的叙述，不能用“便宜”来形容。"}, {"text": "这条传说是今天早上刚刚播出的。", "explanation": "这里应该用〈新闻〉。〈传说〉指流传已久的叙述，不会是今天刚播出的。"}, {"text": "他的论文有充分的传说支持。", "explanation": "这里应该用〈数据〉。〈传说〉是民间流传的叙述，不能用来做论文的论据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听奶奶讲一张古老的传说。", "corrected_sentence": "我小时候常听奶奶讲一个古老的传说。", "error_description": "量词错误：〈传说〉应搭配〈个〉或〈则〉，〈张〉用于纸张、桌子等平面物，“一张传说”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲了一个很古老传说。", "corrected_sentence": "他讲了一个很古老的传说。", "error_description": "结构错误：〈很古老〉修饰名词时要加〈的〉，应说“很古老的传说”，漏掉〈的〉不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
