INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指战争、战斗或进行武力对抗的行为。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在那一战之后被反复讲起，人们借它强调勇气与牺牲；在丰收时节，它则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "战", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这一战打了三天三夜，双方都死了很多人。", "target_word": "战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一战之后，两国很多年没有再打。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老兵常常说起那一战，眼睛都红了。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一战关系到整个国家的命运。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一战他们输了，第二战才赢回来。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里详细写了那一战的经过。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过这一战，他成了有名的将军。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方人多，这一战很难打。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最后一战开始前，将军对士兵讲话。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "战争", "label": "复合"}, {"form": "战斗", "label": "复合"}, {"form": "戰", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "战争、战斗、武力对抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12384, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战", "is_correct": true, "explanation": "正确答案：听到的是“战”，意思是战争或战斗。"}, {"text": "占", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，“占”是占据的意思。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，“展”是展开的意思。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），“赞”是赞美的意思。"}, {"text": "颤", "is_correct": false, "explanation": "chàn 与 zhàn 声母不同（ch 与 zh），“颤”是发抖的意思。"}], "explanations": {"战": "正确答案：听到的是“战”，意思是战争或战斗。", "占": "zhān（第一声）与 zhàn（第四声）声调不同，“占”是占据的意思。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，“展”是展开的意思。", "赞": "zàn 与 zhàn 声母不同（z 与 zh），“赞”是赞美的意思。", "颤": "chàn 与 zhàn 声母不同（ch 与 zh），“颤”是发抖的意思。"}, "sentence_index": null, "correct_answer": "战"}, "level_3": {"options": [{"text": "战", "is_correct": true, "explanation": "正确：“那一战之后”指那场战斗结束以后，英雄传说在其后被反复讲起，语境合理。"}, {"text": "池塘", "is_correct": false, "explanation": "语义：池塘是水体，不是可以被反复讲起的事件，“那一池塘之后”句意不通。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川是自然地貌，不是可以被反复讲起的事件，“那一冰川之后”句意不通。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食是日常事务，不是一次事件，“那一饮食之后”句意不通。"}], "explanations": {"战": "正确：“那一战之后”指那场战斗结束以后，英雄传说在其后被反复讲起，语境合理。", "池塘": "语义：池塘是水体，不是可以被反复讲起的事件，“那一池塘之后”句意不通。", "冰川": "语义：冰川是自然地貌，不是可以被反复讲起的事件，“那一冰川之后”句意不通。", "饮食": "语义：饮食是日常事务，不是一次事件，“那一饮食之后”句意不通。"}, "sentence_index": 0, "correct_answer": "战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战下了一整天。", "explanation": "这里应该用〈雨〉。〈战〉指战斗，不能用“下”来描述。"}, {"text": "他是一名优秀的战。", "explanation": "这里应该用〈战士〉。〈战〉指战斗，不指人，不能说“一名优秀的战”。"}, {"text": "我的战坏了。", "explanation": "这里应该用〈电脑〉。〈战〉指战斗，不是可以“坏”的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12384, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "战", "is_correct": true, "explanation": "正确答案：听到的是“战”，意思是战争或战斗。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，“沾”是沾上、浸湿的意思。"}, {"text": "盏", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，“盏”是量词，指灯。"}, {"text": "詹", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，“詹”多用作姓氏。"}, {"text": "暂", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），“暂”是暂时的意思。"}], "explanations": {"战": "正确答案：听到的是“战”，意思是战争或战斗。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，“沾”是沾上、浸湿的意思。", "盏": "zhǎn（第三声）与 zhàn（第四声）声调不同，“盏”是量词，指灯。", "詹": "zhān（第一声）与 zhàn（第四声）声调不同，“詹”多用作姓氏。", "暂": "zàn 与 zhàn 声母不同（z 与 zh），“暂”是暂时的意思。"}, "sentence_index": null, "correct_answer": "战"}, "level_3": {"options": [{"text": "战", "is_correct": true, "explanation": "正确：“那一战的经过”指那场战斗的经过，与“书里详细写了”相符。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶子没有可以被“详细写了经过”的事件，句意不通。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗不是可以写经过的事件，“那一碗的经过”句意不通。"}, {"text": "椅", "is_correct": false, "explanation": "搭配：椅子应用量词“把”，不能说“那一椅”。"}], "explanations": {"战": "正确：“那一战的经过”指那场战斗的经过，与“书里详细写了”相符。", "瓶": "语义：瓶子没有可以被“详细写了经过”的事件，句意不通。", "碗": "语义：碗不是可以写经过的事件，“那一碗的经过”句意不通。", "椅": "搭配：椅子应用量词“把”，不能说“那一椅”。"}, "sentence_index": 6, "correct_answer": "战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都读战。", "explanation": "这里应该用〈书〉。〈战〉指战斗，不能用“读”。"}, {"text": "将军给士兵制定了一个好的战。", "explanation": "这里应该用〈战略〉。“制定”的对象是计划、战略，“战”不能被制定。"}, {"text": "他的战很好听。", "explanation": "这里应该用〈声音〉。〈战〉指战斗，不能用“好听”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一个战结束以后，村子里的人很少再提起。", "corrected_sentence": "那一战结束以后，村子里的人很少再提起。", "error_description": "量词错误：〈战〉表示一次战斗时直接说“那一战”，不加量词〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那是最惨烈一的战。", "corrected_sentence": "那是最惨烈的一战。", "error_description": "语序错误：数词〈一〉应放在〈的〉之后、紧挨〈战〉，说“最惨烈的一战”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "秩序", "is_correct": false, "explanation": "与“勇气”无反义关系，“秩序”指有条理的正常状态。"}, {"text": "责任", "is_correct": false, "explanation": "与“勇气”无反义关系，“责任”指应当承担的义务。"}, {"text": "友谊", "is_correct": false, "explanation": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "秩序": "与“勇气”无反义关系，“秩序”指有条理的正常状态。", "责任": "与“勇气”无反义关系，“责任”指应当承担的义务。", "友谊": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "桌子", "is_correct": false, "explanation": "与“勇气”无反义关系，“桌子”是家具。"}, {"text": "河流", "is_correct": false, "explanation": "与“勇气”无反义关系，“河流”是自然地理事物。"}, {"text": "节日", "is_correct": false, "explanation": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "桌子": "与“勇气”无反义关系，“桌子”是家具。", "河流": "与“勇气”无反义关系，“河流”是自然地理事物。", "节日": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "面对困难、危险或挑战时，表现出来的不畏缩、不害怕的精神。", "primary_collocate": null, "pronunciation": "yǒng qì", "ipa": "jʊŋ˨˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他有勇气面对失败。", "target_word": "勇气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她鼓起勇气，站到大家面前讲话。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说出真话需要很大的勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到困难时，我们不能没有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的勇气让大家都很感动。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于有了勇气，向老板提出辞职。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败以后，她又找回了勇气，重新开始。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对危险，消防员表现出了极大的勇气。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他缺少勇气，所以一直不敢去试。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，教练的话给了队员很大的勇气。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股勇气", "label": "量词"}, {"form": "勇氣", "label": "繁体"}], "register": "通用", "sense_fingerprint": "面对困难危险时不畏缩的精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。yǒng qì，指面对困难时不畏缩的精神。"}, {"text": "涌起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。"}, {"text": "用气", "is_correct": false, "explanation": "第一音节 yòng（第四声）与 yǒng（第三声）只差声调，意思是使用气体或气力。"}, {"text": "运气", "is_correct": false, "explanation": "第一音节 yùn（第四声）与 yǒng（第三声）声母相同，韵母与声调不同；第二音节 qì 完全相同。“运气”指命运、机遇，与“勇气”意思不同。"}], "explanations": {"勇气": "正确。yǒng qì，指面对困难时不畏缩的精神。", "涌起": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。", "用气": "第一音节 yòng（第四声）与 yǒng（第三声）只差声调，意思是使用气体或气力。", "运气": "第一音节 yùn（第四声）与 yǒng（第三声）声母相同，韵母与声调不同；第二音节 qì 完全相同。“运气”指命运、机遇，与“勇气”意思不同。"}, "sentence_index": null, "correct_answer": "勇气"}, "level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。“有勇气”后接“面对失败”，符合句意。"}, {"text": "财富", "is_correct": false, "explanation": "语义：“财富”指钱财或资源，无法用来面对失败。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有体重”虽可说，但“体重”不能承担“面对失败”这种心理动作。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是戴在眼睛上的物品，与面对失败毫无关系。"}], "explanations": {"勇气": "正确。“有勇气”后接“面对失败”，符合句意。", "财富": "语义：“财富”指钱财或资源，无法用来面对失败。", "体重": "搭配：“有体重”虽可说，但“体重”不能承担“面对失败”这种心理动作。", "眼镜": "语义：“眼镜”是戴在眼睛上的物品，与面对失败毫无关系。"}, "sentence_index": 0, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很有勇气，一遍遍地给我们讲解这道题。", "explanation": "这里应该用〈耐心〉。勇气指不怕困难的精神，反复讲解、不厌其烦要说“耐心”，不说“很有勇气”。"}, {"text": "他今天勇气很好，买彩票居然中了奖。", "explanation": "这里应该用〈运气〉。中奖靠的是运气，勇气指不怕困难的精神，不能说“勇气很好”。"}, {"text": "他的勇气很强，一个人就能修好这台机器。", "explanation": "这里应该用〈能力〉。勇气指不怕困难的精神，不能用来说明动手修机器的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。“找回”的是精神上的勇气，才能“重新开始”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，与失败后重新振作的心理无关。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”用来挡雨，句中没有雨，也不指精神状态。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“找回”的对象应是可以失去又回来的东西，“年龄”不能被找回。"}], "explanations": {"勇气": "正确。“找回”的是精神上的勇气，才能“重新开始”。", "钥匙": "语义：“钥匙”是开锁的工具，与失败后重新振作的心理无关。", "雨伞": "语义：“雨伞”用来挡雨，句中没有雨，也不指精神状态。", "年龄": "搭配：“找回”的对象应是可以失去又回来的东西，“年龄”不能被找回。"}, "sentence_index": 6, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用勇气解开了这道难题。", "explanation": "这里应该用〈智慧〉。勇气指不怕困难的精神，不能用来解题。"}, {"text": "他用勇气把那块大石头推开了。", "explanation": "这里应该用〈力气〉。推动重物要靠力气，勇气不能代替体力。"}, {"text": "他打篮球很有勇气，能轻松过人。", "explanation": "这里应该用〈技巧〉。过人靠的是技巧，勇气不能说明运球的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿出一个勇气，向大家承认了错误。", "corrected_sentence": "他拿出一股勇气，向大家承认了错误。", "error_description": "量词错误：“勇气”的量词是“股”，应说“一股勇气”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他鼓上勇气，才敢向大家道歉。", "corrected_sentence": "他鼓起勇气，才敢向大家道歉。", "error_description": "补语错误：“鼓”与“勇气”之间的结果补语应为“起”，说“鼓起勇气”，不能用“上”说“鼓上勇气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“丰收”无反义关系，“唱歌”是娱乐活动。"}, {"text": "散步", "is_correct": false, "explanation": "与“丰收”无反义关系，“散步”是一种悠闲的活动。"}, {"text": "旅行", "is_correct": false, "explanation": "与“丰收”无反义关系，“旅行”指到外地去游览。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "唱歌": "与“丰收”无反义关系，“唱歌”是娱乐活动。", "散步": "与“丰收”无反义关系，“散步”是一种悠闲的活动。", "旅行": "与“丰收”无反义关系，“旅行”指到外地去游览。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“丰收”无反义关系，“睡觉”是休息的行为。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“丰收”无反义关系，“跳舞”是一种身体活动。"}, {"text": "写字", "is_correct": false, "explanation": "与“丰收”无反义关系，“写字”指用笔写出文字。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "睡觉": "与“丰收”无反义关系，“睡觉”是休息的行为。", "跳舞": "与“丰收”无反义关系，“跳舞”是一种身体活动。", "写字": "与“丰收”无反义关系，“写字”指用笔写出文字。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指农作物获得大收成，也比喻成果丰富。", "primary_collocate": null, "pronunciation": "fēng shōu", "ipa": "fɤŋ˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "丰收", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年雨水好，小麦又丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民们高兴地庆祝丰收。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天是丰收的季节。", "target_word": "丰收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年苹果大丰收，果农笑得合不拢嘴。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地年年丰收，一亩能收一千斤。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过三年努力，我们的研究终于丰收了。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太旱，稻子没有丰收。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的稻田去年丰收，家家都有余粮。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年他学习上也丰收了，拿了三个奖。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丰收了", "label": "体标"}, {"form": "豐收", "label": "繁体"}], "register": "通用", "sense_fingerprint": "农作物大收成，也比喻成果丰富", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“丰收时节”与后文“突出与自然的和谐共生”的语境相合。"}, {"text": "饥荒", "is_correct": false, "explanation": "搭配：“时节”前多接农事或季节词，“饥荒”一般不说“饥荒时节”。"}, {"text": "战乱", "is_correct": false, "explanation": "语义：“战乱”与前文“战时”重复，且与“和谐共生”的语境矛盾。"}, {"text": "旱灾", "is_correct": false, "explanation": "语义：“旱灾”指干旱造成的灾害，与“和谐共生”的语境相悖。"}], "explanations": {"丰收": "正确。“丰收时节”与后文“突出与自然的和谐共生”的语境相合。", "饥荒": "搭配：“时节”前多接农事或季节词，“饥荒”一般不说“饥荒时节”。", "战乱": "语义：“战乱”与前文“战时”重复，且与“和谐共生”的语境矛盾。", "旱灾": "语义：“旱灾”指干旱造成的灾害，与“和谐共生”的语境相悖。"}, "sentence_index": 0, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的商品很丰收，什么都有。", "explanation": "这里应该用〈丰富〉。丰收指农作物或成果的大收成，商品多要说“丰富”。"}, {"text": "他每个月的丰收很多，工资也很高。", "explanation": "这里应该用〈收入〉。丰收不指个人收入，个人的钱要说“收入”。"}, {"text": "这个班的丰收很多，学生都很努力。", "explanation": "这里应该用〈人数〉。丰收不指人的数量，班里人多要说“人数多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“研究终于丰收了”指经过努力取得了成果。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“研究”是工作成果，不能“放假”，与“经过三年努力”的语境不符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能指研究取得的成果。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“研究”不能“生病”，这种主语与动词的搭配不当。"}], "explanations": {"丰收": "正确。“研究终于丰收了”指经过努力取得了成果。", "放假": "语义：“研究”是工作成果，不能“放假”，与“经过三年努力”的语境不符。", "下雨": "语义：“下雨”是天气现象，不能指研究取得的成果。", "生病": "搭配：“研究”不能“生病”，这种主语与动词的搭配不当。"}, "sentence_index": 6, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的房价这几年丰收得很快。", "explanation": "这里应该用〈上涨〉。丰收指农作物或成果的收成，房价的变化要说“上涨”。"}, {"text": "这个孩子长得很丰收。", "explanation": "这里应该用〈健壮〉。丰收用于收成，不说人长得丰收，应说“健壮”。"}, {"text": "他的技术很丰收，大家都很佩服。", "explanation": "这里应该用〈高超〉。丰收不描述技术水平，技术好要说“高超”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年苹果获得了太丰收。", "corrected_sentence": "今年苹果获得了大丰收。", "error_description": "修饰错误：“丰收”前应用形容词“大”，说“大丰收”；“太”是副词，不能修饰“丰收”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民伯伯今年终于迎来了一个丰收。", "corrected_sentence": "农民伯伯今年终于迎来了一场丰收。", "error_description": "量词错误：“丰收”作一次收成时量词应说“一场丰收”，不能用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
