INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指季节或特定的时间阶段。", "primary_collocate": null, "pronunciation": "shí jié", "ipa": "ʂɻ̩˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "时节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "清明时节，南方常常下雨。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋收时节，农民们在田里忙着收稻子。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到春耕时节，村里的人都起得很早。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时节，山上的花开得最好。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在多雨的时节，出门最好带一把伞。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桂花开放的时节，满城都是香味。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天是最冷的时节，大家都穿上了厚衣服。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子成熟的时节，田野一片金黄。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在寒冷的时节里，这种花依然开着。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时节：季节或特定的时间阶段，如丰收时节、清明时节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。"}, {"text": "诗节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}, {"text": "石阶", "is_correct": false, "explanation": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。"}, {"text": "十届", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。"}, {"text": "十级", "is_correct": false, "explanation": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}], "explanations": {"时节": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。", "诗节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。", "石阶": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。", "十届": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。", "十级": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指特定时段，与前文的“战时”并列，只有它能填入空格。"}, {"text": "田地", "is_correct": false, "explanation": "语义：“田地”指土地，不表示时段，不能与“战时”并列。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”指人，不指时段，不能作为“丰收”所限定的时间。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“丰收节奏”不成搭配，“节奏”指快慢的规律，不表示时段。"}], "explanations": {"时节": "正确：“时节”指特定时段，与前文的“战时”并列，只有它能填入空格。", "田地": "语义：“田地”指土地，不表示时段，不能与“战时”并列。", "人群": "语义：“人群”指人，不指时段，不能作为“丰收”所限定的时间。", "节奏": "搭配：“丰收节奏”不成搭配，“节奏”指快慢的规律，不表示时段。"}, "sentence_index": 0, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完全程的时节创了新纪录。", "explanation": "这里应该用〈时间〉。跑完全程所用的时长要说“时间”，时节指季节或一段时期。"}, {"text": "火车到站的时节是下午三点。", "explanation": "这里应该用〈时刻〉。时节指季节或较长的时段，不指具体的某个钟点。"}, {"text": "这次会议的时节定在下周三。", "explanation": "这里应该用〈日期〉。时节指季节或一段时期，不指某一天；定下具体哪一天要说“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。"}, {"text": "世界", "is_correct": false, "explanation": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。"}, {"text": "十戒", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。"}, {"text": "失节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。"}, {"text": "诗界", "is_correct": false, "explanation": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}], "explanations": {"时节": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。", "世界": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。", "十戒": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。", "失节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。", "诗界": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指季节，与“桂花开放”相合，“满城都是香味”也符合季节语境。"}, {"text": "空间", "is_correct": false, "explanation": "语义：“空间”指范围，不表示季节或时段，与“桂花开放”的时间语境不符。"}, {"text": "角落", "is_correct": false, "explanation": "语义：“角落”指局部位置，与“满城都是香味”的整体范围相矛盾。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听到的响声，不表示季节或时段，与“桂花开放”的时间语境不符。"}], "explanations": {"时节": "正确：“时节”指季节，与“桂花开放”相合，“满城都是香味”也符合季节语境。", "空间": "语义：“空间”指范围，不表示季节或时段，与“桂花开放”的时间语境不符。", "角落": "语义：“角落”指局部位置，与“满城都是香味”的整体范围相矛盾。", "声音": "语义：“声音”指听到的响声，不表示季节或时段，与“桂花开放”的时间语境不符。"}, "sentence_index": 6, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司第三时节的利润增加了。", "explanation": "这里应该用〈季度〉。时节不与“第三”这样的序数搭配来表示第几个季度。"}, {"text": "这项工作要花很多时节。", "explanation": "这里应该用〈时间〉。时节指季节或特定时段，不能像时间那样用“很多”来计量时长。"}, {"text": "我的手机上的时节总是不准。", "explanation": "这里应该用〈时钟〉。时节指季节或一段时间，不指计时的钟表；说手机的计时不准要用“时钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只美好的时节，适合出去散步。", "corrected_sentence": "这是一个美好的时节，适合出去散步。", "error_description": "量词错误：“时节”前应用“个”，不能用“只”（“只”多用于动物或单件小物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在春天的时节上，树叶依然绿着。", "corrected_sentence": "在春天的时节里，树叶依然绿着。", "error_description": "方位词错误：“时节”是时间段，表示范围内应用“里”，“时节上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：不死板、能根据情况变通，与“僵化”构成反义。"}, {"text": "繁荣", "is_correct": false, "explanation": "无关：繁荣指兴旺发达，与僵化没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：明亮形容光线或颜色，与僵化不构成反义。"}, {"text": "辛苦", "is_correct": false, "explanation": "无关：辛苦指劳累，与僵化不是反义关系。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：不死板、能根据情况变通，与“僵化”构成反义。", "繁荣": "无关：繁荣指兴旺发达，与僵化没有反义关系。", "明亮": "无关：明亮形容光线或颜色，与僵化不构成反义。", "辛苦": "无关：辛苦指劳累，与僵化不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：不死板、可以变通，与僵化相对。"}, {"text": "寂静", "is_correct": false, "explanation": "无关：寂静指没有声音，与僵化不构成反义。"}, {"text": "漂浮", "is_correct": false, "explanation": "无关：漂浮指浮在水面或空中，与僵化没有反义关系。"}, {"text": "清澈", "is_correct": false, "explanation": "无关：清澈形容水或眼神干净透明，与僵化不相对。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：不死板、可以变通，与僵化相对。", "寂静": "无关：寂静指没有声音，与僵化不构成反义。", "漂浮": "无关：漂浮指浮在水面或空中，与僵化没有反义关系。", "清澈": "无关：清澈形容水或眼神干净透明，与僵化不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容思想、方法、制度等变得死板、不灵活。", "primary_collocate": null, "pronunciation": "jiāng huà", "ipa": "tɕjɑŋ˥ xu̯ɑ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "僵化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的想法已经僵化了。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理方法僵化，公司很难进步。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师不让思想僵化，常常鼓励我们提问。", "target_word": "僵化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制度太僵化，年轻人都不愿意留下。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教学方式僵化，学生很快就没了兴趣。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了以后，想法容易变得僵化。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要多学习，不要让头脑僵化。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套规定已经僵化，需要改一改了。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作方法太僵化，不会根据情况调整。", "target_word": "僵化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "僵化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "僵化：思想、方法、制度变得死板不灵活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化（jiānghuà）：思想、方法、制度变得死板、不灵活。"}, {"text": "讲话", "is_correct": false, "explanation": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。"}, {"text": "钢化", "is_correct": false, "explanation": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。"}, {"text": "姜花", "is_correct": false, "explanation": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}], "explanations": {"僵化": "僵化（jiānghuà）：思想、方法、制度变得死板、不灵活。", "讲话": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。", "强化": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。", "钢化": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。", "姜花": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}, "sentence_index": null, "correct_answer": "僵化"}, "level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：形容思想或制度死板、不灵活，与“可被调用的意义资源”相对，句中说得通。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：档案只是记录，不会欢呼，“欢呼的事实档案”说不通。"}, {"text": "咆哮", "is_correct": false, "explanation": "搭配：“咆哮”多用于野兽或愤怒的人，不能修饰档案。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：档案无法哭泣，“哭泣的事实档案”与句意不符。"}], "explanations": {"僵化": "僵化：形容思想或制度死板、不灵活，与“可被调用的意义资源”相对，句中说得通。", "欢呼": "语义：档案只是记录，不会欢呼，“欢呼的事实档案”说不通。", "咆哮": "搭配：“咆哮”多用于野兽或愤怒的人，不能修饰档案。", "哭泣": "语义：档案无法哭泣，“哭泣的事实档案”与句意不符。"}, "sentence_index": 0, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的天气很僵化，我们都不敢出门。", "explanation": "这里把〈僵化〉当成〈僵硬〉（变硬、不能动）来形容天气；僵化的本义不适用于天气，天气不会变得死板。"}, {"text": "今天的心情很僵化，一整天都不想说话。", "explanation": "这里把〈僵化〉当成〈僵〉（如「气氛很僵」中紧张、僵持的意思）来形容心情；僵化没有这个义项，心情不会僵化。"}, {"text": "这锅汤的味道很僵化，大家都喝完了。", "explanation": "这里把〈僵化〉当成〈僵硬〉（变硬、不能动）来形容味道；味道不会变硬，僵化不用于描述味觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：说想法随年龄变得固定不变，句中合理。"}, {"text": "肥胖", "is_correct": false, "explanation": "搭配：“肥胖”形容人或动物的体态，不能修饰想法。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，想法不能说鲜艳。"}, {"text": "融化", "is_correct": false, "explanation": "语义：想法不会融化，“容易融化”与句意不符。"}], "explanations": {"僵化": "僵化：说想法随年龄变得固定不变，句中合理。", "肥胖": "搭配：“肥胖”形容人或动物的体态，不能修饰想法。", "鲜艳": "搭配：“鲜艳”形容颜色，想法不能说鲜艳。", "融化": "语义：想法不会融化，“容易融化”与句意不符。"}, "sentence_index": 6, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的光很僵化，屋子里很暗。", "explanation": "这里把〈僵化〉当成〈昏暗〉（描写光线的）来用；光线不会变得死板，僵化不能用来形容光。"}, {"text": "这幅画的颜色很僵化，我很喜欢。", "explanation": "这里把〈僵化〉当成形容颜色单调的词来用；僵化只用于思想、方法、制度等失去变通，不能形容颜色。"}, {"text": "这座楼的高度很僵化，一直没有变过。", "explanation": "这里把〈僵化〉当成〈稳定〉（不变）来形容高度；高度是尺寸，不会变得死板，僵化不用于描述尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些规定慢慢僵化来了，大家都很不满意。", "corrected_sentence": "这些规定慢慢僵化起来了，大家都很不满意。", "error_description": "错误在补语：表示逐渐变得死板要用趋向补语“起来”，不能只说“僵化来”；正确说法是“僵化起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的想法越来僵化，我们都很担心。", "corrected_sentence": "他的想法越来越僵化，我们都很担心。", "error_description": "语法错误：漏掉了“越”，“越来”后必须接“越”构成固定格式“越来越”，应说“越来越僵化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
