INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12395, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指机关或企事业单位分类保存的各种文件和材料。", "primary_collocate": null, "pronunciation": "dàng àn", "ipa": "tɑŋ˥˩ ɑn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的员工档案都在人事部。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把我的档案送到新单位。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校保存着每个学生的档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的档案里有一份工作证明。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在查那个人的档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为病人建立了健康档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想看看这个孩子的档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些档案已经保存了三十年。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，他的档案转到了老家。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在人事部门工作，每天整理档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份档案", "label": "量词"}, {"form": "档案馆", "label": "复合"}, {"form": "檔案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机关单位分类保存的文件材料（人事档案、健康档案）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
